import type { HubCredentials, HubSettings } from '../types/hub'
import { DEFAULT_SETTINGS } from '../types/hub'
import type { Favorite } from './favoritesService'
import { favoritesService } from './favoritesService'
import { getValue } from './hubApi'

export interface UserProfile {
  version: number
  settings?: Partial<HubSettings>
  favorites?: Favorite[]
  preferences?: {
    filterLines?: boolean
  }
}

const FILENAME = 'defaults.json'

export const profileService = {
  /** Gather all current user state into a profile object. */
  collect(host: string, settings: HubSettings): UserProfile {
    return {
      version: 1,
      settings,
      favorites: favoritesService.list(host),
      preferences: {
        filterLines: localStorage.getItem('hub.search.filterLines') === '1',
      },
    }
  },

  /** Apply a profile to localStorage for the given host. */
  apply(profile: UserProfile, host: string): void {
    if (Array.isArray(profile.favorites)) {
      favoritesService.setAll(host, profile.favorites)
    }
    if (profile.preferences?.filterLines !== undefined) {
      localStorage.setItem('hub.search.filterLines', profile.preferences.filterLines ? '1' : '0')
    }
  },

  /** Merge profile settings on top of the current defaults, returning merged HubSettings. */
  mergeSettings(profile: UserProfile): HubSettings {
    return { ...DEFAULT_SETTINGS, ...(profile.settings ?? {}) } as HubSettings
  },

  /**
   * Try to load defaults.json.
   * 1. Hub backend      (Drives/Current/opt/minova/defaults.json via getvalue API)
   * 2. Frontend server  (/defaults.json)
   * Returns null if neither source has the file.
   */
  async fetchDefaults(credentials?: HubCredentials): Promise<UserProfile | null> {
    // 1. Hub backend
    if (credentials) {
      try {
        const text = await getValue(credentials, 'Drives/Current/opt/minova/defaults.json', 'text')
        return JSON.parse(text) as UserProfile
      } catch { /* fall through */ }
    }

    // 2. Frontend server
    try {
      const resp = await fetch(`/${FILENAME}?_=${Date.now()}`)
      if (resp.ok) return (await resp.json()) as UserProfile
    } catch { /* fall through */ }

    return null
  },

  /** Trigger a browser download of the profile as defaults.json. */
  download(profile: UserProfile): void {
    const blob = new Blob([JSON.stringify(profile, null, 2)], { type: 'application/json' })
    const url  = URL.createObjectURL(blob)
    const a    = Object.assign(document.createElement('a'), { href: url, download: FILENAME })
    a.click()
    URL.revokeObjectURL(url)
  },
}
