import type { ModelNode } from '../types/hub'
import { strTrue, nodeAttr } from '../types/hub'
import { isChoice, isBool, isLocalFile, isBinary, isPassword, isTimestamp, isUrl, isList, isMap, isValueNode, parseSizeBytes, formatTimestamp } from '../services/hubApi'

interface Props {
  node: ModelNode
  readonly?: boolean
  onChange: (value: string) => void
  onDownload?: (openInTab: boolean) => void
}

export function ValueEditor({ node, readonly, onChange, onDownload }: Props) {
  const isReadonly = readonly || strTrue(node.readonly)

  if (isLocalFile(node) || isBinary(node)) {
    return (
      <span className="value-binary">
        {node.preview && <span className="value-display">{node.preview}</span>}
        <button className="value-download-btn" onClick={e => { e.stopPropagation(); onDownload?.(e.ctrlKey || e.metaKey) }} title="Download / Ctrl+click to open in tab">↓</button>
      </span>
    )
  }

  if (isChoice(node) && node.choices) {
    const current = node.value ?? node.preview ?? ''
    return (
      <select
        value={current}
        disabled={isReadonly}
        onChange={e => onChange(e.target.value)}
        className="value-select"
        onClick={e => e.stopPropagation()}
      >
        {node.choices.split(';').filter(Boolean).map(opt => (
          <option key={opt} value={opt}>{opt}</option>
        ))}
      </select>
    )
  }

  if (isPassword(node)) {
    const len = Math.min(Math.max((node.value ?? node.preview ?? '').length, 6), 12)
    return <span className="value-display value-password">{'•'.repeat(len)}</span>
  }

  if (isTimestamp(node)) {
    return <span className="value-display">{formatTimestamp(node.value ?? node.preview)}</span>
  }

  if (isUrl(node)) {
    const url = node.value ?? node.preview ?? ''
    const display = url.replace(/^https?:\/\//, '')
    const truncated = display.length > 40 ? display.slice(0, 38) + '…' : display
    return (
      <span className="value-binary">
        <span className="value-display">{truncated}</span>
        <a className="value-url" href={url} target="_blank" rel="noreferrer"
           onClick={e => e.stopPropagation()} title={url}>↗</a>
      </span>
    )
  }

  if (isList(node) || isMap(node)) {
    const raw = node.value ?? node.preview ?? ''
    try {
      const parsed = JSON.parse(raw)
      if (Array.isArray(parsed)) {
        const items = parsed.slice(0, 4).map(v => String(v))
        const suffix = parsed.length > 4 ? `, +${parsed.length - 4}` : ''
        return <span className="value-display value-collection">[{items.join(', ')}{suffix}]</span>
      } else if (parsed && typeof parsed === 'object') {
        const keys = Object.keys(parsed)
        const items = keys.slice(0, 3).map(k => `${k}: ${parsed[k]}`)
        const suffix = keys.length > 3 ? `, +${keys.length - 3}` : ''
        return <span className="value-display value-collection">&#123;{items.join(', ')}{suffix}&#125;</span>
      }
    } catch { /* fall through to raw display */ }
    return <span className="value-display value-collection">{raw}</span>
  }

  if (isBool(node)) {
    return (
      <input
        type="checkbox"
        checked={strTrue(node.value as string)}
        disabled={isReadonly}
        onChange={e => onChange(String(e.target.checked))}
        onClick={e => e.stopPropagation()}
        className="value-checkbox"
      />
    )
  }

  if (isValueNode(node) && !isReadonly) {
    const display = node.preview ?? node.value ?? ''
    return (
      <input
        type="text"
        defaultValue={display}
        onBlur={e => { if (e.target.value !== display) onChange(e.target.value) }}
        onKeyDown={e => { if (e.key === 'Enter') (e.target as HTMLInputElement).blur() }}
        onClick={e => e.stopPropagation()}
        className="value-input"
      />
    )
  }

  // Read-only display
  const display = node.preview ?? node.value ?? ''
  const truncated = display.length > 120 ? display.substring(0, 120) + ' …' : display
  return <span className="value-display" title={display.length > 120 ? display : undefined}>{truncated}</span>
}

// eslint-disable-next-line react-refresh/only-export-components
export function fileSizeMB(node: ModelNode): number | null {
  if (!isLocalFile(node) && !isBinary(node)) return null
  const szAttr = nodeAttr(node, 'contentLength')
  if (szAttr != null) {
    const n = parseFloat(szAttr)
    if (!isNaN(n)) return n / (1024 * 1024)
  }
  const bytes = parseSizeBytes(node.preview)
  return bytes !== null ? bytes / (1024 * 1024) : null
}
