export type FavoriteKind = 'value' | 'file' | 'directory'

export interface Favorite {
  path: string
  name: string
  kind: FavoriteKind
  group: string
  addedAt: number
}

const CHANGE_EVENT = 'hub-favorites-changed'

function storageKey(host: string): string {
  try { return `hub.favorites.${btoa(host)}` }
  catch { return `hub.favorites.${encodeURIComponent(host)}` }
}

export const favoritesService = {
  list(host: string): Favorite[] {
    try { return JSON.parse(localStorage.getItem(storageKey(host)) ?? '[]') }
    catch { return [] }
  },

  add(host: string, fav: Omit<Favorite, 'addedAt'>): void {
    const list = this.list(host).filter(f => f.path !== fav.path)
    list.push({ ...fav, addedAt: Date.now() })
    localStorage.setItem(storageKey(host), JSON.stringify(list))
    window.dispatchEvent(new CustomEvent(CHANGE_EVENT, { detail: host }))
  },

  remove(host: string, path: string): void {
    const list = this.list(host).filter(f => f.path !== path)
    localStorage.setItem(storageKey(host), JSON.stringify(list))
    window.dispatchEvent(new CustomEvent(CHANGE_EVENT, { detail: host }))
  },

  has(host: string, path: string): boolean {
    return this.list(host).some(f => f.path === path)
  },

  setAll(host: string, favs: Favorite[]): void {
    localStorage.setItem(storageKey(host), JSON.stringify(favs))
    window.dispatchEvent(new CustomEvent(CHANGE_EVENT, { detail: host }))
  },

  onChange(handler: () => void): () => void {
    window.addEventListener(CHANGE_EVENT, handler)
    return () => window.removeEventListener(CHANGE_EVENT, handler)
  },
}
