import { useState, useEffect, useMemo, useRef } from 'react'
import type { ModelNode, HubCredentials } from '../types/hub'
import { getNode } from '../services/hubApi'
import './ModelPreview.css'
import './SystemInfoPreview.css'

// ---- Cache ------------------------------------------------------------

const sysInfoCache = new Map<string, ModelNode>()
// eslint-disable-next-line react-refresh/only-export-components
export function clearSysInfoCache() { sysInfoCache.clear() }

// ---- Helpers ----------------------------------------------------------

function childVal(children: ModelNode[] | undefined, name: string): string {
  return children?.find(c => c.name === name)?.value ?? ''
}

function childNode(children: ModelNode[] | undefined, name: string): ModelNode | undefined {
  return children?.find(c => c.name === name)
}

function parseMemBytes(v: string): number {
  const m = v.trim().match(/^(\d+(?:\.\d+)?)\s*(k|m|g)?b?$/i)
  if (!m) return 0
  const n = parseFloat(m[1])
  const unit = (m[2] ?? '').toLowerCase()
  if (unit === 'k') return n * 1024
  if (unit === 'm') return n * 1024 * 1024
  if (unit === 'g') return n * 1024 * 1024 * 1024
  return n
}

function memColor(pct: number): string {
  if (pct < 0.5)  return '#22c55e'
  if (pct < 0.75) return '#f59e0b'
  if (pct < 0.9)  return '#f97316'
  return '#ef4444'
}

// ---- MemBar -----------------------------------------------------------

interface MemInfo { used: number; total: number; max: number; usedLabel: string; totalLabel: string; maxLabel: string }

function parseMemGroup(children: ModelNode[] | undefined): MemInfo | null {
  if (!children?.length) return null
  const usedLabel  = childVal(children, 'Used')
  const totalLabel = childVal(children, 'Total')
  const maxLabel   = childVal(children, 'Max')
  if (!usedLabel) return null
  return { used: parseMemBytes(usedLabel), total: parseMemBytes(totalLabel), max: parseMemBytes(maxLabel), usedLabel, totalLabel, maxLabel }
}

function MemBar({ mem }: { mem: MemInfo }) {
  const maxRef   = mem.max > 0 ? mem.max : mem.total
  const pctTotal = maxRef > 0 ? Math.min(mem.total / maxRef, 1) : 0
  const pctUsed  = maxRef > 0 ? Math.min(mem.used  / maxRef, 1) : 0
  const color    = memColor(mem.total > 0 ? mem.used / mem.total : 0)
  return (
    <div>
      <div className="si-membar-track">
        <div className="si-membar-alloc" style={{ width: `${(pctTotal * 100).toFixed(1)}%`, background: color }} />
        <div className="si-membar-used"  style={{ width: `${(pctUsed  * 100).toFixed(1)}%`, background: color }} />
      </div>
      <div className="si-membar-label">{mem.usedLabel} / {mem.totalLabel} <span className="si-muted">(max {mem.maxLabel})</span></div>
    </div>
  )
}

// ---- KVTable ----------------------------------------------------------

function KVTable({ rawValue }: { rawValue: string }) {
  const [filter, setFilter] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  const rows = useMemo(() => rawValue
    .split('\n')
    .map(l => l.trim())
    .filter(l => l.includes('='))
    .map(l => { const i = l.indexOf('='); return { k: l.slice(0, i), v: l.slice(i + 1) } }),
  [rawValue])

  const filtered = filter
    ? rows.filter(r => r.k.toLowerCase().includes(filter.toLowerCase()) || r.v.toLowerCase().includes(filter.toLowerCase()))
    : rows

  return (
    <div className="si-kv-wrap">
      <div className="si-kv-filter-row">
        <input
          ref={inputRef}
          className="si-kv-filter"
          placeholder={`Filter ${rows.length} entries…`}
          value={filter}
          onChange={e => setFilter(e.target.value)}
        />
        {filter && <button className="si-kv-clear" onClick={() => setFilter('')}>✕</button>}
      </div>
      <div className="si-kv-scroll">
        <table className="si-kv-table">
          <tbody>
            {filtered.map((r, i) => (
              <tr key={i} className="si-kv-row">
                <td className="si-kv-key">{r.k}</td>
                <td className="si-kv-val">{r.v}</td>
              </tr>
            ))}
          </tbody>
        </table>
        {filtered.length === 0 && <div className="si-kv-empty">No matches.</div>}
      </div>
    </div>
  )
}

// ---- IcRefresh --------------------------------------------------------

const IcRefresh = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/>
  </svg>
)

// ---- SysInfoPanel (shared, embeddable) --------------------------------

interface SysInfoPanelProps {
  path: string
  credentials: HubCredentials
  simpleMode: boolean
  onNavigate: (path: string) => void
  version?: number  // increment to force a cache-busting reload
}

export function SysInfoPanel({ path, credentials, simpleMode, onNavigate, version = 0 }: SysInfoPanelProps) {
  const cacheKey = `${credentials.host}::${path}`
  const [sysNode, setSysNode]     = useState<ModelNode | null>(() => sysInfoCache.get(cacheKey) ?? null)
  const [loading, setLoading]     = useState(false)
  const [loaded, setLoaded]       = useState(() => sysInfoCache.has(cacheKey))
  const [propsOpen, setPropsOpen] = useState(false)
  const [envOpen, setEnvOpen]     = useState(false)
  const prevVersionRef            = useRef(version)

  function doLoad(bust = false) {
    const key = `${credentials.host}::${path}`
    if (bust) sysInfoCache.delete(key)
    let cancelled = false
    setLoading(true)

    async function run() {
      // Warm up parent node first — backend uses internal caching and depth=2
      // returns incomplete data unless the parent path has been requested before.
      const parentPath = path.substring(0, path.lastIndexOf('/'))
      if (parentPath) await getNode(credentials, parentPath, 1).catch(() => {})
      if (cancelled) return
      try {
        const result = await getNode(credentials, path, 2)
        if (!cancelled) {
          sysInfoCache.set(key, result)
          setSysNode(result)
          setLoaded(true)
        }
      } catch { /* silent */ }
      finally { if (!cancelled) setLoading(false) }
    }

    run()
    return () => { cancelled = true }
  }

  useEffect(() => {
    const isVersionBump = prevVersionRef.current !== version
    prevVersionRef.current = version
    const key = `${credentials.host}::${path}`

    if (isVersionBump) {
      setSysNode(null); setLoaded(false)
      return doLoad(true)
    }
    // path / credentials / simpleMode changed
    const cached = sysInfoCache.get(key)
    if (cached) { setSysNode(cached); setLoaded(true); return }
    setSysNode(null); setLoaded(false); setPropsOpen(false); setEnvOpen(false)
    if (simpleMode) return doLoad()
  }, [path, credentials, simpleMode, version]) // eslint-disable-line react-hooks/exhaustive-deps

  // ---- Derived data ---------------------------------------------------
  const ch           = sysNode?.children ?? []
  const mem          = parseMemGroup(childNode(ch, 'Memory')?.children)
  const processors   = childVal(ch, 'Processors')
  const cpuLoad      = childVal(ch, 'Load')
  const inDocker     = childVal(ch, 'Within Docker')
  const javaGroup    = childNode(ch, 'Java')
  const javaCh       = javaGroup?.children ?? []
  const javaVer      = childVal(javaCh, 'Version')
  const javaExec     = childVal(javaCh, 'Executable')
  const javaProps    = childVal(javaCh, 'Properties')
  const javaEnv      = childVal(javaCh, 'Env')
  const instVersions = childNode(ch, 'Installed versions')?.children?.map(c => c.name ?? '').filter(Boolean) ?? []

  const netMap = useMemo(() => {
    const map = new Map<string, string>()
    for (const n of childNode(ch, 'Network')?.children ?? []) {
      const iface = n.help ?? 'unknown'
      const ip = n.value ?? ''
      if (!ip.includes(':') && !map.has(iface)) map.set(iface, ip)
    }
    return map
  }, [sysNode]) // eslint-disable-line react-hooks/exhaustive-deps

  const threadsGroup = childNode(ch, 'Threads')
  const threadTotal  = parseInt(String(threadsGroup?.childrenCount ?? '0'), 10) || 0
  const threadStates = useMemo(() => {
    const map = new Map<string, number>()
    for (const t of threadsGroup?.children ?? []) {
      const state = t.preview ?? 'UNKNOWN'
      map.set(state, (map.get(state) ?? 0) + 1)
    }
    return map
  }, [sysNode]) // eslint-disable-line react-hooks/exhaustive-deps

  // ---- Render ---------------------------------------------------------
  return (
    <>
      {!loaded && !loading && (
        <div className="si-cta-wrap">
          <button className="mp-svc-cta" onClick={() => doLoad()}>Load system info</button>
        </div>
      )}

      {loading && <div className="mp-loading">Loading…</div>}

      {loaded && (
        <div className="si-body">

          {mem && (
            <div className="si-section">
              <div className="si-row">
                <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Memory`)} title={`${path}/Memory`}>Memory</span>
                <div className="si-value si-value--full"><MemBar mem={mem} /></div>
              </div>
            </div>
          )}

          {(processors || cpuLoad || inDocker) && (
            <div className="si-section">
              {(processors || cpuLoad) && (
                <div className="si-row">
                  <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Processors`)} title={`${path}/Processors`}>CPU</span>
                  <div className="si-value">
                    {processors && <><span className="si-bold">{processors}</span> {parseInt(processors) === 1 ? 'core' : 'cores'}</>}
                    {cpuLoad && <span className="si-muted"> · Load: {cpuLoad}</span>}
                  </div>
                </div>
              )}
              {inDocker && (
                <div className="si-row">
                  <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Within Docker`)} title={`${path}/Within Docker`}>Docker</span>
                  <div className="si-value">
                    <span className={`si-badge${inDocker === 'true' ? ' si-badge--green' : ' si-badge--grey'}`}>
                      {inDocker === 'true' ? 'Yes' : 'No'}
                    </span>
                  </div>
                </div>
              )}
            </div>
          )}

          {threadTotal > 0 && (
            <div className="si-section">
              <div className="si-row">
                <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Threads`)} title={`${path}/Threads`}>Threads</span>
                <div className="si-value">
                  <span className="si-bold">{threadTotal}</span>
                  {[...threadStates.entries()].map(([state, count]) => (
                    <span key={state} className="si-muted"> · {count} {state}</span>
                  ))}
                </div>
              </div>
            </div>
          )}

          {netMap.size > 0 && (
            <div className="si-section">
              {[...netMap.entries()].map(([iface, ip]) => (
                <div key={iface} className="si-row">
                  <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Network`)} title={`${path}/Network`}>{iface}</span>
                  <div className="si-value si-value--mono">{ip}</div>
                </div>
              ))}
            </div>
          )}

          {(javaVer || javaExec || instVersions.length > 0) && (
            <div className="si-section">
              {(javaVer || javaExec) && (
                <div className="si-row">
                  <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Java`)} title={`${path}/Java`}>Java</span>
                  <div className="si-value">
                    {javaVer && <span className="si-bold">v{javaVer}</span>}
                    {javaExec && <span className="si-muted"> · {javaExec}</span>}
                  </div>
                </div>
              )}
              {instVersions.length > 0 && (
                <div className="si-row">
                  <span className="si-label si-label--link" onClick={() => onNavigate(`${path}/Installed versions`)} title={`${path}/Installed versions`}>Installed</span>
                  <div className="si-value">
                    {instVersions.map(v => (
                      <span key={v} className="si-chip si-chip--link" onClick={() => onNavigate(`${path}/Installed versions/${v}`)} title={`${path}/Installed versions/${v}`}>{v}</span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {javaProps && (
            <>
              <button className={`mp-service-toggle${propsOpen ? ' mp-service-toggle--open' : ''}`} onClick={() => setPropsOpen(v => !v)}>
                <span className="mp-toggle-arrow">{propsOpen ? '▾' : '▸'}</span>
                Java Properties
              </button>
              {propsOpen && <KVTable rawValue={javaProps} />}
            </>
          )}

          {javaEnv && (
            <>
              <button className={`mp-service-toggle${envOpen ? ' mp-service-toggle--open' : ''}`} onClick={() => setEnvOpen(v => !v)}>
                <span className="mp-toggle-arrow">{envOpen ? '▾' : '▸'}</span>
                Java Env
              </button>
              {envOpen && <KVTable rawValue={javaEnv} />}
            </>
          )}

        </div>
      )}
    </>
  )
}

// ---- Standalone wrapper (keeps its own toolbar) -----------------------

interface Props {
  path: string
  node: ModelNode
  credentials: HubCredentials
  simpleMode: boolean
  onNavigate: (path: string) => void
  showJson?: boolean
}

export function SystemInfoPreview({ path, node, credentials, onNavigate, showJson = false }: Props) {
  const [version, setVersion] = useState(0)

  return (
    <div className="sys-info-preview">
      <div className="mp-toolbar">
        <span className="mp-toolbar-title">System Info</span>
        <button className="mp-reload-btn" onClick={() => setVersion(v => v + 1)} title="Reload">
          <IcRefresh />
        </button>
      </div>
      <SysInfoPanel path={path} credentials={credentials} simpleMode={true} onNavigate={onNavigate} version={version} />
      {showJson && (
        <div className="detail-accordion">
          <div className="accordion-header open"><span className="accordion-arrow" />JSON</div>
          <div className="accordion-body">
            <pre className="json-view">{JSON.stringify(node, null, 2)}</pre>
          </div>
        </div>
      )}
    </div>
  )
}
