import { useState, useEffect } from 'react'
import type { ModelNode, HubCredentials } from '../types/hub'
import { strTrue, strNum, nodeAttr } from '../types/hub'
import { getNode, getValue, setValue, callCommand } from '../services/hubApi'
import { logStore } from '../services/logStore'
import { ContextMenu } from './ContextMenu'
import type { MenuItem } from './ContextMenu'
import './IssuesPreview.css'

// ---- Classification helpers -------------------------------------------

function isSolution(n: ModelNode): boolean {
  const priority = nodeAttr(n, 'priority')
  return (n.localType === 'ch.minova.appmodel.remote.RemoteCommand' ||
          n.remoteType === 'ch.minova.appmodel.remote.RemoteCommand' ||
          n.type === 'ch.minova.appmodel.remote.RemoteCommand') &&
         priority != null && priority !== ''
}

function isSeverityMeta(n: ModelNode): boolean {
  return n.name === 'Severity' && !!n.choices
}

type IssueSeverity = 'error' | 'warning' | 'info' | 'debug'

function getSeverity(n: ModelNode): IssueSeverity {
  const ico = (n.icon ?? nodeAttr(n, 'iconDataPath') ?? '').toLowerCase()
  if (ico.includes('error')) return 'error'
  if (ico.includes('warning') || ico.includes('warn')) return 'warning'
  if (ico.includes('hint') || ico.includes('debug')) return 'debug'
  return 'info'
}

function getIssueLabel(n: ModelNode): string {
  return n.text ?? n.preview ?? n.name ?? ''
}

function nodeSeg(n: ModelNode): string {
  return n.name && n.name !== '' ? n.name : String(n.rid ?? '_')
}

// ---- Pre-process loaded children --------------------------------------

interface SplitChildren {
  solutions: ModelNode[]
  subIssues: ModelNode[]
}

function splitChildren(children: ModelNode[] | undefined): SplitChildren {
  if (!children?.length) return { solutions: [], subIssues: [] }
  const solutions: ModelNode[] = []
  const subIssues: ModelNode[] = []
  for (const c of children) {
    if (isSeverityMeta(c)) continue
    if (isSolution(c)) solutions.push(c)
    else subIssues.push(c)
  }
  solutions.sort((a, b) => Number(nodeAttr(a, 'priority') ?? 0) - Number(nodeAttr(b, 'priority') ?? 0))
  return { solutions, subIssues }
}

