// ---- Severity badge ---------------------------------------------------

function SevBadge({ sev }: { sev: IssueSeverity }) {
  return <span className={`iss-sev iss-sev--${sev}`} title={sev} />
}

// ---- Solution icon emoji mapping -------------------------------------

function solIcon(icon?: string): string {
  switch ((icon ?? '').toLowerCase()) {
    case 'install': return '↓'
    case 'db':      return '⊞'
    case 'copy':    return '⎘'
    default:        return '↺'
  }
}

// ---- IssueTreeNode (recursive) ----------------------------------------

interface IssueTreeNodeProps {
  node: ModelNode
  path: string
  depth: number
  childrenMap: Map<string, SplitChildren>
  expanded: Set<string>
  loadingSet: Set<string>
  onToggle: (path: string, node: ModelNode) => void
  onRightClick: (e: React.MouseEvent, path: string, solutions: ModelNode[]) => void
}

function IssueTreeNode({ node, path, depth, childrenMap, expanded, loadingSet, onToggle, onRightClick }: IssueTreeNodeProps) {
  const sev   = getSeverity(node)
  const label = getIssueLabel(node)
  const desc  = nodeAttr(node, 'description')

  const loaded    = childrenMap.has(path)
  const split     = loaded ? childrenMap.get(path)! : splitChildren(node.children)
  const isExpanded = expanded.has(path)
  const isLoading  = loadingSet.has(path)

  // Can expand if there are known sub-issues OR if unloaded children exist
  const canExpand = split.subIssues.length > 0 ||
                    (!loaded && strNum(node.childrenCount, 0) > 0)

  const hasSolutions = split.solutions.length > 0 ||
                       (!loaded && strTrue(node.hasCommands) && strNum(node.childrenCount, 0) > 0)

  return (
    <div className="iss-node">
      <div
        className={`iss-row iss-row--d${Math.min(depth, 4)}`}
        onContextMenu={e => { e.preventDefault(); e.stopPropagation(); onRightClick(e, path, split.solutions) }}
        title={desc ? `${label}\n\n${desc}` : undefined}
      >
        <button
          className={`iss-expand${canExpand ? '' : ' iss-expand--leaf'}`}
          onClick={() => canExpand && onToggle(path, node)}
          disabled={!canExpand || isLoading}
          tabIndex={-1}
        >
          {isLoading ? '…' : canExpand ? (isExpanded ? '▾' : '▸') : ''}
        </button>
        <SevBadge sev={sev} />
        <span className="iss-label">{label}</span>
        {hasSolutions && (
          <span className="iss-sol-hint" title="Has solutions — right-click">
            <IcWrench />
          </span>
        )}
      </div>
      {isExpanded && split.subIssues.length > 0 && (
        <div className="iss-children">
          {split.subIssues.map(child => {
            const childPath = `${path}/${nodeSeg(child)}`
            return (
              <IssueTreeNode
                key={childPath}
                node={child}
                path={childPath}
                depth={depth + 1}
                childrenMap={childrenMap}
                expanded={expanded}
                loadingSet={loadingSet}
                onToggle={onToggle}
                onRightClick={onRightClick}
              />
            )
          })}
        </div>
      )}
    </div>
  )
}

// ---- IssuesPanel (embeddable) -----------------------------------------

interface IssuesPanelProps {
  remotePath: string
  appName?: string
  credentials: HubCredentials
  onNavigate: (path: string) => void
  version?: number
}

export function IssuesPanel({ remotePath, appName, credentials, onNavigate, version = 0 }: IssuesPanelProps) {
  const issuesBase     = `${remotePath}/Deployment/Issues`
  const issuesListPath = `${issuesBase}/Issues`

  const [active, setActive]           = useState<boolean | null>(null)
  const [toggling, setToggling]       = useState(false)
  const [issueRoot, setIssueRoot]     = useState<ModelNode | null>(null)
  const [loading, setLoading]         = useState(false)
  const [childrenMap, setChildrenMap] = useState<Map<string, SplitChildren>>(new Map())
  const [expanded, setExpanded]       = useState<Set<string>>(new Set())
  const [loadingSet, setLoadingSet]   = useState<Set<string>>(new Set())
  const [ctxMenu, setCtxMenu]         = useState<{ x: number; y: number; items: MenuItem[] } | null>(null)

  // ---- Initial load ---------------------------------------------------

  useEffect(() => {
    let cancelled = false

    async function init() {
      setActive(null)
      setIssueRoot(null)
      setChildrenMap(new Map())
      setExpanded(new Set())
      try {
        const val = await getValue(credentials, `${issuesBase}/Active`)
        if (cancelled) return
        const isActive = val === 'true'
        setActive(isActive)
        if (!isActive) return
        await fetchIssues(cancelled)
      } catch {
        if (!cancelled) setActive(false)
      }
    }

    async function fetchIssues(isCancelled: boolean) {
      setLoading(true)
      try {
        await getNode(credentials, issuesBase, 1).catch(() => {})
        if (isCancelled) return
        const root = await getNode(credentials, issuesListPath, 2)
        if (isCancelled) return
        setIssueRoot(root)
        setChildrenMap(buildChildrenMap(root, issuesListPath))
      } catch (err) {
        if (!isCancelled) logStore.add({ severity: 'error', text: `Issues load: ${err instanceof Error ? err.message : String(err)}` })
      } finally {
        if (!isCancelled) setLoading(false)
      }
    }

    init()
    return () => { cancelled = true }
  }, [remotePath, credentials.host, version]) // eslint-disable-line react-hooks/exhaustive-deps

  function buildChildrenMap(root: ModelNode, rootPath: string): Map<string, SplitChildren> {
    const map = new Map<string, SplitChildren>()
    for (const group of root.children ?? []) {
      const groupPath = `${rootPath}/${nodeSeg(group)}`
      map.set(groupPath, splitChildren(group.children))
      for (const sub of (group.children ?? []).filter(c => !isSolution(c) && !isSeverityMeta(c))) {
        if ((sub.children?.length ?? 0) > 0) {
          map.set(`${groupPath}/${nodeSeg(sub)}`, splitChildren(sub.children))
        }
      }
    }
    return map
  }

  // ---- Toggle active --------------------------------------------------

  async function handleToggle() {
    if (toggling || active === null) return
    const newActive = !active
    setToggling(true)
    try {
      await setValue(credentials, `${issuesBase}/Active`, String(newActive))
      setActive(newActive)
      if (newActive) {
        try { await callCommand(credentials, `${issuesBase}/Refresh`, {}) } catch { /* ignore */ }
        setLoading(true)
        await getNode(credentials, issuesBase, 1).catch(() => {})
        const root = await getNode(credentials, issuesListPath, 2)
        setIssueRoot(root)
        setChildrenMap(buildChildrenMap(root, issuesListPath))
        setLoading(false)
      } else {
        setIssueRoot(null)
        setChildrenMap(new Map())
        setExpanded(new Set())
      }
    } catch (err) {
      logStore.add({ severity: 'error', text: `Issues toggle: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setToggling(false)
      setLoading(false)
    }
  }

  // ---- Manual refresh -------------------------------------------------

  async function handleRefreshIssues() {
    if (loading || active !== true) return
    setLoading(true)
    try {
      await callCommand(credentials, `${issuesBase}/Refresh`, {})
    } catch { /* ignore */ }
    try {
      await getNode(credentials, issuesBase, 1).catch(() => {})
      const root = await getNode(credentials, issuesListPath, 2)
      setIssueRoot(root)
      setChildrenMap(buildChildrenMap(root, issuesListPath))
    } catch (err) {
      logStore.add({ severity: 'error', text: `Issues refresh: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setLoading(false)
    }
  }

  // ---- Lazy expand ----------------------------------------------------

  async function handleToggleExpand(path: string, _node: ModelNode) {
    if (expanded.has(path)) {
      setExpanded(prev => { const s = new Set(prev); s.delete(path); return s })
      return
    }
    if (childrenMap.has(path)) {
      setExpanded(prev => new Set([...prev, path]))
      return
    }
    setLoadingSet(prev => new Set([...prev, path]))
    try {
      const parent = path.substring(0, path.lastIndexOf('/'))
      if (parent) await getNode(credentials, parent, 1).catch(() => {})
      const loaded = await getNode(credentials, path, 2)
      setChildrenMap(prev => {
        const map = new Map(prev)
        map.set(path, splitChildren(loaded.children))
        for (const child of (loaded.children ?? []).filter(c => !isSolution(c) && !isSeverityMeta(c))) {
          if ((child.children?.length ?? 0) > 0) {
            map.set(`${path}/${nodeSeg(child)}`, splitChildren(child.children))
          }
        }
        return map
      })
      setExpanded(prev => new Set([...prev, path]))
    } catch (err) {
      logStore.add({ severity: 'error', text: `Load children: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setLoadingSet(prev => { const s = new Set(prev); s.delete(path); return s })
    }
  }

  // ---- Context menu (right-click solutions) ---------------------------

  function handleRightClick(e: React.MouseEvent, issuePath: string, solutions: ModelNode[]) {
    const items: MenuItem[] = []
    if (solutions.length > 0) {
      items.push({ label: '— Solutions —', cmd: '__sep', disabled: true })
      for (const sol of solutions) {
        const solPath = `${issuePath}/${nodeSeg(sol)}`
        items.push({
          label: sol.name ?? '',
          icon: solIcon(sol.icon),
          cmd: `sol:${solPath}`,
        })
      }
      items.push({ label: '---', cmd: '---' })
    }
    items.push({ label: 'Navigate to in tree', icon: '→', cmd: `nav:${issuePath}` })

    setCtxMenu({ x: e.clientX, y: e.clientY, items })
  }

  async function handleCtxSelect(cmd: string) {
    setCtxMenu(null)
    if (cmd.startsWith('nav:')) {
      onNavigate(cmd.slice(4))
      return
    }
    if (cmd.startsWith('sol:')) {
      const solPath = cmd.slice(4)
      try {
        await callCommand(credentials, solPath, {})
        logStore.add({ severity: 'info', text: `Applied: ${solPath.split('/').pop()}` })
        await handleRefreshIssues()
      } catch (err) {
        logStore.add({ severity: 'error', text: `Solution failed: ${err instanceof Error ? err.message : String(err)}` })
      }
    }
  }

  // ---- Render ---------------------------------------------------------

  const groups = issueRoot?.children ?? []
  const issueCount = strNum(issueRoot?.childrenCount, groups.length)

  return (
    <div className="iss-panel">
      <div className="iss-controls">
        <button
          className={`iss-refresh-btn${loading ? ' iss-spinning' : ''}`}
          onClick={handleRefreshIssues}
          disabled={loading || active !== true}
          title="Refresh Issues"
        >
          <IcRefreshIssues />
          Refresh Issues
        </button>
        <span className="iss-spacer" />
        {appName && <span className="iss-app-chip" title="Application">{appName}</span>}
        {active === true && issueCount > 0 && <span className="iss-count">{issueCount}</span>}
        <button
          className={`iss-toggle${active === true ? ' iss-toggle--on' : ''}`}
          onClick={handleToggle}
          disabled={toggling || active === null}
          title={active === true ? 'Deactivate issue scanner' : 'Activate issue scanner'}
        >
          {toggling ? '…' : active === true ? 'Active' : 'Inactive'}
        </button>
      </div>

      {active === null && <div className="iss-msg">Loading…</div>}
      {active === false && (
        <div className="iss-msg iss-msg--off">Issue scanner inactive — toggle to activate.</div>
      )}
      {active === true && loading && groups.length === 0 && (
        <div className="iss-msg">Loading issues…</div>
      )}
      {active === true && !loading && groups.length === 0 && (
        <div className="iss-msg iss-msg--ok">No issues found.</div>
      )}
      {groups.length > 0 && (
        <div className="iss-tree">
          {groups.map(group => {
            const groupPath = `${issuesListPath}/${nodeSeg(group)}`
            return (
              <IssueTreeNode
                key={groupPath}
                node={group}
                path={groupPath}
                depth={0}
                childrenMap={childrenMap}
                expanded={expanded}
                loadingSet={loadingSet}
                onToggle={handleToggleExpand}
                onRightClick={handleRightClick}
              />
            )
          })}
        </div>
      )}

      {ctxMenu && (
        <ContextMenu
          x={ctxMenu.x}
          y={ctxMenu.y}
          items={ctxMenu.items}
          onSelect={handleCtxSelect}
          onClose={() => setCtxMenu(null)}
        />
      )}
    </div>
  )
}

// ---- Standalone wrapper for HubDetail ----------------------------------

interface StandaloneProps {
  path: string
  node: ModelNode
  credentials: HubCredentials
  onNavigate: (path: string) => void
  showJson?: boolean
}

export function IssuesPreview({ path, node, credentials, onNavigate, showJson = false }: StandaloneProps) {
  const [version, setVersion] = useState(0)
  const [appName, setAppName] = useState<string | undefined>(undefined)

  const remotePath = (() => {
    const idx = path.indexOf('/Deployment/Issues')
    return idx > 0 ? path.slice(0, idx) : ''
  })()

  useEffect(() => {
    if (!remotePath) return
    let cancelled = false
    getValue(credentials, `${remotePath}/Deployment/DeploymentInfo/Application`)
      .then(v => { if (!cancelled && v) setAppName(v) })
      .catch(() => {})
    return () => { cancelled = true }
  }, [remotePath, credentials.host]) // eslint-disable-line react-hooks/exhaustive-deps

  if (!remotePath) return null

  return (
    <div className="sys-info-preview">
      <div className="mp-toolbar">
        <span className="mp-toolbar-title">Issues</span>
        <button className="mp-reload-btn" onClick={() => setVersion(v => v + 1)} title="Reload Issues">
          <IcRefreshIssues />
        </button>
      </div>
      <IssuesPanel
        remotePath={remotePath}
        appName={appName}
        credentials={credentials}
        onNavigate={onNavigate}
        version={version}
      />
      {showJson && (
        <div className="detail-accordion">
          <div className="accordion-header open"><span className="accordion-arrow" />JSON</div>
          <div className="accordion-body">
            <pre className="json-view">{JSON.stringify(node, null, 2)}</pre>
          </div>
        </div>
      )}
    </div>
  )
}
