import { useState, useEffect } from 'react'
import type { HubCredentials } from '../types/hub'
import { nodeAttr } from '../types/hub'
import { getNode } from '../services/hubApi'
import { FileViewPane } from './FileViewPane'
import './FilePreviewModal.css'

const IcNavigate = () => (
  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>
    <polyline points="15 3 21 3 21 9"/>
    <line x1="10" y1="14" x2="21" y2="3"/>
  </svg>
)

interface Props {
  path: string
  credentials: HubCredentials
  onNavigate: (path: string) => void
  onClose: () => void
}

export function FilePreviewModal({ path, credentials, onNavigate, onClose }: Props) {
  const name = path.split('/').pop() ?? path
  const [totalBytes, setTotalBytes] = useState<number | undefined>(undefined)
  const [resolved, setResolved] = useState(false)

  useEffect(() => {
    setResolved(false)
    setTotalBytes(undefined)
    getNode(credentials, path, 0).then(node => {
      const cl = nodeAttr(node, 'contentLength')
      if (cl !== undefined) setTotalBytes(parseInt(cl, 10))
    }).catch(() => { /* non-fatal — FileViewPane falls back to full load */ })
      .finally(() => setResolved(true))
  }, [path, credentials])

  function handleNavigate() {
    onNavigate(path)
    onClose()
  }

  function handleOverlayClick(e: React.MouseEvent<HTMLDivElement>) {
    if (e.target === e.currentTarget) onClose()
  }

  return (
    <div className="fpm-overlay" onClick={handleOverlayClick}>
      <div className="fpm-dialog">
        <div className="fpm-header">
          <span className="fpm-name" title={name}>{name}</span>
          <span className="fpm-path" title={path}>{path}</span>
          <button className="fpm-btn" onClick={handleNavigate} title="Navigate to file in tree">
            <IcNavigate />
          </button>
          <button className="fpm-close" onClick={onClose} title="Close">✕</button>
        </div>
        <div className="fpm-body">
          {resolved
            ? <FileViewPane path={path} credentials={credentials} totalBytes={totalBytes} />
            : <div className="mp-loading">Loading…</div>}
        </div>
      </div>
    </div>
  )
}
