import { useState, useEffect } from 'react'
import type { LogMessage } from '../types/hub'
import { logStore } from '../services/logStore'
import './LogPanel.css'

const SEV_ORDER: LogMessage['severity'][] = ['error', 'warning', 'info', 'debug']
const SEV_ICON: Record<LogMessage['severity'], string> = { error: '✕', warning: '⚠', info: 'ℹ', debug: '⊙' }

interface Props { onClose: () => void }

export function LogPanel({ onClose }: Props) {
  const [entries, setEntries] = useState(() => logStore.getAll())
  const [minSev, setMinSev] = useState<LogMessage['severity']>('info')
  const [search, setSearch] = useState('')
  const [detail, setDetail] = useState<LogMessage | null>(null)

  useEffect(() => logStore.onChange(() => setEntries([...logStore.getAll()])), [])

  const sevRank = (s: LogMessage['severity']) => SEV_ORDER.indexOf(s)

  const filtered = [...entries]
    .reverse()
    .filter(e => sevRank(e.severity) <= sevRank(minSev))
    .filter(e => !search || e.text.toLowerCase().includes(search.toLowerCase()))

  return (
    <>
      <div className="log-backdrop" onClick={onClose} />
      <div className="log-panel">
        <div className="log-panel-header">
          <span className="log-panel-title">Logs</span>
          <div className="log-sev-filter">
            {SEV_ORDER.map(s => (
              <label key={s} className={`log-sev-pill${minSev === s ? ' active' : ''} sev-${s}`}>
                <input type="radio" name="logsev" value={s} checked={minSev === s} onChange={() => setMinSev(s)} />
                {s.charAt(0).toUpperCase() + s.slice(1)}
              </label>
            ))}
          </div>
          <input
            className="log-search"
            type="text"
            placeholder="Search…"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
          <button className="log-clear" onClick={() => logStore.clear()} title="Clear">Clear</button>
          <button className="log-close" onClick={onClose} title="Close">✕</button>
        </div>

        <div className="log-entries">
          {filtered.length === 0 && <div className="log-empty">No entries</div>}
          {filtered.map(e => (
            <div key={e.id} className={`log-entry sev-${e.severity}`} onClick={() => setDetail(e)}>
              <span className="log-entry-icon">{SEV_ICON[e.severity]}</span>
              {e.time && <span className="log-entry-time">{e.time}</span>}
              <span className="log-entry-text">{e.text}</span>
            </div>
          ))}
        </div>

        {detail && (
          <div className="log-detail-overlay" onClick={() => setDetail(null)}>
            <div className="log-detail-box" onClick={e => e.stopPropagation()}>
              <div className={`log-detail-sev sev-${detail.severity}`}>{detail.severity.toUpperCase()}</div>
              {detail.time && <div className="log-detail-time">{detail.time}</div>}
              <pre className="log-detail-text">{detail.text}</pre>
              <button onClick={() => setDetail(null)}>Close</button>
            </div>
          </div>
        )}
      </div>
    </>
  )
}
