import { useState, useRef } from 'react'
import type { HubCredentials, HubSettings } from '../types/hub'
import { profileService } from '../services/profileService'
import './SettingsDialog.css'

interface Props {
  settings: HubSettings
  credentials: HubCredentials
  onSave: (s: HubSettings) => void
  onClose: () => void
}

export function SettingsDialog({ settings, credentials, onSave, onClose }: Props) {
  const [s, setS]           = useState<HubSettings>({ ...settings })
  const [profileMsg, setProfileMsg] = useState<{ text: string; ok: boolean } | null>(null)
  const fileInputRef        = useRef<HTMLInputElement>(null)

  function set<K extends keyof HubSettings>(key: K, value: HubSettings[K]) {
    setS(prev => ({ ...prev, [key]: value }))
  }

  function handleSave(e: React.FormEvent) {
    e.preventDefault()
    onSave(s)
  }

  async function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    e.target.value = ''
    if (!file) return
    try {
      const profile = JSON.parse(await file.text())
      profileService.apply(profile, credentials.host)
      onSave(profileService.mergeSettings(profile))
    } catch {
      setProfileMsg({ text: 'Invalid file — could not parse JSON.', ok: false })
    }
  }

  async function handleLoadDefaults() {
    setProfileMsg(null)
    const profile = await profileService.fetchDefaults(credentials)
    if (!profile) {
      setProfileMsg({ text: 'defaults.json not found on frontend server or Hub backend.', ok: false })
      return
    }
    profileService.apply(profile, credentials.host)
    onSave(profileService.mergeSettings(profile))
  }

  function handleSaveFile() {
    profileService.download(profileService.collect(credentials.host, s))
    setProfileMsg({ text: 'Saved as defaults.json.', ok: true })
  }

  return (
    <div className="dialog-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="dialog-box settings-dialog">
        <div className="dialog-header">
          <span>Settings</span>
          <button className="dialog-close" onClick={onClose}>✕</button>
        </div>

        <form onSubmit={handleSave} className="settings-form">
          <div className="settings-section">
            <h3>Tree</h3>

            <label>Root path</label>
            <div className="settings-input-row">
              <input
                type="text"
                value={s.rootPath}
                onChange={e => set('rootPath', e.target.value)}
                placeholder="Environment/Remotes"
                className="settings-input"
              />
              <button
                type="button"
                className="settings-reset-btn"
                disabled={s.rootPath === 'Environment/Remotes'}
                onClick={() => set('rootPath', 'Environment/Remotes')}
                title="Reset to default"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/>
                </svg>
              </button>
            </div>

            <label className="settings-checkbox-label">
              <input
                type="checkbox"
                checked={s.showHidden}
                onChange={e => set('showHidden', e.target.checked)}
              />
              Show hidden nodes
            </label>
          </div>

          <div className="settings-section">
            <h3>Refresh</h3>

            <label>Auto-refresh interval (seconds, 0 = disabled)</label>
            <input
              type="number"
              min={0}
              max={300}
              value={s.autoRefreshInterval}
              onChange={e => set('autoRefreshInterval', Number(e.target.value))}
              className="settings-input settings-input--short"
            />
          </div>

          <div className="settings-section">
            <h3>Files</h3>

            <label>Download size warning threshold (MB)</label>
            <input
              type="number"
              min={1}
              max={10000}
              value={s.maxDownloadMB}
              onChange={e => set('maxDownloadMB', Number(e.target.value))}
              className="settings-input settings-input--short"
            />

            <label>Auto-load file contents smaller than (KB, 0 = disabled)</label>
            <input
              type="number"
              min={0}
              max={102400}
              step={1}
              value={s.autoLoadKB}
              onChange={e => set('autoLoadKB', Number(e.target.value))}
              className="settings-input settings-input--short"
            />

            <label>Text preview chunk size (KB)</label>
            <input
              type="number"
              min={1}
              max={10240}
              step={1}
              value={s.autoPreviewKB}
              onChange={e => set('autoPreviewKB', Number(e.target.value))}
              className="settings-input settings-input--short"
            />
          </div>

          <div className="settings-section">
            <h3>Display</h3>

            <label>Mode</label>
            <div className="settings-mode-group">
              <button
                type="button"
                className={`settings-mode-btn${s.mode === 'simple' ? ' settings-mode-btn--active' : ''}`}
                onClick={() => set('mode', 'simple')}
              >Simple</button>
              <button
                type="button"
                className={`settings-mode-btn${s.mode === 'expert' ? ' settings-mode-btn--active' : ''}`}
                onClick={() => set('mode', 'expert')}
              >Expert</button>
            </div>

            <label className="settings-checkbox-label">
              <input
                type="checkbox"
                checked={s.showJson}
                onChange={e => set('showJson', e.target.checked)}
              />
              Show JSON panel in detail view
            </label>

            <label className="settings-checkbox-label">
              <input
                type="checkbox"
                checked={s.autoLoadServiceInfo ?? false}
                onChange={e => set('autoLoadServiceInfo', e.target.checked)}
              />
              Auto-load service info on open
            </label>
          </div>

          <div className="settings-section">
            <h3>Profile</h3>
            <p className="settings-profile-hint">
              Settings + favorites + preferences in one <code>defaults.json</code> file.
              Placed on the server it auto-loads for new sessions.
            </p>
            <div className="settings-profile-btns">
              <button type="button" className="settings-profile-icon-btn settings-profile-icon-btn--blue" onClick={() => fileInputRef.current?.click()} title="Load from file">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                  <polyline points="17 8 12 3 7 8"/>
                  <line x1="12" y1="3" x2="12" y2="15"/>
                </svg>
              </button>
              <button type="button" className="settings-profile-icon-btn settings-profile-icon-btn--green" onClick={handleSaveFile} title="Save to file">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                  <polyline points="7 10 12 15 17 10"/>
                  <line x1="12" y1="15" x2="12" y2="3"/>
                </svg>
              </button>
              <button type="button" className="settings-profile-icon-btn settings-profile-icon-btn--purple" onClick={handleLoadDefaults} title="Load defaults from server">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="8 17 12 21 16 17"/>
                  <line x1="12" y1="12" x2="12" y2="21"/>
                  <path d="M20.88 18.09A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.29"/>
                </svg>
              </button>
            </div>
            {profileMsg && (
              <p className={`settings-profile-msg${profileMsg.ok ? ' settings-profile-msg--ok' : ' settings-profile-msg--err'}`}>
                {profileMsg.text}
              </p>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept=".json,application/json"
              style={{ display: 'none' }}
              onChange={handleFileChange}
            />
          </div>

          <div className="dialog-actions">
            <button type="button" className="btn btn-secondary" onClick={onClose}>Cancel</button>
            <button type="submit" className="btn btn-primary">Save</button>
          </div>
        </form>
      </div>
    </div>
  )
}
