// All boolean/numeric fields from the Hub API arrive as strings ("true"/"false", "1").
// Use the str* helpers below to safely coerce them.

export interface ModelNode {
  rid?: number | string;
  name?: string;
  preview?: string;
  value?: string;
  /** New foundation.model type — describes the node itself: "bool" | "integer" | "decimal" | "text" | "list" | "map" | "class" | "command" | "provider" */
  type?: string;
  /** For type="list" and type="map": the element/value type ("text", "integer", "bool", "decimal", "choice") */
  listType?: string;
  /** Legacy type fields (Assist Hub / appmodel) — kept for backward compatibility */
  remoteType?: string;
  localType?: string;
  encapsulated?: string;
  iconData?: string;
  childrenCount?: string | number;
  args?: string;
  help?: string;
  visible?: string | boolean;
  readonly?: string | boolean;
  deletable?: string | boolean;
  deleteable?: string | boolean;   // legacy spelling used by the backend
  enabled?: string | boolean;
  active?: string | boolean;
  disposed?: string | boolean;
  isRemote?: string | boolean;
  persistent?: string | boolean;
  renameable?: string | boolean;
  startable?: string | boolean;
  started?: string | boolean;
  hasCommands?: string | boolean;
  isCommand?: string | boolean;
  defCmd?: string | boolean;
  persistable?: string | boolean;
  /** Simple return type of a command node: "string" | "integer" | "decimal" | "boolean" | "binary", or a class simple name. Absent for void commands. */
  returnType?: string;
  lastChange?: number;
  label?: string;
  supportedChildren?: string;
  text?: string;
  choices?: string;                // semicolon-separated values for Choice nodes
  children?: ModelNode[];
  // fields present on file-system nodes
  filePath?: string;
  icon?: string;
  /** Number of non-command children — used for the expand triangle.
   *  A node with commands but no navigable children has childrenCount > 0 but visibleChildrenCount = 0. */
  visibleChildrenCount?: string | number;
  // client-side only
  fullPath?: string;
}

export function strTrue(v: string | boolean | undefined): boolean {
  return v === true || v === 'true';
}

export function strNum(v: string | number | undefined, fallback = 0): number {
  if (v === undefined || v === null) return fallback;
  const n = Number(v);
  return isNaN(n) ? fallback : n;
}

/**
 * Reads a top-level @Attribute value from a node response.
 * @Attribute fields are serialised inline alongside standard fields like name/visible,
 * so they are not present in the TypeScript interface but are present at runtime.
 */
export function nodeAttr(node: ModelNode, key: string): string | undefined {
  return (node as Record<string, unknown>)[key] as string | undefined;
}

export interface HubCredentials {
  host: string;
  username: string;
  password: string;
}

export interface HubSettings {
  rootPath: string;
  showHidden: boolean;
  autoRefreshInterval: number; // seconds; 0 = disabled
  maxDownloadMB: number;
  autoLoadKB: number;          // auto-load file contents when size < this (KB); 0 = disabled
  autoPreviewKB: number;       // tail-load chunk size for text preview (KB)
  mode: 'expert' | 'simple';
  showJson: boolean;
  autoLoadServiceInfo: boolean; // background-refresh service data on revisit
}

export const DEFAULT_SETTINGS: HubSettings = {
  rootPath: 'Environment/Remotes',
  showHidden: false,
  autoRefreshInterval: 5,
  maxDownloadMB: 100,
  autoLoadKB: 1024,
  autoPreviewKB: 50,
  mode: 'simple',
  showJson: false,
  autoLoadServiceInfo: false,
}

export interface LogMessage {
  id: number;
  time?: string;
  severity: 'debug' | 'info' | 'warning' | 'error';
  caller?: string;
  text: string;
}

export interface CommandArg {
  name: string;
  /** Simple type name: "string" | "boolean" | "integer" | "decimal" | "binary", or a class simple name. */
  type: string;
  required: boolean;
  defaultValue: string;
  uiHint: string;
}

/** Maps legacy Java FQCN / primitive names to the simple vocabulary. */
function normalizeParamType(raw: string): string {
  switch (raw) {
    case 'java.lang.String':                      return 'string'
    case 'java.lang.Boolean': case 'boolean':     return 'boolean'
    case 'java.lang.Integer': case 'int':
    case 'java.lang.Long':    case 'long':        return 'integer'
    case 'java.lang.Double':  case 'double':
    case 'java.lang.Float':   case 'float':       return 'decimal'
    case '[B': case 'byte[]':                     return 'binary'
    default:                                      return raw
  }
}

// Parses "name,type,required,default,uiHint;..." into CommandArg[]
export function parseArgs(argsStr: string): CommandArg[] {
  return argsStr.split(';').filter(Boolean).map(seg => {
    const parts = seg.split(',');
    return {
      name: parts[0] ?? '',
      type: normalizeParamType(parts[1] ?? 'string'),
      required: parts[2] === 'true',
      defaultValue: parts[3] ?? '',
      uiHint: parts[4] ?? '',
    }
  })
}

// Parses Hub log preview format: "[SEVERITY] [TIME] [CALLER] text"
export function parseLogText(raw: string): Omit<LogMessage, 'id'> {
  let text = raw
  let time: string | undefined
  let caller: string | undefined
  let severity: LogMessage['severity'] = 'info'

  function extractBracket(): string | undefined {
    const s = text.indexOf('['), e = text.indexOf(']')
    if (s === -1 || e === -1) return undefined
    const val = text.substring(s + 1, e)
    text = text.substring(e + 1).trim()
    return val
  }

  const first = extractBracket()
  if (first) {
    const sev = first.toLowerCase()
    if (['debug', 'info', 'warning', 'warn', 'error', 'err'].includes(sev)) {
      severity = sev.startsWith('warn') ? 'warning' : sev.startsWith('err') ? 'error' : sev as LogMessage['severity']
      time = extractBracket()
      caller = extractBracket()
    } else {
      time = first
      caller = extractBracket()
    }
  }

  return { time, severity, caller, text: text.trim() }
}
