import { useState } from 'react'
import type { CommandArg } from '../types/hub'
import './CommandDialog.css'

interface Props {
  commandPath: string
  commandName: string
  args: CommandArg[]
  onExecute: (namedArgs: Record<string, string>) => void
  onClose: () => void
}

export function CommandDialog({ commandName, args, onExecute, onClose }: Props) {
  const [values, setValues] = useState<Record<string, string>>(() => {
    const init: Record<string, string> = {}
    for (const a of args) init[a.name] = a.defaultValue
    return init
  })
  // Display names for binary file pickers (uncontrolled inputs show their own filename)
  const [fileNames, setFileNames] = useState<Record<string, string>>({})

  function set(name: string, value: string) {
    setValues(prev => ({ ...prev, [name]: value }))
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    onExecute(values)
  }

  function renderInput(arg: CommandArg) {
    if (arg.type === 'boolean') {
      return (
        <input
          id={`cmd-${arg.name}`}
          type="checkbox"
          checked={values[arg.name] === 'true'}
          onChange={e => set(arg.name, String(e.target.checked))}
          className="cmd-checkbox"
        />
      )
    }
    if (arg.type === 'binary') {
      return (
        <div className="cmd-file-wrap">
          <input
            id={`cmd-${arg.name}`}
            type="file"
            className="cmd-file-input"
            onChange={e => {
              const file = e.target.files?.[0]
              if (!file) return
              setFileNames(prev => ({ ...prev, [arg.name]: file.name }))
              const reader = new FileReader()
              reader.onload = () => {
                const dataUrl = reader.result as string
                set(arg.name, dataUrl.split(',')[1] ?? '')
              }
              reader.readAsDataURL(file)
            }}
          />
          {fileNames[arg.name] && (
            <span className="cmd-file-name">{fileNames[arg.name]}</span>
          )}
        </div>
      )
    }
    if (arg.type === 'integer') {
      return (
        <input
          id={`cmd-${arg.name}`}
          type="number"
          step="1"
          value={values[arg.name] ?? ''}
          onChange={e => set(arg.name, e.target.value)}
          required={arg.required}
          className="settings-input"
        />
      )
    }
    if (arg.type === 'decimal') {
      return (
        <input
          id={`cmd-${arg.name}`}
          type="number"
          step="any"
          value={values[arg.name] ?? ''}
          onChange={e => set(arg.name, e.target.value)}
          required={arg.required}
          className="settings-input"
        />
      )
    }
    if (arg.uiHint === 'multiline') {
      return (
        <textarea
          id={`cmd-${arg.name}`}
          value={values[arg.name] ?? ''}
          onChange={e => set(arg.name, e.target.value)}
          rows={4}
          className="settings-input cmd-textarea"
          spellCheck={false}
        />
      )
    }
    return (
      <input
        id={`cmd-${arg.name}`}
        type={arg.uiHint === 'password' ? 'password' : arg.uiHint === 'url' ? 'url' : 'text'}
        value={values[arg.name] ?? ''}
        onChange={e => set(arg.name, e.target.value)}
        required={arg.required}
        className="settings-input"
      />
    )
  }

  return (
    <div className="dialog-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="dialog-box command-dialog">
        <div className="dialog-header">
          <span>Execute: {commandName}</span>
          <button className="dialog-close" onClick={onClose}>✕</button>
        </div>
        <form onSubmit={handleSubmit} className="command-form">
          {args.map(arg => (
            <div key={arg.name} className="command-field">
              <label htmlFor={`cmd-${arg.name}`}>
                {arg.name}
                {arg.required && <span className="cmd-required"> *</span>}
              </label>
              {renderInput(arg)}
            </div>
          ))}
          <div className="dialog-actions">
            <button type="button" className="btn btn-secondary" onClick={onClose}>Cancel</button>
            <button type="submit" className="btn btn-primary">Execute</button>
          </div>
        </form>
      </div>
    </div>
  )
}
