import { useState, useEffect, useRef } from 'react'
import type { HubCredentials } from '../types/hub'
import { getNode, HubApiError } from '../services/hubApi'
import { isRemembered } from '../services/authService'
import { NetworkCanvas } from './NetworkCanvas'
import './LoginDialog.css'

interface Props {
  prefillHost?: string
  onLogin: (creds: HubCredentials, remember: boolean) => void
}

export function LoginDialog({ prefillHost, onLogin }: Props) {
  const [host, setHost] = useState(prefillHost ?? 'https://saas-app.minova.com/minova/hub')
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [remember, setRemember] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const logoRef = useRef<HTMLImageElement>(null)

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const urlHost = params.get('host')
    if (urlHost) setHost(urlHost)
    setRemember(isRemembered())
  }, [])

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    const creds: HubCredentials = { host: host.replace(/\/$/, ''), username, password }
    setLoading(true)
    setError(null)
    try {
      await getNode(creds, '', 0)
      onLogin(creds, remember)
    } catch (err) {
      if (err instanceof HubApiError) {
        if (err.status === 403) {
          setError('Invalid credentials.')
        } else if (err.status === 404) {
          // 404 on root just means connected, proceed
          onLogin(creds, remember)
        } else {
          setError(`Connection failed: ${err.message}`)
        }
      } else {
        setError(err instanceof Error ? err.message : 'Connection failed.')
      }
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="login-overlay">
      <NetworkCanvas logoRef={logoRef} />
      <div className="login-card-wrap">
        <img ref={logoRef} src="/favicon.svg" alt="MINOVA Hub" className="login-brand-logo" />
        <div className="login-dialog">
        <div className="login-header">
          <span className="login-logo" />
          <h1>MINOVA Hub</h1>
        </div>
        <form onSubmit={handleSubmit} className="login-form">
          <label htmlFor="hub-host">Hub URL</label>
          <input
            id="hub-host"
            type="text"
            value={host}
            onChange={e => setHost(e.target.value)}
            placeholder="https://host:port/path"
            required
            autoFocus
            autoComplete="url"
          />

          <label htmlFor="hub-user">Username</label>
          <input
            id="hub-user"
            type="text"
            value={username}
            onChange={e => setUsername(e.target.value)}
            autoComplete="username"
            required
          />

          <label htmlFor="hub-pass">Password</label>
          <input
            id="hub-pass"
            type="password"
            value={password}
            onChange={e => setPassword(e.target.value)}
            autoComplete="current-password"
            required
          />

          <label className="login-remember">
            <input
              type="checkbox"
              checked={remember}
              onChange={e => setRemember(e.target.checked)}
            />
            Remember credentials
          </label>

          {error && <div className="login-error">{error}</div>}

          <button type="submit" className="login-btn" disabled={loading}>
            {loading ? 'Connecting…' : 'Connect'}
          </button>
        </form>
        <div className="login-version">v{__APP_VERSION__}</div>
        </div>
      </div>
    </div>
  )
}
