import type { LogMessage } from '../types/hub'

let entries: LogMessage[] = []
let idSeq = 0

const EVENT     = 'hub-log-changed'
const NEW_EVENT = 'hub-log-new'

export const logStore = {
  add(msg: Omit<LogMessage, 'id'>): void {
    const entry = { ...msg, id: ++idSeq }
    entries = [...entries, entry]
    window.dispatchEvent(new CustomEvent(EVENT))
    window.dispatchEvent(new CustomEvent<LogMessage>(NEW_EVENT, { detail: entry }))
  },

  addMany(msgs: Omit<LogMessage, 'id'>[]): void {
    if (msgs.length === 0) return
    const newEntries = msgs.map(m => ({ ...m, id: ++idSeq }))
    entries = [...entries, ...newEntries]
    window.dispatchEvent(new CustomEvent(EVENT))
    newEntries.forEach(e =>
      window.dispatchEvent(new CustomEvent<LogMessage>(NEW_EVENT, { detail: e }))
    )
  },

  getAll(): LogMessage[] { return entries },

  getCounts(): Record<LogMessage['severity'], number> {
    const c = { debug: 0, info: 0, warning: 0, error: 0 }
    for (const e of entries) c[e.severity]++
    return c
  },

  clear(): void {
    entries = []
    window.dispatchEvent(new CustomEvent(EVENT))
  },

  onChange(handler: () => void): () => void {
    window.addEventListener(EVENT, handler)
    return () => window.removeEventListener(EVENT, handler)
  },

  onNew(handler: (msg: LogMessage) => void): () => void {
    const listener = (e: Event) => handler((e as CustomEvent<LogMessage>).detail)
    window.addEventListener(NEW_EVENT, listener)
    return () => window.removeEventListener(NEW_EVENT, listener)
  },
}
