import type { ModelNode, HubCredentials } from '../types/hub'
import { nodeAttr } from '../types/hub'
import { basicAuthHeader } from './authService'

export class HubApiError extends Error {
  constructor(public readonly status: number, message: string) {
    super(message)
    this.name = 'HubApiError'
  }
}

async function req<T>(
  creds: HubCredentials,
  method: 'GET' | 'POST',
  path: string,
  params: Record<string, string | number | boolean | undefined>,
  body?: BodyInit,
): Promise<T> {
  const url = new URL(creds.host + path)
  for (const [k, v] of Object.entries(params)) {
    if (v !== undefined) url.searchParams.set(k, String(v))
  }
  const headers: Record<string, string> = { Authorization: basicAuthHeader(creds) }
  const resp = await fetch(url.toString(), { method, headers, body })
  if (!resp.ok) {
    let msg = `HTTP ${resp.status}`
    try { const e = await resp.json(); if (e.Error) msg = e.Error } catch { /* ignore */ }
    throw new HubApiError(resp.status, msg)
  }
  const ct = resp.headers.get('content-type') ?? ''
  if (ct.includes('application/json')) return resp.json() as Promise<T>
  return resp.text() as unknown as Promise<T>
}

function stripRemoteModelPlaceholders(node: ModelNode): ModelNode {
  if (!node.children?.length) return node
  return {
    ...node,
    children: node.children
      .filter(c => c.name !== 'Remote model')
      .map(stripRemoteModelPlaceholders),
  }
}

export async function getNode(
  creds: HubCredentials,
  path: string,
  depth = 1,
): Promise<ModelNode> {
  const node = await req<ModelNode>(creds, 'GET', '/get', { path, depth })
  return stripRemoteModelPlaceholders(node)
}

export function getValue(
  creds: HubCredentials,
  path: string,
  style: 'auto' | 'text' | 'json' = 'auto',
  key?: string,
): Promise<string> {
  return req<string>(creds, 'GET', '/getvalue', { path, style, key })
}

export function setValue(
  creds: HubCredentials,
  path: string,
  value: string,
  key?: string,
): Promise<ModelNode> {
  return req<ModelNode>(creds, 'GET', '/set', { path, value, key })
}

export async function callCommand(
  creds: HubCredentials,
  path: string,
  namedArgs: Record<string, string>,
): Promise<ModelNode | string | ArrayBuffer> {
  // Path encoded in URL; args sent as POST form body to support large binary (base64) params.
  const url = new URL(`${creds.host}/call/${path.replace(/^\//, '')}`)
  const body = new URLSearchParams()
  for (const [name, val] of Object.entries(namedArgs)) {
    body.set(`arg${name}`, val)
  }
  const resp = await fetch(url.toString(), {
    method: 'POST',
    headers: {
      Authorization: basicAuthHeader(creds),
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  })
  if (!resp.ok) {
    let msg = `HTTP ${resp.status}`
    try { const e = await resp.json(); if (e.Error) msg = e.Error } catch { /* ignore */ }
    throw new HubApiError(resp.status, msg)
  }
  const ct = resp.headers.get('content-type') ?? ''
  if (ct.includes('application/octet-stream')) return resp.arrayBuffer()
  if (ct.includes('application/json')) return resp.json()
  return resp.text()
}

export function deleteNode(
  creds: HubCredentials,
  path: string,
  force = false,
): Promise<ModelNode> {
  return req<ModelNode>(creds, 'GET', '/delete', { path, force })
}

/**
 * Fetches the icon for a node and returns an object URL suitable for <img src>.
 * The caller is responsible for revoking the URL when done (or simply leave it
 * alive for the session — icons are small).
 * Returns null if the node has no icon or the request fails.
 *
 * When nodePath is provided it is sent as the `path` parameter so the backend
 * can route the request to the correct node (including remote nodes via __icon__).
 */
export async function fetchNodeIcon(
  creds: HubCredentials,
  type: string,
  iconName: string,
  nodePath?: string,
): Promise<string | null> {
  const url = new URL(creds.host + '/icon')
  url.searchParams.set('type', type)
  if (iconName) url.searchParams.set('icon', iconName)
  if (nodePath) url.searchParams.set('path', nodePath)
  try {
    const resp = await fetch(url.toString(), { headers: { Authorization: basicAuthHeader(creds) } })
    if (!resp.ok) return null
    const blob = await resp.blob()
    return URL.createObjectURL(blob)
  } catch {
    return null
  }
}


const IMAGE_EXT  = new Set(['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'bmp', 'ico'])
const PDF_EXT    = new Set(['pdf'])
const BINARY_EXT = new Set([
  // executables / compiled
  'exe', 'dll', 'so', 'dylib', 'bin', 'elf', 'o', 'obj', 'a', 'lib', 'pdb',
  'class', 'pyc', 'pyd',
  // archives
  'zip', 'tar', 'gz', 'bz2', 'xz', '7z', 'rar', 'jar', 'war', 'ear', 'apk', 'ipa',
  // office (binary / zip-based, not human-readable)
  'doc', 'xls', 'ppt', 'docx', 'xlsx', 'pptx', 'odt', 'ods', 'odp',
  // database
  'db', 'sqlite', 'sqlite3', 'mdb', 'accdb',
  // media
  'mp3', 'mp4', 'avi', 'mov', 'mkv', 'wav', 'flac', 'ogg', 'webm', 'aac',
  // fonts
  'ttf', 'otf', 'woff', 'woff2', 'eot',
  // disk / firmware
  'iso', 'img', 'dmg', 'vmdk', 'vhd',
])

export type FileViewType = 'text' | 'image' | 'pdf' | 'binary'

export function fileViewType(filename: string): FileViewType {
  const ext = filename.split('.').pop()?.toLowerCase() ?? ''
  if (IMAGE_EXT.has(ext))  return 'image'
  if (PDF_EXT.has(ext))    return 'pdf'
  if (BINARY_EXT.has(ext)) return 'binary'
  return 'text'
}

export function viewStyle(filename: string): 'text' | 'binary' {
  const ext = filename.split('.').pop()?.toLowerCase() ?? ''
  return BINARY_EXT.has(ext) ? 'binary' : 'text'
}

export async function loadFileBlob(creds: HubCredentials, path: string): Promise<string> {
  const url = new URL(creds.host + '/getvalue')
  url.searchParams.set('path', path)
  url.searchParams.set('style', 'binary')
  const resp = await fetch(url.toString(), { headers: { Authorization: basicAuthHeader(creds) } })
  if (!resp.ok) throw new HubApiError(resp.status, `HTTP ${resp.status}`)
  return URL.createObjectURL(await resp.blob())
}

export function getValueUrl(creds: HubCredentials, path: string, style = 'auto', startAt?: number, length?: number): string {
  const url = new URL(`${creds.host}/getvalue/${path}`)
  url.searchParams.set('style', style)
  if (startAt !== undefined && startAt !== 0) url.searchParams.set('startAt', String(startAt))
  if (length !== undefined && length !== -1)  url.searchParams.set('length',  String(length))
  return url.toString()
}

export async function downloadFile(creds: HubCredentials, path: string, filename: string): Promise<void> {
  const url = new URL(creds.host + '/getvalue')
  url.searchParams.set('path', path)
  url.searchParams.set('style', 'binary')
  const resp = await fetch(url.toString(), { headers: { Authorization: basicAuthHeader(creds) } })
  if (!resp.ok) throw new HubApiError(resp.status, `HTTP ${resp.status}`)
  const blob = await resp.blob()
  const objectUrl = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = objectUrl
  a.download = filename
  a.click()
  URL.revokeObjectURL(objectUrl)
}

// ---- Chunked read / download -----------------------------------------------

/** Size of each viewer chunk (initial tail load + load-more steps). */
export const VIEWER_CHUNK_SIZE = 100 * 1024  // 100 KB

/** Size of each download chunk — matches the WS frame raw-payload cap (512 KB × 3/4). */
export const DOWNLOAD_CHUNK_SIZE = (512 * 1024 * 3) / 4  // 384 KB

/**
 * Returns true when a node exposes its byte length, which signals that the
 * backend supports ranged reads (startAt / length params on /getvalue).
 * Old nodes without this attribute must be downloaded in full.
 */
export function supportsChunkedRead(node: ModelNode): boolean {
  return nodeAttr(node, 'contentLength') !== undefined
}

/** Fetches a raw byte range. Returns the bytes and the `X-Content-Total-Length` header value. */
export async function getValueRange(
  creds: HubCredentials,
  path: string,
  startAt: number,
  length: number,
): Promise<{ data: ArrayBuffer; totalLength: number | null }> {
  const url = new URL(creds.host + '/getvalue')
  url.searchParams.set('path', path)
  url.searchParams.set('startAt', String(startAt))
  url.searchParams.set('length', String(length))
  const resp = await fetch(url.toString(), { headers: { Authorization: basicAuthHeader(creds) } })
  if (!resp.ok) {
    let msg = `HTTP ${resp.status}`
    try { const e = await resp.json(); if (e.Error) msg = e.Error } catch { /* ignore */ }
    throw new HubApiError(resp.status, msg)
  }
  const hdr = resp.headers.get('X-Content-Total-Length')
  return { data: await resp.arrayBuffer(), totalLength: hdr !== null ? parseInt(hdr, 10) : null }
}

/**
 * Downloads a file in 384 KB chunks and triggers a browser save dialog.
 * `totalBytes` must come from the node's `contentLength` attribute (i.e. the node
 * must support ranged reads — check with {@link supportsChunkedRead} first).
 */
export async function downloadFileChunked(
  creds: HubCredentials,
  path: string,
  filename: string,
  totalBytes: number,
  onProgress?: (loaded: number, total: number) => void,
  signal?: AbortSignal,
): Promise<void> {
  const parts: BlobPart[] = []
  let offset = 0
  while (offset < totalBytes) {
    if (signal?.aborted) throw new DOMException('Aborted', 'AbortError')
    const { data } = await getValueRange(creds, path, offset, DOWNLOAD_CHUNK_SIZE)
    const bytes = new Uint8Array(data)
    parts.push(bytes)
    offset += bytes.length
    onProgress?.(offset, totalBytes)
    if (bytes.length < DOWNLOAD_CHUNK_SIZE) break  // last chunk (server reached EOF)
  }
  const blob = new Blob(parts)
  const objUrl = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = objUrl
  a.download = filename
  a.click()
  URL.revokeObjectURL(objUrl)
}

// Node type helpers
// Each predicate checks both the legacy remoteType/localType (Assist Hub / appmodel) and
// the new foundation.model `type` field so both backends work without branching elsewhere.
//
// For CLASS/PROVIDER nodes the `type` field is the fully-qualified Java class name.
// typeSimpleName strips the package so predicates work regardless of which package the
// class lives in (e.g. ch.minova.foundation.model.commons.fs.LocalFile → LocalFile).
function typeSimpleName(n: ModelNode): string | undefined {
  if (!n.type) return undefined
  const dot = n.type.lastIndexOf('.')
  return dot >= 0 ? n.type.substring(dot + 1) : n.type
}

export const isLocalFile      = (n: ModelNode) =>
  n.remoteType === 'ch.minova.assist.fs.LocalFile' ||
  typeSimpleName(n) === 'LocalFile'
export const isLocalDirectory = (n: ModelNode) =>
  n.remoteType === 'ch.minova.assist.fs.LocalDirectory' ||
  n.remoteType === 'ch.minova.assist.fs.LocalDir' ||
  typeSimpleName(n) === 'LocalDirectory' ||
  typeSimpleName(n) === 'LocalDir'
export const isBinary    = (n: ModelNode) => n.type === 'binary'
export const isChoice    = (n: ModelNode) =>
  n.remoteType === 'ch.minova.appmodel.value.Choice' ||
  n.remoteType === 'ch.minova.appmodel.value.ChoiceEnum' ||
  typeSimpleName(n) === 'Choice' ||
  typeSimpleName(n) === 'ChoiceEnum' ||
  n.type === 'choice'
export const isBool      = (n: ModelNode) =>
  n.remoteType === 'ch.minova.appmodel.value.Bool' ||
  typeSimpleName(n) === 'Bool' ||
  n.type === 'bool'
export const isPassword  = (n: ModelNode) => n.type === 'password'
export const isTimestamp = (n: ModelNode) => n.type === 'timestamp'
export const isUrl       = (n: ModelNode) => n.type === 'url'
export const isFilePath  = (n: ModelNode) => n.type === 'file' || n.type === 'dir'
export const isList      = (n: ModelNode) => n.type === 'list'
export const isMap       = (n: ModelNode) => n.type === 'map'
export const isValueNode = (n: ModelNode) =>
  n.value != null ||
  (n.remoteType?.startsWith('ch.minova.appmodel.value.') ?? false) ||
  (n.type?.startsWith('ch.minova.appmodel.value.') ?? false) ||
  n.type === 'bool' || n.type === 'integer' || n.type === 'decimal' || n.type === 'text' || n.type === 'choice' ||
  n.type === 'password' || n.type === 'timestamp' || n.type === 'url' || n.type === 'file' || n.type === 'dir' ||
  n.type === 'list' || n.type === 'map'

export function formatTimestamp(raw: string | undefined): string {
  if (!raw) return ''
  const ms = parseInt(raw)
  if (isNaN(ms)) return raw
  return new Date(ms).toLocaleString()
}
export const isCommandNode = (n: ModelNode) =>
  n.remoteType === 'ch.minova.appmodel.command.AutoGeneratedCommand' ||
  n.localType === 'ch.minova.appmodel.remote.RemoteCommand' ||
  typeSimpleName(n) === 'AutoGeneratedCommand' ||
  typeSimpleName(n) === 'RemoteCommand' ||
  n.isCommand === 'true' || n.isCommand === true ||
  n.type === 'command'

export function parseSizeBytes(preview: string | undefined): number | null {
  if (!preview) return null
  const m = preview.trim().match(/^(\d+(?:\.\d+)?)\s*(k|m|g)?b$/i)
  if (!m) return null
  const n = parseFloat(m[1])
  const unit = (m[2] ?? '').toLowerCase()
  if (unit === 'k') return n * 1024
  if (unit === 'm') return n * 1024 * 1024
  if (unit === 'g') return n * 1024 * 1024 * 1024
  return n
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024)           return `${bytes}b`
  if (bytes < 1024 * 1024)    return `${(bytes / 1024).toFixed(1)}kb`
  if (bytes < 1024 ** 3)      return `${(bytes / (1024 * 1024)).toFixed(1)}mb`
  return `${(bytes / (1024 ** 3)).toFixed(1)}gb`
}
