import type { HubCredentials } from '../types/hub'

const SESSION_KEY = 'hub-credentials'
const LOCAL_KEY = 'hub-credentials-saved'

export function getCredentials(): HubCredentials | null {
  const raw = sessionStorage.getItem(SESSION_KEY) ?? localStorage.getItem(LOCAL_KEY)
  if (!raw) return null
  try { return JSON.parse(raw) } catch { return null }
}

export function saveCredentials(creds: HubCredentials, remember: boolean): void {
  const json = JSON.stringify(creds)
  sessionStorage.setItem(SESSION_KEY, json)
  if (remember) {
    localStorage.setItem(LOCAL_KEY, json)
  } else {
    localStorage.removeItem(LOCAL_KEY)
  }
}

export function clearCredentials(): void {
  sessionStorage.removeItem(SESSION_KEY)
  localStorage.removeItem(LOCAL_KEY)
}

export function basicAuthHeader(creds: HubCredentials): string {
  return 'Basic ' + btoa(`${creds.username}:${creds.password}`)
}

export function isRemembered(): boolean {
  return localStorage.getItem(LOCAL_KEY) !== null
}
