import { useState, useEffect, useMemo } from 'react'
import type { HubCredentials } from '../types/hub'
import { favoritesService, type Favorite } from '../services/favoritesService'
import { FilePreviewModal } from './FilePreviewModal'
import './FavoritesSidebar.css'

// ---- Helpers ---------------------------------------------------------------

/** First segment after the first /Remotes/ — used as the group key. */
function rootModel(path: string): string {
  const idx = path.indexOf('/Remotes/')
  if (idx === -1) return path.split('/')[0] ?? '—'
  return path.slice(idx + 9).split('/')[0] || '—'
}

/** First segment after the LAST /Remotes/ — used as per-item disambiguation prefix. */
function remotesPrefix(path: string): string | null {
  const idx = path.lastIndexOf('/Remotes/')
  if (idx === -1) return null
  return path.slice(idx + 9).split('/')[0] || null
}

// ---- Icons -----------------------------------------------------------------

const IcEye = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/>
  </svg>
)

const IcNavigate = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>
    <polyline points="15 3 21 3 21 9"/>
    <line x1="10" y1="14" x2="21" y2="3"/>
  </svg>
)

// ---- Single fav item -------------------------------------------------------

interface ItemProps {
  fav: Favorite
  groupName: string
  credentials: HubCredentials
  onNavigate: (path: string) => void
  onRemove: () => void
}

function FavSidebarItem({ fav, groupName, credentials, onNavigate, onRemove }: ItemProps) {
  const [modalOpen, setModalOpen] = useState(false)
  const prefix = remotesPrefix(fav.path)
  const showPrefix = prefix && prefix !== groupName

  const kindIcon = fav.kind === 'value' ? '★' : fav.kind === 'file' ? '📄' : '📁'
  const kindLabel = fav.kind === 'value' ? 'Value' : fav.kind === 'file' ? 'File' : 'Directory'

  return (
    <>
      <div
        className="fsb-item"
        onClick={() => onNavigate(fav.path)}
        title={fav.path}
      >
        <span className="fsb-kind" title={kindLabel}>{kindIcon}</span>
        {showPrefix && <span className="fsb-prefix">{prefix}</span>}
        <span className="fsb-name">{fav.name}</span>
        <div className="fsb-actions" onClick={e => e.stopPropagation()}>
          {fav.kind === 'file' && (
            <button className="fsb-btn" onClick={() => setModalOpen(true)} title="View file">
              <IcEye />
            </button>
          )}
          {fav.kind !== 'value' && (
            <button className="fsb-btn" onClick={() => onNavigate(fav.path)} title="Navigate">
              <IcNavigate />
            </button>
          )}
          <button className="fsb-btn fsb-btn--remove" onClick={onRemove} title="Remove from favorites">×</button>
        </div>
      </div>
      {modalOpen && (
        <FilePreviewModal
          path={fav.path}
          credentials={credentials}
          onNavigate={onNavigate}
          onClose={() => setModalOpen(false)}
        />
      )}
    </>
  )
}

// ---- Component -------------------------------------------------------------

interface Props {
  credentials: HubCredentials
  onNavigate: (path: string) => void
}

export function FavoritesSidebar({ credentials, onNavigate }: Props) {
  const [favorites, setFavorites] = useState<Favorite[]>(() => favoritesService.list(credentials.host))
  const [panelOpen, setPanelOpen]  = useState(true)
  const [collapsed, setCollapsed]  = useState<Set<string>>(new Set())

  useEffect(() => {
    setFavorites(favoritesService.list(credentials.host))
    return favoritesService.onChange(() => setFavorites(favoritesService.list(credentials.host)))
  }, [credentials.host])

  const groups = useMemo(() => {
    const map = new Map<string, Favorite[]>()
    for (const fav of favorites) {
      const key = rootModel(fav.path)
      const arr = map.get(key) ?? []
      arr.push(fav)
      map.set(key, arr)
    }
    return [...map.entries()]
  }, [favorites])

  if (favorites.length === 0) return null

  function toggleGroup(name: string) {
    setCollapsed(prev => {
      const s = new Set(prev)
      s.has(name) ? s.delete(name) : s.add(name)
      return s
    })
  }

  return (
    <div className="fsb-panel">
      <button className={`fsb-toolbar${panelOpen ? ' fsb-toolbar--open' : ''}`} onClick={() => setPanelOpen(v => !v)}>
        <span className="fsb-arrow">{panelOpen ? '▾' : '▸'}</span>
        <span className="fsb-toolbar-title">Favorites</span>
        <span className="fsb-toolbar-count">{favorites.length}</span>
      </button>
      {panelOpen && (
        <div className="fsb-body">
          {groups.map(([group, favs]) => {
            const open = !collapsed.has(group)
            return (
              <div key={group} className="fsb-group">
                <button
                  className={`fsb-group-hdr${open ? ' fsb-group-hdr--open' : ''}`}
                  onClick={() => toggleGroup(group)}
                >
                  <span className="fsb-arrow">{open ? '▾' : '▸'}</span>
                  <span className="fsb-group-name">{group}</span>
                  <span className="fsb-group-badge">{favs.length}</span>
                </button>
                {open && favs.map(fav => (
                  <FavSidebarItem
                    key={fav.path}
                    fav={fav}
                    groupName={group}
                    credentials={credentials}
                    onNavigate={onNavigate}
                    onRemove={() => favoritesService.remove(credentials.host, fav.path)}
                  />
                ))}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}
