// ---- Helpers -------------------------------------------------------------

function escapeRe(s: string) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') }

function logLineClass(line: string): string {
  if (/\b(error|err|exception|fatal|critical)\b/i.test(line)) return 'fv-line--error'
  if (/\bwarn(ing)?\b/i.test(line)) return 'fv-line--warn'
  if (/\binfo\b/i.test(line)) return 'fv-line--info'
  if (/\b(debug|trace|verbose)\b/i.test(line)) return 'fv-line--debug'
  return ''
}

function renderHighlighted(content: string, query: string, currentIdx: number): React.ReactNode {
  if (!query.trim()) return content
  const parts = content.split(new RegExp(`(${escapeRe(query)})`, 'gi'))
  let matchCount = 0
  return parts.map((part, i) => {
    if (i % 2 === 1) {
      const idx = matchCount++
      return <mark key={i} className={idx === currentIdx ? 'search-mark search-mark--current' : 'search-mark'}>{part}</mark>
    }
    return part
  })
}

// ---- Component -----------------------------------------------------------

const REMOTE_MODEL_TYPE = 'ch.minova.appmodel.remote.RemoteModel'

interface Props {
  path: string | null
  node: ModelNode | null
  credentials: HubCredentials
  maxDownloadMB: number
  autoLoadKB: number
  autoPreviewKB: number
  showJson: boolean
  autoLoadServiceInfo: boolean
  simpleMode: boolean
  onRefresh: (path: string) => void
  onDeleted: (path: string) => void
  onNavigate: (path: string) => void
}

let logIdSeq = 0

export function HubDetail({ path, node, credentials, maxDownloadMB, autoLoadKB, autoPreviewKB, showJson, autoLoadServiceInfo, simpleMode, onRefresh, onDeleted, onNavigate }: Props) {
  const [fullValue, setFullValue]       = useState<string>('')
  const [valueLoading, setValueLoading] = useState(false)
  const [revealPassword, setRevealPassword] = useState(false)
  const [collView, setCollView]         = useState<'table' | 'raw'>('table')
  type FileView = { kind: 'text'; content: string } | { kind: 'image' | 'pdf'; url: string }
  const [fileView, setFileView]       = useState<FileView | null>(null)
  const [fileLoading, setFileLoading] = useState(false)
  const [autoRefresh, setAutoRefresh] = useState(false)
  const [hasMoreAbove, setHasMoreAbove] = useState(false)
  const [hasMoreBelow, setHasMoreBelow] = useState(false)
  const [loadingMore,  setLoadingMore]  = useState(false)
  const [downloadProgress, setDownloadProgress] = useState<{ loaded: number; total: number } | null>(null)
  const [loadedRange, setLoadedRange] = useState<{ head: number; tail: number } | null>(null)
  const [jumpInput, setJumpInput]     = useState('')
  const fileScrollRef    = useRef<HTMLDivElement>(null)
  const filePreRef       = useRef<HTMLPreElement>(null)
  const headByteRef      = useRef(0)
  const tailByteRef      = useRef(0)
  const prependScrollRef = useRef<number | null>(null)

  function updateRange(head: number, tail: number) {
    headByteRef.current = head
    tailByteRef.current = tail
    setLoadedRange({ head, tail })
  }
  const [editContent, setEditContent] = useState<string | null>(null)
  const [saving, setSaving]           = useState(false)
  const [saveError, setSaveError]     = useState<string | null>(null)
  const downloadAbortRef = useRef<AbortController | null>(null)
  const fileExt        = (node?.name ?? path?.split('/').pop() ?? '').split('.').pop()?.toLowerCase() ?? ''
  const isLogFile      = fileExt === 'log' || fileExt === 'out' || fileExt === 'txt'
  const [searchOpen, setSearchOpen]       = useState(false)
  const [searchQuery, setSearchQuery]     = useState('')
  const [searchIdx, setSearchIdx]         = useState(0)
  const [filterLines, setFilterLines]         = useState(() => localStorage.getItem('hub.search.filterLines') === '1')
  const [activeSeverities, setActiveSeverities] = useState<Set<string>>(new Set())
  const searchInputRef = useRef<HTMLInputElement>(null)

  // Capture URL viewer params on mount — consumed once when the matching path first loads.
  // Must be a ref (not read inside an effect) because the URL-sync effect in HubTree
  // clears ?path= before async navigation completes.
  const urlInitRef = useRef((() => {
    const p = new URLSearchParams(window.location.search)
    return { path: p.get('path') ?? '', view: p.get('view') === '1', auto: p.get('auto') === '1' }
  })())

  // Derived: chunked mode is active when the node reports its byte length
  const rawContentLength = node ? nodeAttr(node, 'contentLength') : undefined
  const totalFileBytes   = rawContentLength !== undefined ? parseInt(rawContentLength, 10) : null
  const chunkedMode      = node !== null && node !== undefined && supportsChunkedRead(node)
                           && totalFileBytes !== null && totalFileBytes > autoPreviewKB * 1024
  // atTail: no known content below the loaded window — auto-refresh only makes sense here
  const atTail  = !chunkedMode || !hasMoreBelow
  const atStart = !chunkedMode || loadedRange?.head === 0

  // Revoke blob URLs when fileView changes to avoid memory leaks
  useEffect(() => {
    if (fileView?.kind === 'image' || fileView?.kind === 'pdf') {
      const url = fileView.url
      return () => URL.revokeObjectURL(url)
    }
  }, [fileView])

  useEffect(() => {
    if (!path || !node) { setFullValue(''); setFileView(null); setAutoRefresh(false); setSearchOpen(false); setSearchQuery(''); setSearchIdx(0); setActiveSeverities(new Set()); setHasMoreAbove(false); setHasMoreBelow(false); setLoadedRange(null); setJumpInput(''); setEditContent(null); setSaveError(null); headByteRef.current = 0; tailByteRef.current = 0; return }
    setEditContent(null)
    setSaveError(null)
    setFileView(null)
    setAutoRefresh(false)
    setSearchOpen(false)
    setSearchQuery('')
    setSearchIdx(0)
    setActiveSeverities(new Set())
    setHasMoreAbove(false)
    setHasMoreBelow(false)
    setLoadedRange(null)
    setJumpInput('')
    headByteRef.current = 0
    tailByteRef.current = 0

    // Restore viewer state from URL — one-shot, only for the path we landed on via URL
    const ui = urlInitRef.current
    if (ui.view && ui.path === path && (isLocalFile(node) || isBinary(node))) {
      urlInitRef.current = { path: '', view: false, auto: false } // consume
      loadContent(false)
      if (ui.auto) setAutoRefresh(true)
    } else if (isLocalFile(node) || isBinary(node)) {
      const vt = fileViewType(node.name ?? path.split('/').pop() ?? '')
      if (vt !== 'binary') {
        if (supportsChunkedRead(node)) {
          if (vt === 'text') {
            // Text tail-load reads at most autoPreviewKB * 1024 bytes — always safe
            loadContent(false)
          } else if (autoLoadKB > 0) {
            // Image/PDF: full download — respect the size limit
            const cl = nodeAttr(node, 'contentLength')
            const bytes = cl !== undefined ? parseInt(cl, 10) : parseSizeBytes(node.preview)
            if (bytes !== null && bytes < autoLoadKB * 1024) loadContent(false)
          }
        } else if (autoLoadKB > 0) {
          const bytes = parseSizeBytes(node.preview)
          if (bytes !== null && bytes < autoLoadKB * 1024) {
            loadContent(false)
          }
        }
      }
    }

    if (!isValueNode(node)) { setFullValue(node.preview ?? node.value ?? ''); return }
    setValueLoading(true)
    getValue(credentials, path).then(v => setFullValue(v)).catch(() => {
      setFullValue(node.preview ?? node.value ?? '')
    }).finally(() => setValueLoading(false))
  }, [path, node?.rid]) // eslint-disable-line react-hooks/exhaustive-deps

  // Sync viewer state to URL so the link can be shared
  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    if (fileView !== null) { params.set('view', '1') } else { params.delete('view') }
    if (autoRefresh) { params.set('auto', '1') } else { params.delete('auto') }
    window.history.replaceState(null, '', `${window.location.pathname}?${params.toString()}`)
  }, [fileView, autoRefresh])  

  // Auto-refresh — text only
  useEffect(() => {
    if (!autoRefresh || fileView?.kind !== 'text') return
    const id = setInterval(() => chunkedMode ? loadNewTail() : loadContent(true), 5000)
    return () => clearInterval(id)
  }, [autoRefresh, path, fileView?.kind, chunkedMode]) // eslint-disable-line react-hooks/exhaustive-deps

  // Restore scroll position after a prepend (must run synchronously after DOM update)
  useLayoutEffect(() => {
    if (prependScrollRef.current !== null && fileScrollRef.current) {
      fileScrollRef.current.scrollTop += fileScrollRef.current.scrollHeight - prependScrollRef.current
      prependScrollRef.current = null
    }
  })

  // Intercept Ctrl+F in capture phase so HubTree's global listener never fires
  useEffect(() => {
    if (fileView?.kind !== 'text') return
    function onKey(e: KeyboardEvent) {
      if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
        e.preventDefault()
        e.stopImmediatePropagation()
        setSearchOpen(true)
      }
    }
    document.addEventListener('keydown', onKey, true)
    return () => document.removeEventListener('keydown', onKey, true)
  }, [fileView?.kind])

  useEffect(() => { localStorage.setItem('hub.search.filterLines', filterLines ? '1' : '0') }, [filterLines])

  // Focus search input when opened
  useEffect(() => { if (searchOpen) searchInputRef.current?.focus() }, [searchOpen])

  const searchMatches = useMemo(() => {
    if (!searchQuery.trim() || fileView?.kind !== 'text') return 0
    return (fileView.content.match(new RegExp(escapeRe(searchQuery), 'gi')) ?? []).length
  }, [searchQuery, fileView])

  const displayLines = useMemo(() => {
    if (fileView?.kind !== 'text') return null
    const hasSeverity   = activeSeverities.size > 0
    const hasTextFilter = filterLines && !!searchQuery.trim()
    if (!isLogFile && !hasSeverity && !hasTextFilter && !atStart) return null
    const re = searchQuery.trim() ? new RegExp(escapeRe(searchQuery), 'gi') : null
    let offset = 0
    const result: { lineNum: number; text: string; cls: string; matchOffset: number }[] = []
    const lines = fileView.content.split('\n')
    for (let i = 0; i < lines.length; i++) {
      const text  = lines[i]
      const cls   = isLogFile ? logLineClass(text) : ''
      const cnt   = re ? (text.match(re) ?? []).length : 0
      const mo    = offset
      offset     += cnt
      if (hasSeverity   && !activeSeverities.has(cls)) continue
      if (hasTextFilter && cnt === 0)                  continue
      result.push({ lineNum: i + 1, text, cls, matchOffset: mo })
    }
    return result
  }, [activeSeverities, filterLines, searchQuery, isLogFile, fileView, atStart])

  const logCounts = useMemo(() => {
    if (!isLogFile || fileView?.kind !== 'text') return null
    const c = { debug: 0, info: 0, warn: 0, error: 0 }
    for (const line of fileView.content.split('\n')) {
      const cls = logLineClass(line)
      if      (cls === 'fv-line--error') c.error++
      else if (cls === 'fv-line--warn')  c.warn++
      else if (cls === 'fv-line--info')  c.info++
      else if (cls === 'fv-line--debug') c.debug++
    }
    return c
  }, [isLogFile, fileView])  

  // Clamp index when result count shrinks
  useEffect(() => {
    if (searchMatches > 0 && searchIdx >= searchMatches) setSearchIdx(searchMatches - 1)
  }, [searchMatches]) // eslint-disable-line react-hooks/exhaustive-deps

  // Scroll current match into view
  useEffect(() => {
    if (!searchOpen || !filePreRef.current || searchMatches === 0) return
    filePreRef.current.querySelectorAll<HTMLElement>('.search-mark')[searchIdx]?.scrollIntoView({ block: 'nearest' })
  }, [searchIdx, searchMatches, searchOpen])

  function searchNext() { setSearchIdx(i => searchMatches === 0 ? 0 : (i + 1) % searchMatches) }
  function searchPrev() { setSearchIdx(i => searchMatches === 0 ? 0 : (i - 1 + searchMatches) % searchMatches) }
  function toggleSeverity(cls: string) {
    setActiveSeverities(prev => { const s = new Set(prev); s.has(cls) ? s.delete(cls) : s.add(cls); return s })
  }

  function sizeWarning(): boolean {
    const bytes = parseSizeBytes(node?.preview)
    if (bytes === null) return true
    const mb = bytes / (1024 * 1024)
    return mb <= maxDownloadMB || confirm(`This file is ~${mb.toFixed(1)} MB which exceeds the ${maxDownloadMB} MB threshold. Continue anyway?`)
  }

  async function loadContent(preserveScroll: boolean) {
    if (!path || !node) return
    const vt: FileViewType = fileViewType(node.name ?? path.split('/').pop() ?? '')
    const scrollTop = preserveScroll && fileView?.kind === 'text'
      ? (fileScrollRef.current?.scrollTop ?? 0) : null
    setFileLoading(true)
    try {
      if (vt === 'text') {
        if (chunkedMode && totalFileBytes !== null) {
          const startByte = Math.max(0, totalFileBytes - autoPreviewKB * 1024)
          const { data } = await getValueRange(credentials, path, startByte, autoPreviewKB * 1024)
          const content = new TextDecoder('utf-8', { fatal: false }).decode(data)
          updateRange(startByte, startByte + data.byteLength)
          setHasMoreAbove(startByte > 0)
          setHasMoreBelow(false)
          setFileView({ kind: 'text', content })
        } else {
          const content = await getValue(credentials, path, 'text')
          setFileView({ kind: 'text', content })
        }
        requestAnimationFrame(() => {
          if (!fileScrollRef.current) return
          fileScrollRef.current.scrollTop = scrollTop !== null
            ? scrollTop : fileScrollRef.current.scrollHeight
        })
      } else {
        let url: string
        if (chunkedMode && totalFileBytes !== null) {
          const parts: BlobPart[] = []
          let offset = 0
          while (offset < totalFileBytes) {
            const { data } = await getValueRange(credentials, path, offset, DOWNLOAD_CHUNK_SIZE)
            parts.push(data)
            offset += (data as ArrayBuffer).byteLength
            if ((data as ArrayBuffer).byteLength < DOWNLOAD_CHUNK_SIZE) break
          }
          url = URL.createObjectURL(new Blob(parts))
        } else {
          url = await loadFileBlob(credentials, path)
        }
        setFileView({ kind: vt as 'image' | 'pdf', url })
      }
    } catch (err) {
      logStore.add({ severity: 'error', text: `View failed: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setFileLoading(false)
    }
  }

  async function loadNewTail() {
    if (!path || fileView?.kind !== 'text') return
    try {
      const { data } = await getValueRange(credentials, path, tailByteRef.current, autoPreviewKB * 1024)
      if (data.byteLength === 0) return
      const newText = new TextDecoder('utf-8', { fatal: false }).decode(data)
      const newTail = tailByteRef.current + data.byteLength
      tailByteRef.current = newTail
      setLoadedRange(prev => prev ? { ...prev, tail: newTail } : { head: 0, tail: newTail })
      const scrollEl = fileScrollRef.current
      const atBottom = scrollEl
        ? scrollEl.scrollHeight - scrollEl.scrollTop - scrollEl.clientHeight < 8
        : true
      setFileView(prev => prev?.kind === 'text' ? { kind: 'text', content: prev.content + newText } : prev)
      if (atBottom) requestAnimationFrame(() => {
        if (scrollEl) scrollEl.scrollTop = scrollEl.scrollHeight
      })
    } catch { /* non-fatal */ }
  }

  async function loadMoreAbove() {
    if (!path || !hasMoreAbove || loadingMore || headByteRef.current <= 0) return
    setLoadingMore(true)
    const startByte = Math.max(0, headByteRef.current - autoPreviewKB * 1024)
    const length    = headByteRef.current - startByte
    try {
      const { data } = await getValueRange(credentials, path, startByte, length)
      const newText = new TextDecoder('utf-8', { fatal: false }).decode(data)
      prependScrollRef.current = fileScrollRef.current?.scrollHeight ?? null
      headByteRef.current = startByte
      setLoadedRange(prev => prev ? { ...prev, head: startByte } : { head: startByte, tail: tailByteRef.current })
      setHasMoreAbove(startByte > 0)
      setFileView(prev => prev?.kind === 'text' ? { kind: 'text', content: newText + prev.content } : prev)
    } catch (err) {
      logStore.add({ severity: 'error', text: `Load failed: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setLoadingMore(false)
    }
  }

  async function loadMoreBelow() {
    if (!path || !hasMoreBelow || loadingMore || totalFileBytes === null) return
    setLoadingMore(true)
    try {
      const { data } = await getValueRange(credentials, path, tailByteRef.current, autoPreviewKB * 1024)
      if (data.byteLength === 0) { setHasMoreBelow(false); return }
      const newText = new TextDecoder('utf-8', { fatal: false }).decode(data)
      const newTail = tailByteRef.current + data.byteLength
      tailByteRef.current = newTail
      setLoadedRange(prev => prev ? { ...prev, tail: newTail } : { head: 0, tail: newTail })
      setHasMoreBelow(newTail < totalFileBytes)
      setFileView(prev => prev?.kind === 'text' ? { kind: 'text', content: prev.content + newText } : prev)
    } catch (err) {
      logStore.add({ severity: 'error', text: `Load failed: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setLoadingMore(false)
    }
  }

  async function loadFromByte(startByte: number) {
    if (!path || !node || totalFileBytes === null) return
    const clamped = Math.max(0, Math.min(startByte, totalFileBytes))
    setFileLoading(true)
    try {
      const { data } = await getValueRange(credentials, path, clamped, autoPreviewKB * 1024)
      const content = new TextDecoder('utf-8', { fatal: false }).decode(data)
      const newTail = clamped + data.byteLength
      updateRange(clamped, newTail)
      setHasMoreAbove(clamped > 0)
      setHasMoreBelow(newTail < totalFileBytes)
      setFileView({ kind: 'text', content })
      if (newTail < totalFileBytes) setAutoRefresh(false)
      requestAnimationFrame(() => { if (fileScrollRef.current) fileScrollRef.current.scrollTop = 0 })
    } catch (err) {
      logStore.add({ severity: 'error', text: `Jump failed: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setFileLoading(false)
    }
  }

  async function loadAllChunked() {
    if (!path || !node || totalFileBytes === null) return
    setFileLoading(true)
    try {
      const parts: string[] = []
      let offset = 0
      while (offset < totalFileBytes) {
        const { data } = await getValueRange(credentials, path, offset, DOWNLOAD_CHUNK_SIZE)
        parts.push(new TextDecoder('utf-8', { fatal: false }).decode(data))
        offset += (data as ArrayBuffer).byteLength
        if ((data as ArrayBuffer).byteLength < DOWNLOAD_CHUNK_SIZE) break
      }
      const content = parts.join('')
      updateRange(0, totalFileBytes)
      setHasMoreAbove(false)
      setHasMoreBelow(false)
      setFileView({ kind: 'text', content })
      requestAnimationFrame(() => { if (fileScrollRef.current) fileScrollRef.current.scrollTop = 0 })
    } catch (err) {
      logStore.add({ severity: 'error', text: `Load failed: ${err instanceof Error ? err.message : String(err)}` })
    } finally {
      setFileLoading(false)
    }
  }

  function handleJump() {
    const offset = parseInt(jumpInput, 10)
    if (isNaN(offset) || offset < 0) return
    if (loadedRange && offset >= loadedRange.head && offset < loadedRange.tail) {
      const frac = (offset - loadedRange.head) / (loadedRange.tail - loadedRange.head)
      if (fileScrollRef.current) fileScrollRef.current.scrollTop = frac * fileScrollRef.current.scrollHeight
    } else {
      loadFromByte(offset)
    }
  }

  function handleFileScroll(e: React.UIEvent<HTMLDivElement>) {
    const el = e.currentTarget
    if (el.scrollTop <= 0 && hasMoreAbove && !loadingMore) loadMoreAbove()
    if (el.scrollHeight - el.scrollTop - el.clientHeight < 8 && hasMoreBelow && !loadingMore) loadMoreBelow()
  }

  async function handleSetValue() {
    if (!path) return
    try {
      await setValue(credentials, path, fullValue)
      logStore.add({ severity: 'info', text: `${path} updated` })
      onRefresh(path)
    } catch (err) {
      logStore.add({ severity: 'error', text: err instanceof Error ? err.message : 'Set failed' })
    }
  }

  async function handleDelete() {
    if (!path || !node) return
    if (!confirm(`Delete ${path}?`)) return
    try {
      await deleteNode(credentials, path)
      logStore.add({ severity: 'info', text: `${path} deleted` })
      onDeleted(path)
    } catch (err) {
      logStore.add({ severity: 'error', text: err instanceof Error ? err.message : 'Delete failed' })
    }
  }

  async function handleDownload(openInTab = false) {
    if (!path || !node) return
    const filename = node.name ?? path.split('/').pop() ?? 'file'
    if (openInTab) {
      if (chunkedMode && totalFileBytes !== null && fileViewType(filename) === 'text') {
        const startAt = Math.max(0, totalFileBytes - autoPreviewKB * 1024)
        window.open(getValueUrl(credentials, path, 'text', startAt, autoPreviewKB * 1024), '_blank')
      } else {
        window.open(getValueUrl(credentials, path, viewStyle(filename)), '_blank')
      }
      return
    }
    if (chunkedMode && totalFileBytes !== null && totalFileBytes > 0) {
      const ctrl = new AbortController()
      downloadAbortRef.current = ctrl
      setDownloadProgress({ loaded: 0, total: totalFileBytes })
      try {
        await downloadFileChunked(credentials, path, filename, totalFileBytes,
          (loaded, total) => setDownloadProgress({ loaded, total }),
          ctrl.signal)
      } catch (err) {
        if ((err as DOMException).name !== 'AbortError') {
          logStore.add({ severity: 'error', text: `Download failed: ${err instanceof Error ? err.message : String(err)}` })
        }
      } finally {
        setDownloadProgress(null)
        downloadAbortRef.current = null
      }
      return
    }
    if (!sizeWarning()) return
    try {
      await downloadFile(credentials, path, filename)
    } catch (err) {
      logStore.add({ severity: 'error', text: `Download failed: ${err instanceof Error ? err.message : String(err)}` })
    }
  }

  const canDownload = node ? (isLocalFile(node) || isBinary(node)) : false
  const canDelete   = node ? (strTrue(node.deletable) || strTrue(node.deleteable)) : false
  const canSetValue = node ? (isValueNode(node) && !strTrue(node.readonly)) : false
  const viewType    = canDownload && node
    ? fileViewType(node.name ?? path?.split('/').pop() ?? '')
    : 'binary' as FileViewType
  const canViewInline = viewType !== 'binary'
  const isBigFile    = (parseSizeBytes(node?.preview) ?? 0) > 10_000_000
  const ctaBaseLabel = viewType === 'image' ? 'View image' : viewType === 'pdf' ? 'View document' : 'Load file contents'
  const ctaLabel     = isBigFile ? `${ctaBaseLabel} (big file)` : ctaBaseLabel
  // Modify: text file fully loaded (not chunked, or all bytes fetched) and not read-only
  const canModify = canDownload && viewType === 'text' && fileView?.kind === 'text'
    && atStart && atTail && !strTrue(node?.readonly)

  async function handleSave() {
    if (editContent === null || !path || !node) return
    const parentPath = path.substring(0, path.lastIndexOf('/'))
    const filename   = node.name ?? path.split('/').pop() ?? 'file'
    const uploadPath = parentPath + '/upload'
    const bytes = new TextEncoder().encode(editContent)
    let binary = ''
    for (let i = 0; i < bytes.length; i += 8192)
      binary += String.fromCharCode(...bytes.subarray(i, Math.min(i + 8192, bytes.length)))
    try {
      setSaving(true)
      setSaveError(null)
      await callCommand(credentials, uploadPath, { fileName: filename, data: btoa(binary), append: 'false' })
      setEditContent(null)
      loadContent(true)
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : String(err))
    } finally {
      setSaving(false)
    }
  }

  function handleCancelEdit() {
    setEditContent(null)
    setSaveError(null)
  }

  if (!path || !node) {
    return (
      <div className="hub-detail hub-detail--empty">
        <span>Select a node to view details</span>
      </div>
    )
  }

  if (node.remoteType === REMOTE_MODEL_TYPE || node.type === REMOTE_MODEL_TYPE) {
    return (
      <div className="hub-detail">
        <ModelPreview path={path} node={node} credentials={credentials} onNavigate={onNavigate} autoLoadServiceInfo={autoLoadServiceInfo} simpleMode={simpleMode} showJson={showJson} />
      </div>
    )
  }

  if (node.encapsulated === 'ch.minova.assist.data.SystemInfo' || node.remoteType === 'ch.minova.assist.data.SystemInfo' || node.type === 'ch.minova.assist.data.SystemInfo') {
    return (
      <div className="hub-detail">
        <SystemInfoPreview path={path} node={node} credentials={credentials} simpleMode={simpleMode} onNavigate={onNavigate} showJson={showJson} />
      </div>
    )
  }

  // Deployment/Issues node selected directly (expert mode)
  if (path.endsWith('/Deployment/Issues') || path.endsWith('/Deployment/Issues/Issues')) {
    return (
      <div className="hub-detail">
        <IssuesPreview path={path} node={node} credentials={credentials} onNavigate={onNavigate} showJson={showJson} />
      </div>
    )
  }

  return (
    <div className="hub-detail">
      <div className="detail-section">

        {/* Toolbar */}
        <div className="detail-toolbar">
          <button className="dib dib--refresh" onClick={() => onRefresh(path)} disabled={saving} title="Refresh node"><IcRefresh /></button>
          {canDownload && (
            <>
              <button className="dib dib--download" disabled={downloadProgress !== null || saving} onClick={e => handleDownload(e.ctrlKey || e.metaKey)} title="Download · Ctrl+click to open in tab"><IcDownload /></button>
              {downloadProgress !== null && (
                <span className="dib-download-progress">
                  {Math.round((downloadProgress.loaded / downloadProgress.total) * 100)}%
                  <button className="dib-download-cancel" onClick={() => downloadAbortRef.current?.abort()} title="Cancel">✕</button>
                </span>
              )}
            </>
          )}
          <button className="dib dib--delete" disabled={!canDelete || saving} onClick={handleDelete} title="Delete node"><IcDelete /></button>
          <button className="dib dib--apply" disabled={(editContent === null ? !canSetValue : false) || saving} onClick={editContent !== null ? handleSave : handleSetValue} title={editContent !== null ? 'Save changes' : 'Apply value'}><IcApply /></button>
          {editContent !== null
            ? <button className="dib dib--cancel-edit" onClick={handleCancelEdit} disabled={saving} title="Discard changes"><IcCancelEdit /></button>
            : canModify && (
                <button className="dib dib--modify" onClick={() => { setEditContent(fileView!.kind === 'text' ? fileView.content : '') }} title="Modify file"><IcEdit /></button>
              )
          }
        </div>

        <div className="detail-path" title={path}>{path}</div>

        {/* File/directory metadata: size and last-modified */}
        {(nodeAttr(node, 'contentLength') || nodeAttr(node, 'lastModified')) && (
          <div className="detail-meta-row">
            {nodeAttr(node, 'contentLength') != null && (
              <span className="detail-meta-item" title="File size">
                {formatBytes(parseFloat(nodeAttr(node, 'contentLength')!))}
              </span>
            )}
            {nodeAttr(node, 'lastModified') && (
              <span className="detail-meta-item" title="Last modified">
                {new Date(nodeAttr(node, 'lastModified')!).toLocaleString()}
              </span>
            )}
          </div>
        )}

        {isValueNode(node) && (() => {
          const ro = strTrue(node.readonly)
          const val = valueLoading ? '' : fullValue
          if (isPassword(node)) return (
            <div className="detail-value-row">
              <input
                type={revealPassword ? 'text' : 'password'}
                className="detail-value detail-value--single"
                value={val}
                readOnly={ro}
                placeholder={valueLoading ? 'Loading…' : undefined}
                onChange={e => setFullValue(e.target.value)}
              />
              <button className="detail-reveal-btn" onClick={() => setRevealPassword(v => !v)}
                title={revealPassword ? 'Hide' : 'Reveal'}>
                {revealPassword ? '🙈' : '👁'}
              </button>
            </div>
          )
          if (isTimestamp(node)) return (
            <div>
              <div className="detail-preview">{valueLoading ? 'Loading…' : formatTimestamp(val)}</div>
              {!ro && <textarea className="detail-value" value={val} onChange={e => setFullValue(e.target.value)}
                rows={2} spellCheck={false} placeholder="milliseconds since epoch" />}
            </div>
          )
          if (isUrl(node)) return (
            <div>
              {val && <a href={val} target="_blank" rel="noreferrer" className="detail-url-link">{val}</a>}
              {!ro && <input type="url" className="detail-value detail-value--single"
                value={val} onChange={e => setFullValue(e.target.value)}
                placeholder={valueLoading ? 'Loading…' : 'https://…'} />}
              {ro && !val && <div className="detail-preview">{valueLoading ? 'Loading…' : '—'}</div>}
            </div>
          )
          if (isList(node) || isMap(node)) {
            const pretty = (() => {
              if (valueLoading) return ''
              try { return JSON.stringify(JSON.parse(val), null, 2) } catch { return val }
            })()
            return (
              <div>
                <div className="coll-toggle-bar">
                  <button
                    className={`coll-toggle-btn${collView === 'table' ? ' coll-toggle-btn--active' : ''}`}
                    onClick={() => setCollView('table')}>Table</button>
                  <button
                    className={`coll-toggle-btn${collView === 'raw' ? ' coll-toggle-btn--active' : ''}`}
                    onClick={() => setCollView('raw')}>Raw</button>
                </div>
                {valueLoading
                  ? <div className="detail-preview">Loading…</div>
                  : collView === 'table'
                    ? <CollectionEditor
                        key={path}
                        value={val}
                        listType={node.listType}
                        isMap={isMap(node)}
                        readonly={ro}
                        onChange={json => setFullValue(json)}
                      />
                    : <textarea
                        className="detail-value detail-value--json"
                        value={pretty}
                        readOnly={ro}
                        rows={Math.min(Math.max(pretty.split('\n').length, 3), 16)}
                        spellCheck={false}
                        onChange={ro ? undefined : e => setFullValue(e.target.value)}
                      />
                }
              </div>
            )
          }
          return (
            <textarea
              className="detail-value"
              value={valueLoading ? 'Loading…' : val}
              readOnly={ro}
              onChange={e => setFullValue(e.target.value)}
              rows={4}
              spellCheck={false}
            />
          )
        })()}
        {node.preview && !isValueNode(node) && (
          <div className="detail-preview">{node.preview}</div>
        )}

        {/* Show CTA — only for viewable types, before content is loaded */}
        {canViewInline && fileView === null && (
          <button
            className={`detail-show-cta${isBigFile ? ' detail-show-cta--big' : ''}`}
            disabled={fileLoading}
            onClick={() => { if (sizeWarning()) loadContent(false) }}
          >
            {fileLoading ? <span className="detail-show-spinner">⟳</span> : <IcEye />}
            {fileLoading ? 'Loading…' : ctaLabel}
          </button>
        )}
      </div>

      {/* Inline file viewer */}
      {fileView !== null && (
        <div ref={fileScrollRef} className={`detail-file-view detail-file-view--${fileView.kind}${editContent !== null ? ' detail-file-view--editing' : ''}`} onScroll={handleFileScroll}>
          {fileView.kind === 'text' && (
            <>
              {editContent === null && hasMoreAbove && (
                <div className="fvp-load-more-bar">
                  {loadingMore
                    ? <span className="fvp-load-more-spinner">↑ Loading…</span>
                    : <button className="fvp-load-more-btn" onClick={loadMoreAbove}>
                        ↑ Load {formatBytes(autoPreviewKB * 1024)} earlier
                      </button>}
                </div>
              )}
              {editContent === null && searchOpen && (
                <div className="file-search-bar">
                  <input
                    ref={searchInputRef}
                    className="file-search-input"
                    value={searchQuery}
                    onChange={e => {
                      setSearchQuery(e.target.value)
                      setSearchIdx(0)
                    }}
                    onKeyDown={e => {
                      if (e.key === 'Enter') { e.shiftKey ? searchPrev() : searchNext(); e.preventDefault() }
                      if (e.key === 'Escape') { setSearchOpen(false); setSearchQuery('') }
                    }}
                    placeholder="Search in file…"
                    spellCheck={false}
                  />
                  {searchQuery && (
                    <span className="file-search-count">
                      {filterLines || activeSeverities.size > 0
                        ? `${displayLines?.length ?? 0} lines`
                        : searchMatches > 0 ? `${searchIdx + 1} / ${searchMatches}` : '0 / 0'}
                    </span>
                  )}
                  <button className="file-search-nav" onClick={searchPrev} disabled={searchMatches === 0} title="Previous (Shift+Enter)"><IcChevUp /></button>
                  <button className="file-search-nav" onClick={searchNext} disabled={searchMatches === 0} title="Next (Enter)"><IcChevDown /></button>
                  <button
                    className={`file-search-nav${filterLines ? ' file-search-nav--on' : ''}`}
                    onClick={() => setFilterLines(v => !v)}
                    disabled={!searchQuery}
                    title={filterLines ? 'Show all lines' : 'Show matching lines only'}
                  ><IcLines /></button>
                  <button className="file-search-close" onClick={() => { setSearchOpen(false); setSearchQuery('') }}>✕</button>
                </div>
              )}
              {editContent !== null
                ? <textarea
                    className="detail-file-edit"
                    value={editContent}
                    onChange={e => setEditContent(e.target.value)}
                    spellCheck={false}
                    autoFocus
                  />
                : <pre ref={filePreRef} className="detail-file-pre">
                    {displayLines
                      ? displayLines.map(({ lineNum, text, cls, matchOffset }, i) => (
                          <span key={i} className={`fv-line${cls ? ' ' + cls : ''}`}>
                            {(filterLines || activeSeverities.size > 0 || atStart) && <span className="search-ln">{lineNum}</span>}
                            {searchOpen && searchQuery
                              ? renderHighlighted(text, searchQuery, searchIdx - matchOffset)
                              : text}
                          </span>
                        ))
                      : searchOpen && searchQuery
                        ? renderHighlighted(fileView.content, searchQuery, searchIdx)
                        : fileView.content}
                  </pre>
              }
              {editContent === null && hasMoreBelow && (
                <div className="fvp-load-more-bar fvp-load-more-bar--below">
                  {loadingMore
                    ? <span className="fvp-load-more-spinner">↓ Loading…</span>
                    : <button className="fvp-load-more-btn" onClick={loadMoreBelow}>
                        ↓ Load {formatBytes(autoPreviewKB * 1024)} more
                      </button>}
                </div>
              )}
              {saveError && <div className="detail-save-error">{saveError}</div>}
              {editContent === null && <div className="file-pill-row">
                {logCounts && (
                  <div className="file-log-counts-pill">
                    {logCounts.error > 0 && <button className={`lc-chip lc-chip--error${activeSeverities.has('fv-line--error') ? ' lc-chip--on' : ''}`} onClick={() => toggleSeverity('fv-line--error')} title="Toggle error lines">{logCounts.error}</button>}
                    {logCounts.warn  > 0 && <button className={`lc-chip lc-chip--warn${activeSeverities.has('fv-line--warn')   ? ' lc-chip--on' : ''}`} onClick={() => toggleSeverity('fv-line--warn')}  title="Toggle warning lines">{logCounts.warn}</button>}
                    {logCounts.info  > 0 && <button className={`lc-chip lc-chip--info${activeSeverities.has('fv-line--info')   ? ' lc-chip--on' : ''}`} onClick={() => toggleSeverity('fv-line--info')}  title="Toggle info lines">{logCounts.info}</button>}
                    {logCounts.debug > 0 && <button className={`lc-chip lc-chip--debug${activeSeverities.has('fv-line--debug') ? ' lc-chip--on' : ''}`} onClick={() => toggleSeverity('fv-line--debug')} title="Toggle debug lines">{logCounts.debug}</button>}
                  </div>
                )}
                <div className="file-refresh-pill">
                  <button className="file-pill-half" onClick={() => loadContent(true)} disabled={fileLoading} title="Refresh">
                    <IcRefresh />
                  </button>
                  <button
                    className={`file-pill-half file-pill-auto${autoRefresh ? ' file-pill-auto--on' : ''}`}
                    onClick={() => setAutoRefresh(v => !v)}
                    title={autoRefresh ? 'Auto-refresh on · click to stop' : atTail ? 'Enable auto-refresh (5 s)' : 'Auto-refresh disabled — not at file tail'}
                    disabled={!atTail}
                  >
                    <IcClock /> 5s
                  </button>
                  <button
                    className={`file-pill-half${searchOpen ? ' file-pill-auto--on' : ''}`}
                    onClick={() => setSearchOpen(v => !v)}
                    title="Search in file (Ctrl+F)"
                  >
                    <IcSearch />
                  </button>
                </div>
                {chunkedMode && loadedRange !== null && totalFileBytes !== null && (
                  <div className="file-nav-pill">
                    <span className="file-nav-range" title={`Loaded bytes ${loadedRange.head}–${loadedRange.tail} of ${totalFileBytes}`}>
                      {formatBytes(loadedRange.head)}–{formatBytes(loadedRange.tail)} / {formatBytes(totalFileBytes)}
                    </span>
                    <button className="file-pill-half" onClick={() => loadFromByte(0)} disabled={fileLoading || loadedRange.head === 0} title="Jump to start">⏮</button>
                    <button className="file-pill-half" onClick={() => loadFromByte(Math.max(0, totalFileBytes - autoPreviewKB * 1024))} disabled={fileLoading || atTail} title="Jump to end">⏭</button>
                    <button className="file-pill-half" onClick={loadAllChunked} disabled={fileLoading} title="Load entire file into preview">⇊</button>
                    <input
                      type="number"
                      className="file-nav-input"
                      value={jumpInput}
                      onChange={e => setJumpInput(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleJump()}
                      placeholder="byte…"
                      min={0}
                      max={totalFileBytes}
                    />
                    <button className="file-pill-half" onClick={handleJump} disabled={fileLoading || !jumpInput.trim()} title="Jump to byte offset">Go</button>
                  </div>
                )}
              </div>}
            </>
          )}
          {fileView.kind === 'image' && (
            <img className="detail-file-img" src={fileView.url} alt={node?.name ?? ''} />
          )}
          {fileView.kind === 'pdf' && (
            <embed className="detail-file-pdf" src={fileView.url} type="application/pdf" />
          )}
        </div>
      )}

      {/* JSON panel — only when enabled in settings */}
      {showJson && (
        <div className="detail-accordion">
          <div className="accordion-header open">
            <span className="accordion-arrow" />
            JSON
          </div>
          <div className="accordion-body">
            <pre className="json-view">{JSON.stringify(node, null, 2)}</pre>
          </div>
        </div>
      )}
    </div>
  )
}

// eslint-disable-next-line react-refresh/only-export-components
export function extractLogs(result: ModelNode | string): LogMessage[] {
  if (typeof result === 'string') return []
  const logNode = result.children?.find(c => c.name === 'Log')
  if (!logNode?.children) return []
  return logNode.children.map(child => {
    const parsed = parseLogText(child.preview ?? '')
    return { ...parsed, id: ++logIdSeq }
  })
}
