import React, { useState, useMemo } from 'react'
import './CollectionEditor.css'

interface Props {
  value: string       // JSON string — array or object
  listType?: string   // "text" | "integer" | "decimal" | "bool" | "choice"
  isMap: boolean
  readonly: boolean
  onChange: (json: string) => void
}

/**
 * Renders a List<T> or Map<K,V> value as an editable table with inline search.
 *
 * Mount with key={path} in the parent so the component remounts (and re-reads
 * the initial value) whenever the selected node changes.
 */
export function CollectionEditor({ value, listType, isMap, readonly, onChange }: Props) {
  const [items, setItems] = useState<string[]>(() =>
    isMap ? parseMapValues(value) : parseList(value))
  const [keys, setKeys] = useState<string[]>(() =>
    isMap ? parseKeys(value) : [])
  const [newKey, setNewKey] = useState('')
  const [newVal, setNewVal] = useState('')
  const [filter, setFilter] = useState('')

  const filterLower = filter.toLowerCase()
  const visibleIndices = useMemo(() => {
    if (!filterLower) return items.map((_, i) => i)
    return items.reduce<number[]>((acc, val, i) => {
      const key = isMap ? (keys[i] ?? '') : String(i)
      if (key.toLowerCase().includes(filterLower) || val.toLowerCase().includes(filterLower))
        acc.push(i)
      return acc
    }, [])
  }, [items, keys, filter, isMap]) // eslint-disable-line react-hooks/exhaustive-deps

  function emit(ks: string[], vs: string[]) {
    if (isMap) {
      const obj: Record<string, string> = {}
      ks.forEach((k, i) => { if (k) obj[k] = vs[i] ?? '' })
      onChange(JSON.stringify(obj))
    } else {
      onChange(JSON.stringify(vs))
    }
  }

  function updateValue(i: number, v: string) {
    const next = [...items]; next[i] = v
    setItems(next); emit(keys, next)
  }

  function remove(i: number) {
    const ni = items.filter((_, j) => j !== i)
    const nk = keys.filter((_, j) => j !== i)
    setItems(ni); setKeys(nk); emit(nk, ni)
  }

  function add() {
    if (isMap) {
      if (!newKey.trim()) return
      const nk = [...keys, newKey.trim()]
      const ni = [...items, newVal]
      setKeys(nk); setItems(ni); emit(nk, ni)
      setNewKey(''); setNewVal('')
    } else {
      const ni = [...items, newVal]
      setItems(ni); emit(keys, ni)
      setNewVal('')
    }
  }

  const hasSearch = items.length > 6

  return (
    <div className="coll-wrap">
      {hasSearch && (
        <div className="coll-search-bar">
          <input
            className="coll-search-input"
            value={filter}
            onChange={e => setFilter(e.target.value)}
            placeholder={`Filter ${items.length} entries…`}
            spellCheck={false}
          />
          {filter && (
            <button className="coll-search-clear" onClick={() => setFilter('')} title="Clear">×</button>
          )}
        </div>
      )}
      <table className="coll-table">
        <thead>
          <tr>
            <th className={`coll-th ${isMap ? 'coll-th--key' : 'coll-th--idx'}`}>
              {isMap ? 'Key' : '#'}
            </th>
            <th className="coll-th coll-th--val">
              Value
              {filter && <span className="coll-match-count"> ({visibleIndices.length}/{items.length})</span>}
            </th>
            {!readonly && <th className="coll-th coll-th--act" />}
          </tr>
        </thead>
        <tbody>
          {visibleIndices.map(i => (
            <tr key={isMap ? keys[i] : i} className="coll-row">
              {isMap
                ? <td className="coll-key" title={keys[i]}>{keys[i]}</td>
                : <td className="coll-idx">{i}</td>}
              <td className="coll-val">
                <ItemInput listType={listType} value={items[i]} readonly={readonly}
                  onChange={v => updateValue(i, v)} />
              </td>
              {!readonly && (
                <td className="coll-act">
                  <button className="coll-btn coll-btn--rm" onClick={() => remove(i)} title="Remove">×</button>
                </td>
              )}
            </tr>
          ))}
        </tbody>
        {!readonly && (
          <tfoot>
            <tr className="coll-add-row">
              {isMap && (
                <td>
                  <input className="coll-input coll-new-key" placeholder="new key"
                    value={newKey} onChange={e => setNewKey(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && add()} />
                </td>
              )}
              <td colSpan={isMap ? 1 : 2}>
                <ItemInput listType={listType} value={newVal} readonly={false}
                  onChange={setNewVal} onEnter={add} placeholder="value" />
              </td>
              <td className="coll-act">
                <button className="coll-btn coll-btn--add"
                  onClick={add} disabled={isMap && !newKey.trim()} title="Add">+</button>
              </td>
            </tr>
          </tfoot>
        )}
      </table>
      {items.length === 0 && (
        <div className="coll-empty">—</div>
      )}
      {items.length > 0 && visibleIndices.length === 0 && (
        <div className="coll-empty">No matches</div>
      )}
    </div>
  )
}

// ---- Item input ------------------------------------------------------------

interface ItemInputProps {
  listType?: string
  value: string
  readonly: boolean
  onChange: (v: string) => void
  onEnter?: () => void
  placeholder?: string
}

function ItemInput({ listType, value, readonly, onChange, onEnter, placeholder }: ItemInputProps) {
  const onKey = onEnter
    ? (e: React.KeyboardEvent) => { if (e.key === 'Enter') onEnter() }
    : undefined

  if (listType === 'bool') {
    return (
      <input type="checkbox" className="coll-checkbox"
        checked={value === 'true'} disabled={readonly}
        onChange={e => onChange(String(e.target.checked))} />
    )
  }
  return (
    <input className="coll-input"
      type={listType === 'integer' || listType === 'decimal' ? 'number' : 'text'}
      value={value} readOnly={readonly} placeholder={placeholder}
      onChange={e => onChange(e.target.value)}
      onKeyDown={onKey} />
  )
}

// ---- JSON helpers ----------------------------------------------------------

function parseList(json: string): string[] {
  try {
    const p = JSON.parse(json || '[]')
    if (Array.isArray(p)) return p.map(String)
  } catch { /* ignore */ }
  return []
}

function parseKeys(json: string): string[] {
  try {
    const p = JSON.parse(json || '{}')
    if (p && typeof p === 'object' && !Array.isArray(p)) return Object.keys(p)
  } catch { /* ignore */ }
  return []
}

function parseMapValues(json: string): string[] {
  try {
    const p = JSON.parse(json || '{}')
    if (p && typeof p === 'object' && !Array.isArray(p))
      return Object.values(p).map(String)
  } catch { /* ignore */ }
  return []
}
