import { useEffect, useRef } from 'react'
import './ContextMenu.css'

export interface MenuItem {
  label: string
  icon?: string
  iconUrl?: string   // blob/object URL for image icons
  cmd: string
  disabled?: boolean
  danger?: boolean
}

interface Props {
  x: number
  y: number
  items: MenuItem[]
  onSelect: (cmd: string) => void
  onClose: () => void
}

export function ContextMenu({ x, y, items, onSelect, onClose }: Props) {
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose()
    }
    function handleKey(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('mousedown', handleClick)
    document.addEventListener('keydown', handleKey)
    return () => {
      document.removeEventListener('mousedown', handleClick)
      document.removeEventListener('keydown', handleKey)
    }
  }, [onClose])

  // Clamp to viewport
  const style: React.CSSProperties = {
    position: 'fixed',
    left: Math.min(x, window.innerWidth - 200),
    top: Math.min(y, window.innerHeight - items.length * 32 - 8),
  }

  if (items.length === 0) return null

  return (
    <div ref={ref} className="context-menu" style={style}>
      {items.map((item, i) => (
        item.label === '---'
          ? <div key={i} className="context-menu-separator" />
          : (
            <button
              key={i}
              className={`context-menu-item${item.danger ? ' danger' : ''}${item.disabled ? ' disabled' : ''}`}
              disabled={item.disabled}
              onClick={() => { onSelect(item.cmd); onClose() }}
            >
              {item.iconUrl
                ? <img className="context-menu-icon context-menu-icon--img" src={item.iconUrl} alt="" />
                : item.icon && <span className="context-menu-icon">{item.icon}</span>}
              {item.label}
            </button>
          )
      ))}
    </div>
  )
}
