import { useState, useCallback, useRef } from 'react'
import type { HubCredentials, HubSettings, ModelNode } from './types/hub'
import { DEFAULT_SETTINGS } from './types/hub'
import type { HubTreeHandle } from './components/HubTree'
import { saveCredentials, clearCredentials } from './services/authService'
import { getNode } from './services/hubApi'
import { loadSettings, saveSettings, hasSettings } from './services/settingsService'
import { profileService } from './services/profileService'
import { logStore } from './services/logStore'
import { LoginDialog } from './components/LoginDialog'
import { SettingsDialog } from './components/SettingsDialog'
import { HubTree } from './components/HubTree'
import { HubDetail } from './components/HubDetail'
import { clearServiceDataCache } from './components/ModelPreview'
import { clearSysInfoCache } from './components/SystemInfoPreview'
import { FavoritesSidebar } from './components/FavoritesSidebar'
import { LogChip } from './components/LogChip'
import { Toaster } from './components/Toaster'
import './App.css'

interface Props {
  initialCredentials?: HubCredentials | null
}

export function App({ initialCredentials = null }: Props) {
  const [credentials, setCredentials] = useState<HubCredentials | null>(initialCredentials)
  const [settings, setSettings] = useState<HubSettings>(() =>
    credentials ? loadSettings(credentials.host) : { ...DEFAULT_SETTINGS }
  )
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [selectedPath, setSelectedPath] = useState<string | null>(null)
  const [selectedNode, setSelectedNode] = useState<ModelNode | null>(null)
  const [treePanelWidth, setTreePanelWidth] = useState(520)
  const [mobileDetailOpen, setMobileDetailOpen] = useState(false)
  const [mobileTreeOpen, setMobileTreeOpen]     = useState(false)
  const dragging = useRef(false)
  const hubTreeRef = useRef<HubTreeHandle>(null)

  function handleLogin(creds: HubCredentials, remember: boolean) {
    saveCredentials(creds, remember)
    setCredentials(creds)
    const base = loadSettings(creds.host)
    setSettings(base)
    if (!hasSettings(creds.host)) {
      profileService.fetchDefaults(creds).then(profile => {
        if (!profile) return
        profileService.apply(profile, creds.host)
        const merged = profileService.mergeSettings(profile)
        saveSettings(creds.host, merged)
        setSettings(merged)
      }).catch(() => {})
    }
  }

  function handleLogout() {
    clearCredentials()
    clearServiceDataCache()
    clearSysInfoCache()
    setCredentials(null)
    setSelectedPath(null)
    setSelectedNode(null)
    setMobileDetailOpen(false)
    setMobileTreeOpen(false)
    logStore.clear()
  }

  function handleSettingsSave(s: HubSettings) {
    if (credentials) saveSettings(credentials.host, s)
    setSettings(s)
    setSettingsOpen(false)
  }

  const handleSelectNode = useCallback((path: string, node: ModelNode) => {
    setSelectedPath(path)
    setSelectedNode(node)
    setMobileDetailOpen(true)
    setMobileTreeOpen(false)
  }, [])

  function handleRefresh(path: string) {
    // Signal tree to reload this node by changing key or via a ref callback
    // For now, update selected node data by reloading
    if (credentials) {
      getNode(credentials, path, 1).then(node => {
        if (path === selectedPath) setSelectedNode(node)
      }).catch(() => {})
    }
  }

  function handleNavigate(path: string) {
    hubTreeRef.current?.navigate(path)
  }

  function handleDeleted(path: string) {
    if (path === selectedPath) {
      setSelectedPath(null)
      setSelectedNode(null)
      setMobileDetailOpen(false)
    }
  }

  function handleMobileBack() {
    setMobileDetailOpen(false)
    setMobileTreeOpen(false)
  }

  // Resizable split pane
  function startResize(e: React.MouseEvent) {
    e.preventDefault()
    dragging.current = true
    const startX = e.clientX
    const startW = treePanelWidth

    function onMove(e: MouseEvent) {
      if (!dragging.current) return
      setTreePanelWidth(Math.max(240, Math.min(window.innerWidth * 0.75, startW + e.clientX - startX)))
    }
    function onUp() {
      dragging.current = false
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
  }

  if (!credentials) {
    return <LoginDialog onLogin={handleLogin} />
  }

  const appClass = [
    'app',
    mobileDetailOpen && 'app--mobile-detail',
    mobileTreeOpen   && 'app--mobile-tree',
  ].filter(Boolean).join(' ')

  return (
    <div className={appClass}>
      <header className="app-header">
        <button className="header-icon-btn header-nav-btn" onClick={handleMobileBack} title="Back to tree">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6"/>
          </svg>
        </button>
        <span className="app-title">MINOVA Hub</span>
        <div className="app-header-info">
          <span className="app-host" title={credentials.host}>{credentials.host}</span>
          <span className="app-user">👤 {credentials.username}</span>
        </div>
        <div className="app-header-actions">
          <button className="header-icon-btn" onClick={() => setSettingsOpen(true)} title="Settings">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="3"/>
              <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>
            </svg>
          </button>
          <button className="header-icon-btn header-icon-btn--danger" onClick={handleLogout} title="Disconnect">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/>
              <polyline points="16 17 21 12 16 7"/>
              <line x1="21" y1="12" x2="9" y2="12"/>
            </svg>
          </button>
        </div>
      </header>

      <div className="app-body">
        <div className="tree-panel" style={{ width: treePanelWidth }}>
          <FavoritesSidebar credentials={credentials} onNavigate={handleNavigate} />
          <HubTree
            ref={hubTreeRef}
            credentials={credentials}
            settings={settings}
            onSelectNode={handleSelectNode}
          />
        </div>

        <div className="resize-handle" onMouseDown={startResize} />

        {mobileTreeOpen && <div className="mobile-backdrop" onClick={() => setMobileTreeOpen(false)} />}

        <button
          className="mobile-tree-btn"
          onClick={() => setMobileTreeOpen(v => !v)}
          title="Tree"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/>
          </svg>
        </button>

        <div className="detail-panel">
          {credentials && (
            <HubDetail
              path={selectedPath}
              node={selectedNode}
              credentials={credentials}
              maxDownloadMB={settings.maxDownloadMB}
              autoLoadKB={settings.autoLoadKB}
              autoPreviewKB={settings.autoPreviewKB}
              showJson={settings.showJson}
              autoLoadServiceInfo={settings.autoLoadServiceInfo ?? false}
              simpleMode={settings.mode === 'simple'}
              onRefresh={handleRefresh}
              onDeleted={handleDeleted}
              onNavigate={handleNavigate}
            />
          )}
        </div>
      </div>

      {settingsOpen && (
        <SettingsDialog
          settings={settings}
          credentials={credentials}
          onSave={handleSettingsSave}
          onClose={() => setSettingsOpen(false)}
        />
      )}

      <LogChip />
      <Toaster />
    </div>
  )
}
