import { useEffect, useRef, type RefObject } from 'react'

const COUNT = 55
const MAX_DIST = 150
const MAX_DIST_CENTER = 220
const BASE_SPEED = 0.18
const BORDER_ZONE = 80
const BORDER_FORCE = 0.0006

interface Particle {
  x: number; y: number
  vx: number; vy: number
  r: number
  hub: boolean
  pulse: number
}

interface Theme {
  bg: string
  nodeHub: string
  nodeReg: string
  edge: [number, number, number]   // RGB for rgba()
  pulseRing: [number, number, number]
}

const DARK: Theme = {
  bg:       '#090d18',
  nodeHub:  '241,188,15',
  nodeReg:  '200,155,15',
  edge:     [241, 188, 15],
  pulseRing:[241, 188, 15],
}

const LIGHT: Theme = {
  bg:       '#ffffff',
  nodeHub:  '140,140,140',
  nodeReg:  '160,160,160',
  edge:     [150, 150, 150],
  pulseRing:[140, 140, 140],
}

function makeParticles(w: number, h: number, cx: number, cy: number): Particle[] {
  const spread = Math.min(w, h) * 0.45
  return Array.from({ length: COUNT }, () => {
    const hub = Math.random() < 0.14
    const angle = Math.random() * Math.PI * 2
    const speed = BASE_SPEED * (0.4 + Math.random() * 0.8)
    return {
      x: cx + (Math.random() - 0.5) * spread * 2,
      y: cy + (Math.random() - 0.5) * spread * 2,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      r: hub ? 3.5 + Math.random() * 2 : 1.8 + Math.random() * 1.5,
      hub,
      pulse: 0,
    }
  })
}

interface Props {
  logoRef?: RefObject<HTMLImageElement | null>
}

export function NetworkCanvas({ logoRef }: Props) {
  const ref = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = ref.current as HTMLCanvasElement
    if (!canvas) return
    const ctx = canvas.getContext('2d')!
    let particles: Particle[] = []
    let raf: number
    let prev = 0
    let cx = window.innerWidth / 2
    let cy = window.innerHeight / 2

    function updateCenter() {
      const el = logoRef?.current
      if (el) {
        const r = el.getBoundingClientRect()
        cx = r.left + r.width / 2
        cy = r.top + r.height / 2
      } else {
        cx = canvas.width / 2
        cy = canvas.height / 2
      }
    }

    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    let dark = mq.matches

    function resize() {
      const prevW = canvas.width || window.innerWidth
      const prevH = canvas.height || window.innerHeight
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
      updateCenter()
      if (particles.length === 0) {
        particles = makeParticles(canvas.width, canvas.height, cx, cy)
      } else {
        // Scale existing positions proportionally — no sudden jumps
        const sx = canvas.width / prevW
        const sy = canvas.height / prevH
        for (const p of particles) {
          p.x = Math.min(p.x * sx, canvas.width)
          p.y = Math.min(p.y * sy, canvas.height)
        }
      }
    }

    function tick(now: number) {
      raf = requestAnimationFrame(tick)
      if (document.hidden) return

      const dt = Math.min(now - prev, 64)
      prev = now
      const { width: w, height: h } = canvas
      const theme = dark ? DARK : LIGHT
      const [er, eg, eb] = theme.edge
      const [pr, pg, pb] = theme.pulseRing

      ctx.fillStyle = theme.bg
      ctx.fillRect(0, 0, w, h)

      updateCenter()

      for (const p of particles) {
        // Soft border repulsion — nudge away from edges before they reach them
        if (p.x < BORDER_ZONE)     p.vx += (BORDER_ZONE - p.x)       * BORDER_FORCE * dt
        if (p.x > w - BORDER_ZONE) p.vx -= (p.x - (w - BORDER_ZONE)) * BORDER_FORCE * dt
        if (p.y < BORDER_ZONE)     p.vy += (BORDER_ZONE - p.y)       * BORDER_FORCE * dt
        if (p.y > h - BORDER_ZONE) p.vy -= (p.y - (h - BORDER_ZONE)) * BORDER_FORCE * dt
        // Speed clamp so border nudges don't accumulate
        const spd = Math.sqrt(p.vx * p.vx + p.vy * p.vy)
        const max = BASE_SPEED * 1.4
        if (spd > max) { p.vx = p.vx / spd * max; p.vy = p.vy / spd * max }

        p.x += p.vx * dt * 0.06
        p.y += p.vy * dt * 0.06
        p.x = Math.max(0, Math.min(w, p.x))
        p.y = Math.max(0, Math.min(h, p.y))
        if (p.pulse > 0) p.pulse = Math.max(0, p.pulse - dt * 0.0018)
      }

      if (Math.random() < 0.008)
        particles[Math.floor(Math.random() * particles.length)].pulse = 1

      // Edges
      for (let i = 0; i < particles.length - 1; i++) {
        const a = particles[i]
        for (let j = i + 1; j < particles.length; j++) {
          const b = particles[j]
          const dx = a.x - b.x, dy = a.y - b.y
          const d2 = dx * dx + dy * dy
          if (d2 > MAX_DIST * MAX_DIST) continue
          const t = 1 - Math.sqrt(d2) / MAX_DIST
          const alpha = t * t * (a.hub || b.hub ? 0.5 : 0.28)
          ctx.strokeStyle = `rgba(${er},${eg},${eb},${alpha.toFixed(3)})`
          ctx.lineWidth = a.hub || b.hub ? 0.8 : 0.4
          ctx.beginPath()
          ctx.moveTo(a.x, a.y)
          ctx.lineTo(b.x, b.y)
          ctx.stroke()
        }
      }

      // Edges to center hub
      for (const p of particles) {
        const dx = p.x - cx, dy = p.y - cy
        const d2 = dx * dx + dy * dy
        if (d2 > MAX_DIST_CENTER * MAX_DIST_CENTER) continue
        const t = 1 - Math.sqrt(d2) / MAX_DIST_CENTER
        const alpha = t * t * (p.hub ? 0.55 : 0.32)
        ctx.strokeStyle = `rgba(${er},${eg},${eb},${alpha.toFixed(3)})`
        ctx.lineWidth = p.hub ? 1.0 : 0.5
        ctx.beginPath()
        ctx.moveTo(p.x, p.y)
        ctx.lineTo(cx, cy)
        ctx.stroke()
      }

      // Nodes
      for (const p of particles) {
        if (p.pulse > 0) {
          ctx.beginPath()
          ctx.arc(p.x, p.y, p.r + p.pulse * 10, 0, Math.PI * 2)
          ctx.strokeStyle = `rgba(${pr},${pg},${pb},${(p.pulse * 0.4).toFixed(3)})`
          ctx.lineWidth = 1
          ctx.stroke()
        }
        ctx.beginPath()
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
        const alpha = p.hub ? 0.85 + p.pulse * 0.15 : 0.5 + p.pulse * 0.15
        ctx.fillStyle = p.hub
          ? `rgba(${theme.nodeHub},${alpha.toFixed(3)})`
          : `rgba(${theme.nodeReg},${alpha.toFixed(3)})`
        ctx.fill()
      }
    }

    function onSchemeChange(e: MediaQueryListEvent) { dark = e.matches }
    mq.addEventListener('change', onSchemeChange)

    resize()
    window.addEventListener('resize', resize)
    raf = requestAnimationFrame(tick)
    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener('resize', resize)
      mq.removeEventListener('change', onSchemeChange)
    }
  }, [logoRef])

  return <canvas ref={ref} className="network-canvas" />
}
