// ---- Tree state -------------------------------------------------------

interface TreeEntry {
  data: ModelNode
  childPaths: string[] | null  // null = not yet fetched from backend
  loading: boolean
}

interface TreeState {
  entries: Record<string, TreeEntry>
  expanded: Set<string>
  selected: string | null
  rootLoaded: boolean
}

type TreeAction =
  | { type: 'SET_ENTRY'; path: string; data: ModelNode; childPaths: string[] | null }
  | { type: 'SET_LOADING'; path: string; loading: boolean }
  | { type: 'SET_CHILDREN'; path: string; children: ModelNode[] }
  | { type: 'EXPAND'; path: string }
  | { type: 'COLLAPSE'; path: string }
  | { type: 'SELECT'; path: string | null }
  | { type: 'UPDATE_VALUE'; path: string; value: string }
  | { type: 'REMOVE'; path: string }
  | { type: 'RESET' }

function treeReducer(state: TreeState, action: TreeAction): TreeState {
  switch (action.type) {
    case 'RESET':
      return { entries: {}, expanded: new Set<string>(), selected: null, rootLoaded: false }

    case 'SET_ENTRY':
      return {
        ...state,
        rootLoaded: true,
        entries: {
          ...state.entries,
          [action.path]: { data: action.data, childPaths: action.childPaths, loading: false },
        },
      }

    case 'SET_LOADING': {
      const prev = state.entries[action.path]
      if (!prev) return state
      return { ...state, entries: { ...state.entries, [action.path]: { ...prev, loading: action.loading } } }
    }

    case 'SET_CHILDREN': {
      const parent = state.entries[action.path]
      if (!parent) return state
      const newEntries: Record<string, TreeEntry> = { ...state.entries }
      const seenPaths = new Set<string>()
      const childPaths: string[] = []
      for (const child of action.children) {
        const cp = `${action.path}/${child.name}`
        child.fullPath = cp
        const hasKnownChildren = strNum(child.childrenCount, 0) > 0
        newEntries[cp] = {
          data: child,
          childPaths: hasKnownChildren ? (state.entries[cp]?.childPaths ?? null) : [],
          loading: false,
        }
        // Deduplicate: same-named siblings (different rids) map to the same path — keep last, list once
        if (!seenPaths.has(cp)) {
          seenPaths.add(cp)
          childPaths.push(cp)
        }
      }
      newEntries[action.path] = { ...parent, childPaths, loading: false }
      return { ...state, entries: newEntries }
    }

    case 'EXPAND':
      return { ...state, expanded: new Set([...state.expanded, action.path]) }

    case 'COLLAPSE': {
      const next = new Set(state.expanded)
      const prefix = action.path + '/'
      for (const p of next) {
        if (p === action.path || p.startsWith(prefix)) next.delete(p)
      }
      return { ...state, expanded: next }
    }

    case 'SELECT':
      return { ...state, selected: action.path }

    case 'UPDATE_VALUE': {
      const e = state.entries[action.path]
      if (!e) return state
      return { ...state, entries: { ...state.entries, [action.path]: { ...e, data: { ...e.data, value: action.value, preview: action.value } } } }
    }

    case 'REMOVE': {
      const next = { ...state.entries }
      delete next[action.path]
      const parentPath = action.path.substring(0, action.path.lastIndexOf('/'))
      const parent = next[parentPath]
      if (parent) next[parentPath] = { ...parent, childPaths: parent.childPaths?.filter(p => p !== action.path) ?? null }
      const nextExp = new Set(state.expanded); nextExp.delete(action.path)
      return { ...state, entries: next, expanded: nextExp, selected: state.selected === action.path ? null : state.selected }
    }

    default:
      return state
  }
}

// ---- Visible row build ------------------------------------------------

interface VisibleRow {
  path: string
  level: number
  data: ModelNode
  isExpanded: boolean
  hasChildren: boolean
  loading: boolean
  dimmed: boolean
}

function nodeMatches(data: ModelNode, filter: string): boolean {
  return (data.name ?? '').toLowerCase().includes(filter.toLowerCase())
}

function hasMatchingDescendant(path: string, entries: Record<string, TreeEntry>, filter: string): boolean {
  const entry = entries[path]
  if (!entry?.childPaths) return false
  for (const cp of entry.childPaths) {
    const child = entries[cp]
    if (!child) continue
    if (nodeMatches(child.data, filter)) return true
    if (hasMatchingDescendant(cp, entries, filter)) return true
  }
  return false
}

// Returns true when a node has children the user can expand.
// When the new backend explicitly sends visibleChildrenCount, trust it unconditionally —
// childPaths includes command children too, so its length must not override an explicit "0".
// For legacy nodes (visibleChildrenCount absent) fall back to childrenCount or loaded paths.
function hasVisibleChildren(data: ModelNode, entry: TreeEntry): boolean {
  if (data.visibleChildrenCount != null) {
    return strNum(data.visibleChildrenCount, 0) > 0
  }
  return strNum(data.childrenCount, 0) > 0 || (entry.childPaths !== null && entry.childPaths.length > 0)
}

function sortedChildren(childPaths: string[], entries: Record<string, TreeEntry>, parentData?: ModelNode): string[] {
  return [...childPaths].sort((a, b) => {
    const na = entries[a]?.data
    const nb = entries[b]?.data
    if (parentData && isLocalDirectory(parentData)) {
      const aDir = na ? isLocalDirectory(na) : false
      const bDir = nb ? isLocalDirectory(nb) : false
      if (aDir !== bDir) return aDir ? -1 : 1
    }
    return (na?.name ?? a).localeCompare(nb?.name ?? b)
  })
}

