const REMOTE_MODEL_TYPE = 'ch.minova.appmodel.remote.RemoteModel'
const REMOTE_NODE_TYPE  = 'ch.minova.foundation.model.node.session.RemoteNode'
const SIMPLE_MODE_HIDDEN = new Set(['Services', 'Deployment', 'Instance'])

function isRemoteNode(data: ModelNode | null | undefined): boolean {
  if (!data) return false
  return data.remoteType === REMOTE_MODEL_TYPE || data.type === REMOTE_MODEL_TYPE || data.type === REMOTE_NODE_TYPE
}

function buildVisibleRows(
  entries: Record<string, TreeEntry>,
  expanded: Set<string>,
  rootPath: string,
  filter: string,
  showHidden: boolean,
  simpleMode: boolean,
): VisibleRow[] {
  const rows: VisibleRow[] = []
  const visited = new Set<string>()

  function visit(path: string, level: number, parentData?: ModelNode) {
    if (visited.has(path)) return
    visited.add(path)
    const entry = entries[path]
    if (!entry) return
    const { data } = entry

    if (!showHidden && data.visible === 'false') return
    if (nodeAttr(data, 'AssistOnly') === 'true') return
    if (simpleMode && isRemoteNode(parentData) && SIMPLE_MODE_HIDDEN.has(data.name ?? '')) return

    if (simpleMode && isRemoteNode(parentData) && data.name === 'Remotes') {
      // Transparent in simple mode: hoist children to the same level; hide if empty/loading
      if (entry.childPaths?.length) {
        for (const cp of entry.childPaths) visit(cp, level, parentData)
      }
      return
    }

    if (filter) {
      const matches = nodeMatches(data, filter)
      const childMatch = hasMatchingDescendant(path, entries, filter)
      if (!matches && !childMatch) return
      rows.push({ path, level, data, isExpanded: expanded.has(path), hasChildren: hasVisibleChildren(data, entry), loading: entry.loading, dimmed: !matches })
    } else {
      rows.push({ path, level, data, isExpanded: expanded.has(path), hasChildren: hasVisibleChildren(data, entry), loading: entry.loading, dimmed: false })
    }

    if (expanded.has(path) && entry.childPaths) {
      for (const cp of sortedChildren(entry.childPaths, entries, data)) visit(cp, level + 1, data)
    }
  }

  const rootEntry = entries[rootPath]
  if (rootEntry?.childPaths) {
    for (const cp of sortedChildren(rootEntry.childPaths, entries, rootEntry.data)) visit(cp, 0, rootEntry.data)
  }
  return rows
}

