// Exact icon names sent by the backend (e.g. from doProposeIcon on the Java side)
const BUILTIN_CMD_ICONS: Record<string, string> = {
  add:      '➕',
  clear:    '✕',
  remove:   '✕',
  delete:   '🗑',
  copy:     '⎘',
  upload:   '↑',
  download: '↓',
  refresh:  '↻',
  reload:   '↻',
  restart:  '↺',
  reboot:   '↺',
  off:      '○',
  on:       '●',
  play:     '▶',
  start:    '▶',
  execute:  '▶',
  call:     '→',
  save:     '💾',
  stop:     '⏹',
  shutdown: '⏹',
  pause:    '⏸',
  view:     '👁',
  modify:   '✎',
  db:       '⊞',
  install:  '↓',
  export:   '↗',
  import:   '↙',
  reset:    '↺',
}

// Derive an icon emoji from a command name using keyword substring matching —
// mirrors the Java-side doProposeIcon heuristic.
function proposeIconFromName(name: string): string | null {
  const s = name.toLowerCase()
  if (/create|add\b|\bnew\b/.test(s))      return '➕'
  if (/clear|delete|remove/.test(s))       return '✕'
  if (/copy|duplicate/.test(s))            return '⎘'
  if (/upload|push|commit/.test(s))        return '↑'
  if (/update|refresh|reload/.test(s))     return '↻'
  if (/restart|reboot/.test(s))            return '↺'
  if (/download|load|pull/.test(s))        return '↓'
  if (/shutdown/.test(s))                  return '⏹'
  if (/deactivate|disable/.test(s))        return '○'
  if (/activate|enable/.test(s))           return '●'
  if (/start/.test(s))                     return '▶'
  if (/save/.test(s))                      return '💾'
  if (/stop/.test(s))                      return '⏹'
  if (/open|view/.test(s))                 return '👁'
  if (/rename|modify|edit/.test(s))        return '✎'
  if (/database|\bdb\b|sql/.test(s))       return '⊞'
  if (/install/.test(s))                   return '↓'
  if (/export/.test(s))                    return '↗'
  if (/import/.test(s))                    return '↙'
  if (/reset/.test(s))                     return '↺'
  if (/run|execute|call/.test(s))          return '▶'
  if (/build|compile/.test(s))             return '⚙'
  if (/test|check/.test(s))               return '✓'
  if (/send|submit/.test(s))               return '→'
  if (/search|find/.test(s))               return '⌕'
  if (/cancel|abort/.test(s))              return '✕'
  if (/connect/.test(s))                   return '⟷'
  return null
}

/** Detects the chunked-upload command by name + binary-param signature. */
function isUploadCommand(cd: ModelNode): boolean {
  if (cd.name?.toLowerCase() !== 'upload' || !cd.args) return false
  const parsed = parseArgs(cd.args)
  return parsed.some(a => a.type === 'binary') && parsed.some(a => a.type === 'boolean')
}

interface PendingCommand { path: string; name: string; args: CommandArg[]; returnType?: string }
interface PendingUpload  { path: string; args: CommandArg[] }

interface Props {
  credentials: HubCredentials
  settings: HubSettings
  onSelectNode: (path: string, node: ModelNode) => void
}

export interface HubTreeHandle {
  navigate: (path: string) => void
}

export const HubTree = forwardRef<HubTreeHandle, Props>(function HubTree({ credentials, settings, onSelectNode }, ref) {
  const [state, dispatch] = useReducer(treeReducer, {
    entries: {}, expanded: new Set<string>(), selected: null, rootLoaded: false,
  })
  const [filter, setFilter] = useState('')
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; items: MenuItem[] } | null>(null)
  const [pendingCmd, setPendingCmd] = useState<PendingCommand | null>(null)
  const [pendingUpload, setPendingUpload] = useState<PendingUpload | null>(null)
  const [blinking, setBlinking] = useState<Set<string>>(new Set())
  const [favPaths, setFavPaths] = useState<Set<string>>(() => new Set(favoritesService.list(credentials.host).map(f => f.path)))
  const [treeDownloadProgress, setTreeDownloadProgress] = useState<{ loaded: number; total: number; name: string } | null>(null)
  const treeDownloadAbortRef = useRef<AbortController | null>(null)
  const blinkTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const filterRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    setFavPaths(new Set(favoritesService.list(credentials.host).map(f => f.path)))
    return favoritesService.onChange(() => {
      setFavPaths(new Set(favoritesService.list(credentials.host).map(f => f.path)))
    })
  }, [credentials.host])

  function triggerBlink(paths: string[]) {
    if (blinkTimer.current) clearTimeout(blinkTimer.current)
    setBlinking(new Set(paths))
    blinkTimer.current = setTimeout(() => setBlinking(new Set()), 650)
  }

  const rootPath = settings.rootPath

  // ---- API helpers ---------------------------------------------------

  const loadNode = useCallback(async (path: string): Promise<ModelNode | null> => {
    dispatch({ type: 'SET_LOADING', path, loading: true })
    try {
      const node = await getNode(credentials, path, 1)
      node.fullPath = path
      const childPaths = strNum(node.childrenCount, 0) > 0 && node.children
        ? node.children.map(c => `${path}/${c.name}`)
        : (strNum(node.childrenCount, 0) > 0 ? null : [])
      dispatch({ type: 'SET_ENTRY', path, data: node, childPaths })
      if (node.children?.length) {
        dispatch({ type: 'SET_CHILDREN', path, children: node.children })
      }
      return node
    } catch (err) {
      dispatch({ type: 'SET_LOADING', path, loading: false })
      logStore.add({ severity: 'error', text: `Load failed: ${err instanceof Error ? err.message : String(err)}` })
      return null
    }
  }, [credentials])

  // Returns the freshly loaded children so callers can use them without stale-state issues
  const loadChildren = useCallback(async (path: string): Promise<ModelNode[]> => {
    dispatch({ type: 'SET_LOADING', path, loading: true })
    try {
      const node = await getNode(credentials, path, 1)
      const children = node.children ?? []
      dispatch({ type: 'SET_CHILDREN', path, children })
      return children
    } catch (err) {
      dispatch({ type: 'SET_LOADING', path, loading: false })
      logStore.add({ severity: 'error', text: `Refresh failed: ${err instanceof Error ? err.message : String(err)}` })
      return []
    }
  }, [credentials])

  // ---- Initial load + URL path navigation ----------------------------

  useEffect(() => {
    dispatch({ type: 'RESET' })
    // Capture URL path synchronously — the URL-sync effect will clear ?path= on first render
    // before the async loadNode resolves, so we must read it now.
    const urlPath = new URLSearchParams(window.location.search).get('path')

    async function init() {
      await loadNode(rootPath)
      if (urlPath && urlPath.startsWith(rootPath)) {
        await navigateToPath(urlPath)
      }
    }
    init()
  }, [rootPath, credentials.host, credentials.username]) // eslint-disable-line react-hooks/exhaustive-deps

  // Navigate to a path by loading+expanding each ancestor segment below rootPath
  async function navigateToPath(targetPath: string) {
    const segments = targetPath.split('/')
    // Start at rootPath depth — segments above rootPath are not loadable/relevant
    const rootDepth = rootPath.split('/').length
    for (let i = rootDepth; i < segments.length; i++) {
      const path = segments.slice(0, i).join('/')
      try {
        const children = await loadChildren(path)
        dispatch({ type: 'EXPAND', path })
        if (!children.some(c => c.name === segments[i])) break
      } catch { break }
    }
    dispatch({ type: 'SELECT', path: targetPath })
    const node = await loadNode(targetPath)
    if (node) onSelectNode(targetPath, node)
    await loadChildren(targetPath)
    dispatch({ type: 'EXPAND', path: targetPath })
  }

  // ---- URL sync -------------------------------------------------------

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    if (state.selected) params.set('path', state.selected)
    else params.delete('path')
    window.history.replaceState(null, '', `${window.location.pathname}?${params.toString()}`)
  }, [state.selected])

  // ---- Auto-refresh (only when enabled; default is 0 = off) ----------

  useEffect(() => {
    if (settings.autoRefreshInterval <= 0) return
    const id = setInterval(() => {
      // Capture current expanded set at call time to avoid stale closure
      const expanded = [...state.expanded]
      for (const path of expanded) loadChildren(path)
    }, settings.autoRefreshInterval * 1000)
    return () => clearInterval(id)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings.autoRefreshInterval]) // intentionally shallow — reads live via loadChildren closure

  // ---- Keyboard ------------------------------------------------------

  useEffect(() => {
    async function onKey(e: KeyboardEvent) {
      if (e.key === 'F5') {
        e.preventDefault()
        const path = state.selected ?? rootPath
        const node = await loadNode(path)
        if (node?.children?.length) {
          triggerBlink(node.children.map(c => `${path}/${c.name}`))
        }
        if (settings.mode === 'simple' && isRemoteNode(node)) {
          const remotesPath = `${path}/Remotes`
          dispatch({ type: 'EXPAND', path: remotesPath })
          loadChildren(remotesPath)
        }
      }
      if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
        e.preventDefault()
        filterRef.current?.focus()
      }
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [state.selected, rootPath, loadChildren, loadNode, settings.mode])

  // ---- Expand/collapse (always reloads on expand) --------------------

  async function handleToggle(path: string, isExpanded: boolean) {
    if (isExpanded) {
      dispatch({ type: 'COLLAPSE', path })
      return
    }
    dispatch({ type: 'EXPAND', path })
    const children = await loadChildren(path)
    if (settings.mode === 'simple' && isRemoteNode(state.entries[path]?.data)) {
      const remotesChild = children.find(c => c.name === 'Remotes')
      if (remotesChild) {
        const remotesPath = `${path}/Remotes`
        dispatch({ type: 'EXPAND', path: remotesPath })
        loadChildren(remotesPath)
      }
    }
  }

  // ---- Select --------------------------------------------------------

  function handleSelect(path: string, data: ModelNode) {
    dispatch({ type: 'SELECT', path })
    onSelectNode(path, data)
  }

  // ---- Inline value change -------------------------------------------

  async function handleValueChange(path: string, value: string) {
    try {
      await setValue(credentials, path, value)
      dispatch({ type: 'UPDATE_VALUE', path, value })
      logStore.add({ severity: 'info', text: `${path}: value updated` })
    } catch (err) {
      logStore.add({ severity: 'error', text: err instanceof Error ? err.message : 'Set failed' })
    }
  }

  // ---- Start/stop ----------------------------------------------------

  async function handleStartStop(path: string, start: boolean) {
    try {
      await setValue(credentials, path, String(start), 'started')
      dispatch({ type: 'UPDATE_VALUE', path, value: String(start) })
      const parentPath = path.substring(0, path.lastIndexOf('/'))
      if (parentPath) loadChildren(parentPath)
    } catch (err) {
      logStore.add({ severity: 'error', text: err instanceof Error ? err.message : 'Start/stop failed' })
    }
  }

  // ---- Context menu --------------------------------------------------

  async function handleContextMenu(e: React.MouseEvent, path: string) {
    e.preventDefault()
    e.stopPropagation()

    // Load children fresh so commands are available — bypass stale state
    const commandChildren = await loadChildren(path)

    // Pre-fetch icon URLs for command nodes in parallel
    const cmdNodes = commandChildren.filter(
      cd => isCommandNode(cd) && cd.active !== 'false' && cd.active !== false && shouldFetchIcon(cd.icon)
    )
    const iconUrls = new Map<string, string | null>()
    await Promise.all(cmdNodes.map(async cd => {
      const type = cd.type ?? 'command'
      const key = `${credentials.host}:${type}:${cd.icon}`
      const routingPath = cd.fullPath?.startsWith('/Nodes/') ? cd.fullPath : undefined
      let promise = iconUrlCache.get(key)
      if (!promise) {
        promise = fetchNodeIcon(credentials, type, cd.icon!, routingPath)
        iconUrlCache.set(key, promise)
      }
      iconUrls.set(cd.icon!, await promise)
    }))

    buildContextMenu(e.clientX, e.clientY, path, commandChildren, iconUrls)
  }

  function buildContextMenu(x: number, y: number, path: string, commandChildren: ModelNode[], iconUrls: Map<string, string | null> = new Map()) {
    const data = state.entries[path]?.data
    const items: MenuItem[] = []

    if (data) {
      if (isLocalFile(data) || isBinary(data)) {
        items.push({ label: 'Download', icon: '↓', cmd: `__download__:${path}` })
      }
      if (strTrue(data.deletable) || strTrue(data.deleteable)) {
        items.push({ label: 'Delete', icon: '🗑', cmd: `__delete__:${path}`, danger: true })
      }
    }

    const commands: MenuItem[] = []
    for (const cd of commandChildren) {
      // Show command if not explicitly disabled
      if (isCommandNode(cd) && cd.active !== 'false' && cd.active !== false && nodeAttr(cd, 'AssistOnly') !== 'true') {
        const childPath = cd.fullPath ?? `${path}/${cd.name}`
        const iconUrl = cd.icon ? (iconUrls.get(cd.icon) ?? null) : null

        if (isUploadCommand(cd)) {
          // Upload commands get a dedicated dialog — encode args for later parsing
          commands.push({
            label: cd.name ?? 'Upload',
            ...(iconUrl ? { iconUrl } : { icon: '↑' }),
            cmd: `__upload__:${childPath}:${encodeURIComponent(cd.args!)}`,
          })
          continue
        }

        const hasArgs = Boolean(cd.args)
        const returnType = cd.returnType ?? ''
        // Encode args + returnType: __cmd__:{path}:{args}:{returnType}
        const needsTrailer = hasArgs || returnType
        const cmd = needsTrailer
          ? `__cmd__:${childPath}:${hasArgs ? encodeURIComponent(cd.args!) : ''}:${encodeURIComponent(returnType)}`
          : `__cmd__:${childPath}`
        const fallbackIcon = (cd.icon && BUILTIN_CMD_ICONS[cd.icon.toLowerCase()])
          ?? (cd.name && proposeIconFromName(cd.name))
          ?? cd.name
          ?? (hasArgs ? '💬' : '▶')
        commands.push({
          label: (cd.name ?? '') + (hasArgs ? ' …' : ''),
          ...(iconUrl ? { iconUrl } : { icon: fallbackIcon }),
          cmd,
        })
      }
    }
    if (commands.length > 0) {
      if (items.length > 0) items.push({ label: '---', cmd: '' })
      items.push(...commands)
    }

    items.push({ label: '---', cmd: '' })
    items.push({ label: 'Refresh', icon: '↻', cmd: `__refresh__:${path}` })
    items.push({ label: 'Copy path', icon: '📋', cmd: `__copy__:${path}` })

    setContextMenu({ x, y, items })
  }

  // ---- Context menu actions ------------------------------------------

  async function handleMenuSelect(cmd: string) {
    if (cmd.startsWith('__download__:')) {
      const path = cmd.slice(13)
      const data = state.entries[path]?.data
      const filename = data?.name ?? path.split('/').pop() ?? 'file'
      try {
        if (data && supportsChunkedRead(data)) {
          const totalBytes = parseInt(nodeAttr(data, 'contentLength')!)
          const ctrl = new AbortController()
          treeDownloadAbortRef.current = ctrl
          setTreeDownloadProgress({ loaded: 0, total: totalBytes, name: filename })
          try {
            await downloadFileChunked(credentials, path, filename, totalBytes,
              (loaded, total) => setTreeDownloadProgress({ loaded, total, name: filename }),
              ctrl.signal)
          } finally {
            setTreeDownloadProgress(null)
            treeDownloadAbortRef.current = null
          }
        } else {
          await downloadFile(credentials, path, filename)
        }
      } catch (err) {
        if ((err as DOMException).name !== 'AbortError')
          logStore.add({ severity: 'error', text: `Download failed: ${err instanceof Error ? err.message : String(err)}` })
      }
      return
    }
    if (cmd.startsWith('__delete__:')) {
      const path = cmd.slice(11)
      if (!confirm(`Delete ${path}?`)) return
      try {
        await deleteNode(credentials, path)
        dispatch({ type: 'REMOVE', path })
        logStore.add({ severity: 'info', text: `${path} deleted` })
      } catch (err) {
        logStore.add({ severity: 'error', text: err instanceof Error ? err.message : 'Delete failed' })
      }
      return
    }
    if (cmd.startsWith('__refresh__:')) {
      loadChildren(cmd.slice(12))
      return
    }
    if (cmd.startsWith('__copy__:')) {
      const path = cmd.slice(9)
      navigator.clipboard?.writeText(path).catch(() => {})
      logStore.add({ severity: 'info', text: `Copied: ${path}` })
      return
    }
    if (cmd.startsWith('__upload__:')) {
      const rest = cmd.slice(11)
      const colonIdx = rest.indexOf(':')
      const uploadPath = colonIdx >= 0 ? rest.slice(0, colonIdx) : rest
      const argsStr = colonIdx >= 0 ? decodeURIComponent(rest.slice(colonIdx + 1)) : ''
      setPendingUpload({ path: uploadPath, args: parseArgs(argsStr) })
      return
    }
    if (cmd.startsWith('__cmd__:')) {
      // Format: __cmd__:{path}:{encodedArgs}:{encodedReturnType}  (trailing segments optional)
      const rest = cmd.slice(8)
      const [cmdPath = '', encodedArgs = '', encodedReturnType = ''] = rest.split(':')
      const argsStr = encodedArgs ? decodeURIComponent(encodedArgs) : ''
      const returnType = encodedReturnType ? decodeURIComponent(encodedReturnType) : ''
      const name = cmdPath.split('/').pop() ?? ''
      if (argsStr) {
        setPendingCmd({ path: cmdPath, name, args: parseArgs(argsStr), returnType })
      } else {
        await executeCommand(cmdPath, name, {}, returnType)
      }
    }
  }

  async function executeCommand(cmdPath: string, name: string, namedArgs: Record<string, string>, _returnType?: string) {
    try {
      const result = await callCommand(credentials, cmdPath, namedArgs)
      if (result instanceof ArrayBuffer) {
        const slug = name.toLowerCase().replace(/\s+/g, '_')
        const blob = new Blob([result], { type: 'application/octet-stream' })
        const objectUrl = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = objectUrl
        a.download = slug
        a.click()
        URL.revokeObjectURL(objectUrl)
        logStore.add({ severity: 'info', text: `${name}: downloaded ${result.byteLength} bytes` })
      } else if (typeof result === 'string') {
        const text = result.trim()
        logStore.add({ severity: 'info', text: text ? `${name}: ${text}` : `${name}: executed` })
      } else {
        const logs = extractLogs(result)
        if (logs.length > 0) {
          logStore.addMany(logs)
        } else {
          const text = result != null ? JSON.stringify(result) : null
          logStore.add({ severity: 'info', text: text ? `${name}: ${text}` : `${name}: executed` })
        }
      }
      const parentPath = cmdPath.substring(0, cmdPath.lastIndexOf('/'))
      if (parentPath) loadChildren(parentPath)
    } catch (err) {
      logStore.add({
        severity: 'error',
        text: `${name}: ${err instanceof HubApiError ? err.message : String(err)}`,
      })
    }
  }

  // ---- Imperative handle --------------------------------------------

  useImperativeHandle(ref, () => ({
    navigate: (path: string) => navigateToPath(path),
  }))  

  // ---- Render --------------------------------------------------------

  const visibleRows = buildVisibleRows(state.entries, state.expanded, rootPath, filter, settings.showHidden, settings.mode === 'simple')

  if (!state.rootLoaded) {
    return <div className="hub-tree hub-tree--loading"><div className="tree-spinner">Loading…</div></div>
  }

  return (
    <div className="hub-tree">
      <div className="tree-filter-bar">
        <input
          ref={filterRef}
          type="text"
          className="tree-filter"
          placeholder="Filter nodes… (Ctrl+F)"
          value={filter}
          onChange={e => setFilter(e.target.value)}
        />
        {filter && <button className="tree-filter-clear" onClick={() => setFilter('')}>✕</button>}
        <button
          className="tree-root-reload"
          title="Reload top-level list"
          onClick={async () => {
            const node = await loadNode(rootPath)
            if (node?.children?.length) triggerBlink(node.children.map(c => `${rootPath}/${c.name}`))
          }}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/>
          </svg>
        </button>
      </div>

      {treeDownloadProgress !== null && (
        <div className="tree-download-progress">
          <span className="tree-dl-name" title={treeDownloadProgress.name}>{treeDownloadProgress.name}</span>
          <div className="tree-dl-bar-wrap">
            <div className="tree-dl-bar" style={{ width: `${Math.round(treeDownloadProgress.loaded / treeDownloadProgress.total * 100)}%` }} />
          </div>
          <span className="tree-dl-pct">{Math.round(treeDownloadProgress.loaded / treeDownloadProgress.total * 100)}%</span>
          <button className="tree-dl-cancel" onClick={() => treeDownloadAbortRef.current?.abort()} title="Cancel">✕</button>
        </div>
      )}

      <div className="tree-body">
        {visibleRows.length === 0 ? (
          <div className="tree-empty">{filter ? 'No matching nodes' : 'No nodes'}</div>
        ) : (
          visibleRows.map(row => (
            <TreeRow
              key={row.path}
              row={row}
              credentials={credentials}
              isSelected={state.selected === row.path}
              isBlinking={blinking.has(row.path)}
              isFav={favPaths.has(row.path)}
              onToggle={() => handleToggle(row.path, row.isExpanded)}
              onClick={() => handleSelect(row.path, row.data)}
              onContextMenu={e => handleContextMenu(e, row.path)}
              onValueChange={v => handleValueChange(row.path, v)}
              onStartStop={start => handleStartStop(row.path, start)}
              onDownload={openInTab => {
                const filename = row.data.name ?? row.path.split('/').pop() ?? 'file'
                if (openInTab) { window.open(getValueUrl(credentials, row.path, viewStyle(filename)), '_blank'); return }
                if (supportsChunkedRead(row.data)) {
                  const totalBytes = parseInt(nodeAttr(row.data, 'contentLength')!)
                  const ctrl = new AbortController()
                  treeDownloadAbortRef.current = ctrl
                  setTreeDownloadProgress({ loaded: 0, total: totalBytes, name: filename })
                  downloadFileChunked(credentials, row.path, filename, totalBytes,
                    (loaded, total) => setTreeDownloadProgress({ loaded, total, name: filename }),
                    ctrl.signal)
                    .catch(err => {
                      if ((err as DOMException).name !== 'AbortError')
                        logStore.add({ severity: 'error', text: `Download failed: ${err instanceof Error ? err.message : String(err)}` })
                    })
                    .finally(() => { setTreeDownloadProgress(null); treeDownloadAbortRef.current = null })
                } else {
                  downloadFile(credentials, row.path, filename)
                    .catch(err => logStore.add({ severity: 'error', text: `Download failed: ${err instanceof Error ? err.message : String(err)}` }))
                }
              }}
              onToggleFav={() => {
                const data = state.entries[row.path]?.data
                if (!data) return
                if (favPaths.has(row.path)) {
                  favoritesService.remove(credentials.host, row.path)
                } else {
                  const kind = isValueNode(data) ? 'value' : isLocalFile(data) ? 'file' : 'directory'
                  favoritesService.add(credentials.host, {
                    path: row.path,
                    name: data.name ?? row.path.split('/').pop() ?? row.path,
                    kind,
                    group: row.path.split('/')[0] ?? '',
                  })
                }
              }}
            />
          ))
        )}
      </div>

      {contextMenu && (
        <ContextMenu
          x={contextMenu.x}
          y={contextMenu.y}
          items={contextMenu.items}
          onSelect={handleMenuSelect}
          onClose={() => setContextMenu(null)}
        />
      )}

      {pendingCmd && (
        <CommandDialog
          commandPath={pendingCmd.path}
          commandName={pendingCmd.name}
          args={pendingCmd.args}
          onExecute={namedArgs => { const c = pendingCmd; setPendingCmd(null); executeCommand(c.path, c.name, namedArgs, c.returnType) }}
          onClose={() => setPendingCmd(null)}
        />
      )}

      {pendingUpload && (
        <UploadDialog
          commandPath={pendingUpload.path}
          args={pendingUpload.args}
          credentials={credentials}
          onComplete={() => {
            const parentPath = pendingUpload.path.substring(0, pendingUpload.path.lastIndexOf('/'))
            if (parentPath) loadChildren(parentPath)
          }}
          onClose={() => setPendingUpload(null)}
        />
      )}
    </div>
  )
})

// ---- Single row -------------------------------------------------------

// Module-level cache: keeps object URLs alive for the whole session.
// Caches the Promise, not the resolved value — concurrent mounts share one in-flight request.
const iconUrlCache = new Map<string, Promise<string | null>>()

// Returns true when `name` should trigger a backend /icon fetch:
// - empty string  → type-default icon (backend derives name from simple class name)
// - has extension → explicit icon file (≤255 chars to reject embedded blob data)
// Extension-less non-empty names (e.g. "play", "stop") are built-in Web UI icons — not fetched.
const shouldFetchIcon = (name: string | undefined): name is string =>
  name !== undefined && (name === '' || (name.length <= 255 && /\.\w{2,5}$/.test(name)))

function useNodeIconUrl(
  creds: HubCredentials,
  type: string | undefined,
  iconName: string | undefined,
  nodePath?: string,
): string | null {
  const [url, setUrl] = useState<string | null>(null)
  useEffect(() => {
    if (!type || !shouldFetchIcon(iconName)) return
    // Cache key is type+icon — the icon is fully determined by the node type, not by its instance path.
    // nodePath is forwarded to the backend only for remote nodes (routing), never as part of the key.
    const key = `${creds.host}:${type}:${iconName}`
    const routingPath = nodePath?.startsWith('/Nodes/') ? nodePath : undefined
    let promise = iconUrlCache.get(key)
    if (!promise) {
      promise = fetchNodeIcon(creds, type, iconName, routingPath)
      iconUrlCache.set(key, promise)
    }
    let cancelled = false
    promise.then(u => { if (!cancelled) setUrl(u) })
    return () => { cancelled = true }
  }, [creds, type, iconName, nodePath])
  return url
}

interface RowProps {
  row: VisibleRow
  credentials: HubCredentials
  isSelected: boolean
  isBlinking: boolean
  isFav: boolean
  onToggle: () => void
  onClick: () => void
  onContextMenu: (e: React.MouseEvent) => void
  onValueChange: (v: string) => void
  onStartStop: (start: boolean) => void
  onDownload: (openInTab: boolean) => void
  onToggleFav: () => void
}

function TreeRow({ row, credentials, isSelected, isBlinking, isFav, onToggle, onClick, onContextMenu, onValueChange, onStartStop, onDownload, onToggleFav }: RowProps) {
  const { path, level, data, isExpanded, hasChildren, loading, dimmed } = row
  const started = strTrue(data.started)
  const isStartable = strTrue(data.startable)
  const rawName = data.name ?? path.split('/').pop() ?? path
  const name = isRemoteNode(data) ? stripRemoteModelName(rawName) : rawName
  const isTopLevelModel = level === 0 && isRemoteNode(data) && !isFrontendClient(rawName)
  const env = isTopLevelModel ? detectEnvironment(rawName) : null

  // Icon: new-style (fetch from /icon?path=) or legacy inline base64
  const nodeIconUrl = useNodeIconUrl(credentials, data.type, data.icon, data.fullPath ?? undefined)

  return (
    <div
      className={`tree-row${isSelected ? ' selected' : ''}${dimmed ? ' dimmed' : ''}${isBlinking ? ' blink' : ''}`}
      style={{ paddingLeft: `${level * 18 + 4}px` }}
      onClick={onClick}
      onContextMenu={onContextMenu}
    >
      <span
        className={`tree-toggle${!hasChildren ? ' leaf' : ''}`}
        onClick={e => { e.stopPropagation(); if (hasChildren) onToggle() }}
      >
        {loading ? '⟳' : hasChildren ? (isExpanded ? '▼' : '▶') : null}
      </span>

      {isRemoteNode(data)
        ? <ProductIcon name={data.name ?? ''} iconData={data.iconData} size={16} className="tree-icon product-icon" />
        : nodeIconUrl
          ? <img className="tree-icon" src={nodeIconUrl} alt="" />
          : data.icon === undefined && data.iconData
            ? <img className="tree-icon" src={`data:image/png;base64,${data.iconData}`} alt="" />
            : isCommandNode(data)
              ? <span className="tree-icon tree-icon--text"><IcConsole /></span>
              : null
      }

      <span className={`tree-name${isStartable ? (started ? ' started' : ' stopped') : ''}`} title={name}>
        {name}
      </span>
      {env && <span className={`env-badge env-badge--${env}`}>{env.toUpperCase()}</span>}

      <div className="tree-value-cell" onClick={e => e.stopPropagation()}>
        <ValueEditor node={data} onChange={onValueChange} onDownload={onDownload} />
      </div>

      <div className="tree-actions" onClick={e => e.stopPropagation()}>
        {level > 0 && (
          <button
            className={`tree-fav-btn${isFav ? ' tree-fav-btn--on' : ''}`}
            title={isFav ? 'Remove from favorites' : 'Add to favorites'}
            onClick={onToggleFav}
          >★</button>
        )}
        {isStartable && (
          <button
            className={`tree-action-btn${started ? ' btn-stop' : ' btn-start'}`}
            title={started ? 'Stop' : 'Start'}
            onClick={() => onStartStop(!started)}
          >
            {started ? '⏸' : '▶'}
          </button>
        )}
      </div>
    </div>
  )
}
