/* eslint-disable react-refresh/only-export-components */
type ProductCode = 'AFIS' | 'TTA' | 'SIS' | 'DISPO'

// Matches ch.minova.{mfe|afis|tta|sis|dispo}.application.product-
const FE_PREFIX_RE = /^ch\.minova\.(mfe|afis|tta|sis|dispo)\.application\.product-/i

export function isFrontendClient(name: string): boolean {
  return FE_PREFIX_RE.test(name)
}

export function stripRemoteModelName(name: string): string {
  return name.replace(FE_PREFIX_RE, '')
}

export function detectEnvironment(name: string): 'dev' | 'prod' {
  const segments = name.toUpperCase().split(/[-_\s]+/)
  return segments.includes('DEV') ? 'dev' : 'prod'
}

export function detectProductCode(name: string): ProductCode | null {
  const segments = stripRemoteModelName(name).toUpperCase().split(/[-_\s]+/)
  for (const seg of segments) {
    if (seg === 'AFIS')  return 'AFIS'
    if (seg === 'TTA')   return 'TTA'
    if (seg === 'SIS')   return 'SIS'
    if (seg === 'DISPO') return 'DISPO'
  }
  return null
}

interface Props {
  name: string
  iconData?: string
  size?: number
  className?: string
}

export function ProductIcon({ name, size = 16, className }: Props) {
  const svg = {
    width: size, height: size, viewBox: '0 0 24 24',
    fill: 'none', stroke: 'currentColor', strokeWidth: '1.8',
    strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const,
    className,
  }

  if (isFrontendClient(name)) return (
    // Frontend / browser client → user icon
    <svg {...svg}>
      <circle cx="12" cy="8" r="4"/>
      <path d="M4 20c0-4 3.58-7 8-7s8 3 8 7"/>
    </svg>
  )

  const code = detectProductCode(name)

  if (!code) {
    return (
      <svg {...svg}>
        <circle cx="12" cy="12" r="8"/>
        <circle cx="12" cy="12" r="2" fill="currentColor" stroke="none"/>
      </svg>
    )
  }

  switch (code) {
    case 'AFIS': return (
      // Top-down airplane silhouette
      <svg {...svg}>
        <path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5z"/>
      </svg>
    )
    case 'TTA': return (
      // Vertical fuel tank / cylinder
      <svg {...svg}>
        <ellipse cx="12" cy="6" rx="8" ry="3"/>
        <path d="M4 6v12c0 1.66 3.58 3 8 3s8-1.34 8-3V6"/>
        <path d="M20 12c0 1.66-3.58 3-8 3s-8-1.34-8-3"/>
      </svg>
    )
    case 'SIS': return (
      // Euro sign — invoicing / billing
      <svg {...svg}>
        <path d="M18 8a6 6 0 1 0 0 8"/>
        <line x1="5" y1="11" x2="15" y2="11"/>
        <line x1="5" y1="14" x2="15" y2="14"/>
      </svg>
    )
    case 'DISPO': return (
      // Delivery truck
      <svg {...svg}>
        <rect x="1" y="3" width="15" height="13"/>
        <polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/>
        <circle cx="5.5" cy="18.5" r="2.5"/>
        <circle cx="18.5" cy="18.5" r="2.5"/>
      </svg>
    )
  }
}
