import { useState, useEffect, useRef } from 'react'
import type { LogMessage } from '../types/hub'
import { logStore } from '../services/logStore'
import './Toaster.css'

interface Toast extends LogMessage {
  expiresAt: number
}

const TTL: Record<LogMessage['severity'], number> = {
  error:   6000,
  warning: 5000,
  info:    3500,
  debug:   2500,
}

export function Toaster() {
  const [toasts, setToasts] = useState<Toast[]>([])
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    return logStore.onNew(msg => {
      if (msg.severity === 'debug') return
      const toast: Toast = { ...msg, expiresAt: Date.now() + TTL[msg.severity] }
      setToasts(prev => [...prev.slice(-4), toast])
    })
  }, [])

  // Drive a single timer that removes the next-expiring toast
  useEffect(() => {
    if (toasts.length === 0) return
    const next = Math.min(...toasts.map(t => t.expiresAt))
    const delay = Math.max(next - Date.now(), 0)
    timerRef.current = setTimeout(() => {
      setToasts(prev => prev.filter(t => t.expiresAt > Date.now()))
    }, delay)
    return () => { if (timerRef.current) clearTimeout(timerRef.current) }
  }, [toasts])

  function dismiss(id: number) {
    setToasts(prev => prev.filter(t => t.id !== id))
  }

  if (toasts.length === 0) return null

  return (
    <div className="toaster">
      {toasts.map(t => (
        <div key={t.id} className={`toast toast--${t.severity}`} onClick={() => dismiss(t.id)}>
          <span className="toast-dot" />
          <span className="toast-text">{t.text}</span>
          <button className="toast-close" onClick={e => { e.stopPropagation(); dismiss(t.id) }}>✕</button>
        </div>
      ))}
    </div>
  )
}
