import type { HubSettings } from '../types/hub'
import { DEFAULT_SETTINGS } from '../types/hub'

const key = (host: string) => `hub-settings:${host}`

export function loadSettings(host: string): HubSettings {
  try {
    const raw = localStorage.getItem(key(host))
    if (!raw) return { ...DEFAULT_SETTINGS }
    return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) }
  } catch {
    return { ...DEFAULT_SETTINGS }
  }
}

export function saveSettings(host: string, settings: HubSettings): void {
  localStorage.setItem(key(host), JSON.stringify(settings))
}

export function hasSettings(host: string): boolean {
  return localStorage.getItem(key(host)) !== null
}
