import { useState, useEffect } from 'react'
import { logStore } from '../services/logStore'
import { LogPanel } from './LogPanel'
import './LogChip.css'

export function LogChip() {
  const [counts, setCounts] = useState(() => logStore.getCounts())
  const [open, setOpen] = useState(false)

  useEffect(() => logStore.onChange(() => setCounts({ ...logStore.getCounts() })), [])

  const total = counts.error + counts.warning + counts.info + counts.debug

  return (
    <>
      <button
        className={`log-chip${open ? ' log-chip--open' : ''}`}
        onClick={() => setOpen(o => !o)}
        title="Logs"
      >
        <span className="log-chip-label">Log</span>
        {counts.error   > 0 && <span className="log-chip-badge log-chip-badge--error">{counts.error}</span>}
        {counts.warning > 0 && <span className="log-chip-badge log-chip-badge--warning">{counts.warning}</span>}
        {counts.info    > 0 && <span className="log-chip-badge log-chip-badge--info">{counts.info}</span>}
        {total === 0 && <span className="log-chip-empty">–</span>}
      </button>
      {open && <LogPanel onClose={() => setOpen(false)} />}
    </>
  )
}
