// ---- Data types -------------------------------------------------------

interface MemoryInfo {
  used: number; total: number; max: number
  usedLabel: string; totalLabel: string; maxLabel: string
}

interface CwdInfo {
  hubPath: string; filePath: string; iconData?: string
}

interface ServiceInfo {
  path: string
  name: string
  iconData?: string
}

interface ServiceData {
  memory: MemoryInfo | null
  since: string | null
  cwd: CwdInfo | null
  hasTerminal: boolean
}

// ---- Helpers ----------------------------------------------------------

function parseMemoryBytes(v: string): number {
  const m = v.trim().match(/^(\d+(?:\.\d+)?)\s*(k|m|g)?b?$/i)
  if (!m) return 0
  const n = parseFloat(m[1])
  const unit = (m[2] ?? '').toLowerCase()
  if (unit === 'k') return n * 1024
  if (unit === 'm') return n * 1024 * 1024
  if (unit === 'g') return n * 1024 * 1024 * 1024
  return n
}

function childValue(children: ModelNode[] | undefined, name: string): string {
  return children?.find(c => c.name === name)?.value ?? ''
}

function extractMemory(node: ModelNode): MemoryInfo | null {
  if (!node.children?.length) return null
  const usedLabel  = childValue(node.children, 'Used')
  const totalLabel = childValue(node.children, 'Total')
  const maxLabel   = childValue(node.children, 'Max')
  if (!usedLabel) return null
  return {
    used:  parseMemoryBytes(usedLabel),
    total: parseMemoryBytes(totalLabel),
    max:   parseMemoryBytes(maxLabel),
    usedLabel, totalLabel, maxLabel,
  }
}

async function resolveCwdFromDrives(
  creds: HubCredentials,
  remotePath: string,
  drivesNode: ModelNode,
): Promise<CwdInfo | null> {
  const currentDrive = drivesNode.children?.find(c => c.icon === 'LocalDir.Current.png')
  if (!currentDrive) return null

  let hubPath     = `${remotePath}/Drives/${currentDrive.name}`
  let cwdFilePath = currentDrive.filePath ?? '/'
  let cwdIconData = currentDrive.iconData

  while (true) {
    let fetched: ModelNode
    try { fetched = await getNode(creds, hubPath, 1) }
    catch { break }
    cwdFilePath = fetched.filePath ?? cwdFilePath
    cwdIconData = fetched.iconData ?? cwdIconData
    const next = fetched.children?.find(c => c.icon === 'LocalDir.Current.png')
    if (!next) break
    hubPath = `${hubPath}/${next.name}`
  }

  return { hubPath, filePath: cwdFilePath, iconData: cwdIconData }
}

function formatDuration(sinceStr: string): string {
  if (!sinceStr) return '—'
  const d = new Date(sinceStr)
  if (isNaN(d.getTime())) return sinceStr
  const ms    = Date.now() - d.getTime()
  const mins  = Math.floor(ms / 60_000)
  const hours = Math.floor(mins / 60)
  const days  = Math.floor(hours / 24)
  if (days  > 0) return `${days}d ${hours % 24}h`
  if (hours > 0) return `${hours}h ${mins % 60}m`
  if (mins  > 0) return `${mins}m`
  return '<1m'
}

function memColor(pct: number): string {
  if (pct < 0.5)  return '#22c55e'
  if (pct < 0.75) return '#f59e0b'
  if (pct < 0.9)  return '#f97316'
  return '#ef4444'
}

// ---- Memory bar -------------------------------------------------------

function MemBar({ mem }: { mem: MemoryInfo }) {
  const maxRef   = mem.max > 0 ? mem.max : mem.total
  const pctTotal = maxRef > 0 ? Math.min(mem.total / maxRef, 1) : 0
  const pctUsed  = maxRef > 0 ? Math.min(mem.used  / maxRef, 1) : 0
  const color    = memColor(mem.total > 0 ? mem.used / mem.total : 0)
  return (
    <div className="mp-membar">
      <div className="mp-membar-track">
        <div className="mp-membar-alloc" style={{ width: `${(pctTotal * 100).toFixed(1)}%`, background: color }} />
        <div className="mp-membar-used"  style={{ width: `${(pctUsed  * 100).toFixed(1)}%`, background: color }} />
      </div>
      <div className="mp-membar-label">{mem.usedLabel} / {mem.totalLabel}</div>
    </div>
  )
}

