// ---- Restart button with inline confirmation -------------------------

interface RestartButtonProps {
  name: string
  onConfirm: () => void
  className?: string
}

function RestartButton({ name, onConfirm, className = '' }: RestartButtonProps) {
  const [pending, setPending] = useState(false)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  function handleClick() {
    if (!pending) {
      setPending(true)
      timerRef.current = setTimeout(() => setPending(false), 3000)
    } else {
      if (timerRef.current) clearTimeout(timerRef.current)
      setPending(false)
      onConfirm()
    }
  }

  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current) }, [])

  return (
    <button
      className={`mp-icon-btn mp-icon-btn--danger${pending ? ' mp-icon-btn--pending' : ''} ${className}`}
      onClick={handleClick}
      title={pending ? `Click again to restart ${name}` : `Restart ${name}`}
    >
      {pending ? <span className="mp-really">Really?</span> : <IcPower />}
    </button>
  )
}

// ---- Shared data hook ------------------------------------------------

const serviceDataCache = new Map<string, ServiceData>()
// eslint-disable-next-line react-refresh/only-export-components
export function clearServiceDataCache() { serviceDataCache.clear() }

interface ServiceRowProps {
  info: ServiceInfo
  credentials: HubCredentials
  onNavigate: (path: string) => void
  loadData?: boolean
}

function useServiceData(credentials: HubCredentials, path: string, enabled: boolean, withMemory = true): { data: ServiceData | null; loading: boolean } {
  const cacheKey = `${credentials.host}::${path}`
  const [data, setData]       = useState<ServiceData | null>(() => serviceDataCache.get(cacheKey) ?? null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (!enabled) return
    const cached = serviceDataCache.get(cacheKey)
    if (cached) {
      setData(cached)
      return  // never re-fetch silently; user reloads explicitly
    }
    let cancelled = false
    setLoading(true)
    setData(null)

    async function fetchData() {
      const selfNode     = await getNode(credentials, path, 1).catch(() => null)
      if (cancelled) return
      const selfChildren = selfNode?.children ?? []
      const hasTerminal  = selfChildren.some(c => c.name === 'terminal' && isCommandNode(c))

      const [instanceRes, drivesRes] = await Promise.allSettled([
        getNode(credentials, `${path}/Instance`, 1),
        getNode(credentials, `${path}/Drives`, 1),
      ])
      if (cancelled) return

      const instanceNode = instanceRes.status === 'fulfilled' ? instanceRes.value : null
      const sinceRaw     = instanceNode ? childValue(instanceNode.children, 'Running since') : null
      const since        = sinceRaw ? formatDuration(sinceRaw) : null
      const drivesNode   = drivesRes.status === 'fulfilled' ? drivesRes.value : null

      const [memRes, cwdRes] = await Promise.allSettled([
        withMemory ? getNode(credentials, `${path}/SystemInfo/Memory`, 1) : Promise.resolve(null),
        drivesNode ? resolveCwdFromDrives(credentials, path, drivesNode) : Promise.resolve(null),
      ])
      if (cancelled) return

      const memory = withMemory && memRes.status === 'fulfilled' && memRes.value ? extractMemory(memRes.value) : null
      const cwd    = cwdRes.status === 'fulfilled' ? cwdRes.value : null

      const result: ServiceData = { memory, since, cwd, hasTerminal }
      serviceDataCache.set(cacheKey, result)
      setData(result)
      setLoading(false)
    }

    fetchData()
    return () => { cancelled = true }
  }, [path, credentials, enabled, cacheKey, withMemory])

  return { data, loading }
}

// ---- Self panel (selected / parent node) -----------------------------

function SelfPanel({ info, credentials, onNavigate }: ServiceRowProps) {
  const { data, loading } = useServiceData(credentials, info.path, true, false)
  const env = !isFrontendClient(info.name) ? detectEnvironment(info.name) : null

  async function doRestart() {
    try {
      await callCommand(credentials, `${info.path}/terminal`, { commandLine: 'reboot', inBackground: 'false', '': '' })
      logStore.add({ severity: 'warning', text: `${info.name}: restart initiated` })
    } catch (err) {
      logStore.add({ severity: 'error', text: `Restart failed: ${err instanceof Error ? err.message : String(err)}` })
    }
  }

  return (
    <div className="mp-self-panel">
      <div className="mp-self-header">
        <ProductIcon name={info.name} iconData={info.iconData} size={18} className="mp-row-icon product-icon" />
        <span className="mp-self-name">{stripRemoteModelName(info.name)}</span>
        {env && <span className={`env-badge env-badge--${env}`}>{env.toUpperCase()}</span>}
        {!loading && data?.hasTerminal && (
          <RestartButton name={info.name} onConfirm={doRestart} />
        )}
      </div>
      <div className="mp-self-rows">
        <div className="mp-self-row">
          <span className="mp-self-label">Uptime</span>
          <div className="mp-self-value mp-self-value--uptime">
            {loading ? <div className="mp-skel mp-skel--short" /> : <span>{data?.since ?? '—'}</span>}
          </div>
        </div>
        <div className="mp-self-row">
          <span className="mp-self-label">Directory</span>
          <div className="mp-self-value mp-self-value--cwd">
            {loading
              ? <div className="mp-skel" />
              : data?.cwd
                ? <>
                    <button className="mp-icon-btn" onClick={() => onNavigate(data.cwd!.hubPath)} title={data.cwd.filePath}>
                      {data.cwd.iconData
                        ? <img src={`data:image/png;base64,${data.cwd.iconData}`} alt="" width={14} height={14} />
                        : <span className="mp-fs-fallback">📁</span>
                      }
                    </button>
                    <span className="mp-self-path">{data.cwd.filePath}</span>
                  </>
                : <span className="mp-na">—</span>
            }
          </div>
        </div>
      </div>
    </div>
  )
}

