interface Props {
  path: string
  node: ModelNode
  credentials: HubCredentials
  onNavigate: (path: string) => void
  autoLoadServiceInfo?: boolean
  simpleMode?: boolean
  showJson?: boolean
}

export function ModelPreview({ path, node, credentials, onNavigate, autoLoadServiceInfo = false, simpleMode = false, showJson = false }: Props) {
  const [selfInfo, setSelfInfo]           = useState<ServiceInfo | null>(null)
  const [remoteInfos, setRemoteInfos]     = useState<ServiceInfo[]>([])
  const [rosterLoading, setRosterLoading] = useState(true)
  const [rosterVersion, setRosterVersion] = useState(0)
  const [serviceInfoOpen, setServiceInfoOpen] = useState(false)
  const [sysInfoOpen, setSysInfoOpen]     = useState(true)
  const [sysInfoVersion, setSysInfoVersion] = useState(0)
  const [scEntries, setScEntries]         = useState<ScEntry[]>([])
  const [scOpen, setScOpen]               = useState(simpleMode)
  const [favorites, setFavorites]         = useState<Favorite[]>(() => favoritesService.list(credentials.host))
  const [favOpen, setFavOpen]             = useState(true)
  const [svcOpen, setSvcOpen]             = useState(true)
  const [appName, setAppName]             = useState<string | null>(null)
  const [issuesOpen, setIssuesOpen]       = useState(true)
  const [issuesVersion, setIssuesVersion] = useState(0)
  const prevPathRef                        = useRef('')

  useEffect(() => {
    setFavorites(favoritesService.list(credentials.host))
    return favoritesService.onChange(() => setFavorites(favoritesService.list(credentials.host)))
  }, [credentials.host])

  useEffect(() => {
    let cancelled = false
    const isNewPath = prevPathRef.current !== path
    prevPathRef.current = path

    if (isNewPath) {
      setSelfInfo(null)
      setRemoteInfos([])
      setScEntries([])
      setAppName(null)
      setIssuesVersion(v => v + 1)
      const cachePrefix = `${credentials.host}::${path}/Remotes/`
      const hasCached = [...serviceDataCache.keys()].some(k => k.startsWith(cachePrefix))
      setServiceInfoOpen(hasCached || autoLoadServiceInfo || simpleMode)
    }
    setRosterLoading(true)

    async function fetchRoster() {
      const [remotesRes, scRes, appRes] = await Promise.allSettled([
        getNode(credentials, `${path}/Remotes`, 1),
        getNode(credentials, `${path}/servicecontroller`, 2),
        getValue(credentials, `${path}/Deployment/DeploymentInfo/Application`),
      ])
      if (cancelled) return

      setSelfInfo({
        path,
        name:     node.name ?? path.split('/').pop() ?? 'Remote',
        iconData: node.iconData,
      })
      const newInfos = remotesRes.status === 'fulfilled'
        ? (remotesRes.value.children ?? [])
            .map(c => ({ path: `${path}/Remotes/${c.name}`, name: c.name ?? '', iconData: c.iconData }))
        : []
      setRemoteInfos(newInfos)

      const newScEntries: ScEntry[] = scRes.status === 'fulfilled'
        ? (scRes.value.children ?? [])
            .filter(c => c.remoteType === 'ch.minova.service.servicecontroller.ServiceNode' || c.type === 'ch.minova.service.servicecontroller.ServiceNode')
            .map(c => ({
              path: `${path}/servicecontroller/${c.name}`,
              name: c.name ?? '',
              iconData: c.iconData,
              started: c.started === 'true' || c.started === true,
              startable: c.startable === 'true' || c.startable === true,
              logFiles: (c.children ?? [])
                .filter(ch => isLocalFile(ch))
                .map(ch => ({
                  path: `${path}/servicecontroller/${c.name}/${ch.name}`,
                  name: ch.name ?? '',
                  filePath: ch.filePath ?? '',
                })),
            }))
        : []
      setScEntries(newScEntries)

      const newAppName = appRes.status === 'fulfilled' && appRes.value ? appRes.value : null
      setAppName(newAppName)

      setRosterLoading(false)
    }

    fetchRoster()
    return () => { cancelled = true }
  }, [path, credentials, node.name, node.iconData, rosterVersion, autoLoadServiceInfo, simpleMode])

  async function handleScStartStop(entry: ScEntry, start: boolean) {
    try {
      await setValue(credentials, entry.path, String(start), 'started')
      setScEntries(prev => prev.map(e => e.path === entry.path ? { ...e, started: start } : e))
    } catch (err) {
      logStore.add({ severity: 'error', text: err instanceof Error ? err.message : 'Start/stop failed' })
    }
  }

  const isInitialLoad = rosterLoading && !selfInfo

  return (
    <div className="model-preview">
      <div className="mp-toolbar">
        <span className="mp-toolbar-title">Remote Model</span>
        <button
          className="mp-reload-btn"
          onClick={() => {
            remoteInfos.forEach(svc => serviceDataCache.delete(`${credentials.host}::${svc.path}`))
            if (selfInfo) serviceDataCache.delete(`${credentials.host}::${selfInfo.path}`)
            setSysInfoVersion(v => v + 1)
            setIssuesVersion(v => v + 1)
            setRosterVersion(v => v + 1)
          }}
          disabled={rosterLoading}
          title="Reload"
        >
          <IcRefresh />
        </button>
      </div>

      {isInitialLoad ? (
        <div className="mp-loading">Loading…</div>
      ) : (
        <>
          {selfInfo && (
            <SelfPanel
              key={`${selfInfo.path}-${rosterVersion}`}
              info={selfInfo}
              credentials={credentials}
              onNavigate={onNavigate}
            />
          )}

          <button
            className={`mp-service-toggle${sysInfoOpen ? ' mp-service-toggle--open' : ''}`}
            onClick={() => setSysInfoOpen(v => !v)}
          >
            <span className="mp-toggle-arrow">{sysInfoOpen ? '▾' : '▸'}</span>
            <IcMonitor />
            System Info
          </button>
          {sysInfoOpen && (
            <SysInfoPanel
              path={`${path}/SystemInfo`}
              credentials={credentials}
              simpleMode={simpleMode}
              onNavigate={onNavigate}
              version={sysInfoVersion}
            />
          )}

          {appName && (<>
            <button
              className={`mp-service-toggle${issuesOpen ? ' mp-service-toggle--open' : ''}`}
              onClick={() => setIssuesOpen(v => !v)}
            >
              <span className="mp-toggle-arrow">{issuesOpen ? '▾' : '▸'}</span>
              <IcIssues />
              Issues
            </button>
            {issuesOpen && (
              <IssuesPanel
                remotePath={path}
                appName={appName}
                credentials={credentials}
                onNavigate={onNavigate}
                version={issuesVersion}
              />
            )}
          </>)}

          {scEntries.length > 0 && (<>
            <button
              className={`mp-service-toggle${scOpen ? ' mp-service-toggle--open' : ''}`}
              onClick={() => setScOpen(v => !v)}
            >
              <span className="mp-toggle-arrow">{scOpen ? '▾' : '▸'}</span>
              <IcCog />
              Service Controller
              <span className="mp-badge">{scEntries.length}</span>
            </button>
            {scOpen && (
              <div className="mp-sc-list">
                {scEntries.map(entry => (
                  <ScRow
                    key={entry.path}
                    entry={entry}
                    credentials={credentials}
                    onNavigate={onNavigate}
                    onStartStop={handleScStartStop}
                  />
                ))}
              </div>
            )}
          </>)}

          <button
            className={`mp-service-toggle${favOpen ? ' mp-service-toggle--open' : ''}`}
            onClick={() => setFavOpen(v => !v)}
          >
            <span className="mp-toggle-arrow">{favOpen ? '▾' : '▸'}</span>
            <IcStar />
            Favorites
            {(() => { const n = favorites.filter(f => f.path === path || f.path.startsWith(path + '/')).length; return n > 0 && <span className="mp-badge">{n}</span> })()}
          </button>

          {favOpen && (
            <div className="mp-fav-list">
              {(() => {
                const scoped = favorites.filter(f => f.path === path || f.path.startsWith(path + '/'))
                if (scoped.length === 0) return (
                  <div className="mp-fav-empty">No favorites in this model's tree — star items in the detail view.</div>
                )
                return scoped.map(fav => {
                    const onRemove = () => favoritesService.remove(credentials.host, fav.path)
                    if (fav.kind === 'value') return <FavValueRow key={fav.path} fav={fav} credentials={credentials} onRemove={onRemove} />
                    if (fav.kind === 'file')  return <FavFileRow  key={fav.path} fav={fav} credentials={credentials} onNavigate={onNavigate} onRemove={onRemove} />
                    return                            <FavDirRow   key={fav.path} fav={fav} onNavigate={onNavigate} onRemove={onRemove} />
                  })
              })()}
            </div>
          )}

          <button
            className={`mp-service-toggle${svcOpen ? ' mp-service-toggle--open' : ''}`}
            onClick={() => setSvcOpen(v => !v)}
          >
            <span className="mp-toggle-arrow">{svcOpen ? '▾' : '▸'}</span>
            <IcServer />
            Services
            {remoteInfos.length > 0 && <span className="mp-badge">{remoteInfos.length}</span>}
          </button>

          {svcOpen && remoteInfos.length > 0 && (
            <div className="mp-svc-wrap">
              <table className="mp-table mp-table--sub">
                <thead>
                  <tr>
                    <th className="mp-th">Service</th>
                    <th className="mp-th">Memory</th>
                    <th className="mp-th">Uptime</th>
                    <th className="mp-th" title="Working directory">FS</th>
                    <th className="mp-th"></th>
                  </tr>
                </thead>
                <tbody>
                  {remoteInfos.map(svc => (
                    <ServiceRow
                      key={`${svc.path}-${rosterVersion}`}
                      info={svc}
                      credentials={credentials}
                      onNavigate={onNavigate}
                      loadData={serviceInfoOpen}
                    />
                  ))}
                </tbody>
              </table>
              {!serviceInfoOpen && (
                <div className="mp-svc-overlay">
                  <button className="mp-svc-cta" onClick={() => setServiceInfoOpen(true)}>
                    Load service info
                  </button>
                </div>
              )}
            </div>
          )}

          {svcOpen && !rosterLoading && remoteInfos.length === 0 && (
            <div className="mp-fav-empty">No connected services.</div>
          )}
        </>
      )}

      {showJson && (
        <div className="detail-accordion">
          <div className="accordion-header open"><span className="accordion-arrow" />JSON</div>
          <div className="accordion-body">
            <pre className="json-view">{JSON.stringify(node, null, 2)}</pre>
          </div>
        </div>
      )}
    </div>
  )
}
