import { useState, useRef } from 'react'
import type { CommandArg } from '../types/hub'
import type { HubCredentials } from '../types/hub'
import { callCommand, formatBytes, HubApiError } from '../services/hubApi'
import './UploadDialog.css'

/**
 * Raw bytes per chunk. Must fit inside one WebSocket Execute message in node mode:
 * NodeProperties.maxMessageSize defaults to 512 KB; base64 expands by ⌈4/3⌉,
 * so max raw payload = 512 KB × 3/4 = 384 KB — same limit the download side enforces.
 */
const CHUNK_SIZE = (512 * 1024 * 3) / 4  // 384 KB

type Phase = 'idle' | 'uploading' | 'done' | 'stopped'

interface Props {
  commandPath: string
  args: CommandArg[]
  credentials: HubCredentials
  onComplete: () => void
  onClose: () => void
}

export function UploadDialog({ commandPath, args, credentials, onComplete, onClose }: Props) {
  const [file, setFile] = useState<File | null>(null)
  const [fileName, setFileName] = useState('')
  const [phase, setPhase] = useState<Phase>('idle')
  const [uploaded, setUploaded] = useState(0)
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const cancelRef = useRef(false)

  const fileNameParam = args.find(a => a.type === 'string')?.name ?? 'fileName'
  const dataParam     = args.find(a => a.type === 'binary')?.name  ?? 'data'
  const appendParam   = args.find(a => a.type === 'boolean')?.name ?? 'append'

  function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0] ?? null
    setFile(f)
    if (f) setFileName(f.name)
    setError(null)
    setPhase('idle')
    setUploaded(0)
  }

  async function handleUpload() {
    if (!file || !fileName.trim()) return
    cancelRef.current = false
    setPhase('uploading')
    setUploaded(0)
    setError(null)

    try {
      let offset = 0
      let append = false

      while (offset < file.size) {
        if (cancelRef.current) { setPhase('stopped'); return }

        const slice = file.slice(offset, offset + CHUNK_SIZE)
        const ab = await slice.arrayBuffer()

        // Encode raw bytes to base64 in 8 KB sub-chunks to avoid stack overflow
        const bytes = new Uint8Array(ab)
        let binary = ''
        for (let i = 0; i < bytes.length; i += 8192) {
          binary += String.fromCharCode(...bytes.subarray(i, Math.min(i + 8192, bytes.length)))
        }

        await callCommand(credentials, commandPath, {
          [fileNameParam]: fileName.trim(),
          [dataParam]:     btoa(binary),
          [appendParam]:   String(append),
        })

        offset += ab.byteLength
        append = true
        setUploaded(offset)
      }

      setPhase('done')
      onComplete()
    } catch (err) {
      setError(err instanceof HubApiError ? err.message : String(err))
      setPhase('idle')
    }
  }

  function handleStop() {
    cancelRef.current = true
  }

  function handleReset() {
    setPhase('idle')
    setUploaded(0)
    setError(null)
  }

  const total    = file?.size ?? 0
  const pct      = total > 0 ? Math.round((uploaded / total) * 100) : 0
  const title    = phase === 'done' ? 'Upload complete'
                 : phase === 'stopped' ? 'Upload stopped'
                 : 'Upload file'

  return (
    <div className="dialog-overlay" onClick={e => e.target === e.currentTarget && phase !== 'uploading' && onClose()}>
      <div className="dialog-box upload-dialog">
        <div className="dialog-header">
          <span>{title}</span>
          <button className="dialog-close" onClick={phase !== 'uploading' ? onClose : undefined} disabled={phase === 'uploading'}>✕</button>
        </div>

        <div className="upload-body">
          {phase === 'done' ? (
            <div className="upload-done">
              <span className="upload-done-icon">✓</span>
              <span>Uploaded {formatBytes(total)}</span>
            </div>
          ) : phase === 'stopped' ? (
            <div className="upload-stopped">
              <p>Stopped at {formatBytes(uploaded)} of {formatBytes(total)}.</p>
              <p className="upload-note">The partially uploaded file was not removed.</p>
            </div>
          ) : (
            <>
              {/* File picker */}
              <input
                ref={fileInputRef}
                type="file"
                className="upload-file-input-hidden"
                onChange={handleFileChange}
                disabled={phase === 'uploading'}
              />
              <button
                type="button"
                className="btn btn-secondary upload-choose-btn"
                onClick={() => fileInputRef.current?.click()}
                disabled={phase === 'uploading'}
              >
                📁 Choose file…
              </button>

              {/* Filename field */}
              <div className="upload-name-row">
                <label htmlFor="upload-filename" className="upload-label">Save as</label>
                <input
                  id="upload-filename"
                  type="text"
                  className="settings-input"
                  value={fileName}
                  onChange={e => setFileName(e.target.value)}
                  placeholder="filename"
                  disabled={phase === 'uploading'}
                />
              </div>

              {/* Progress (shown while uploading) */}
              {phase === 'uploading' && (
                <div className="upload-progress-area">
                  <div className="upload-progress-track">
                    <div className="upload-progress-fill" style={{ width: `${pct}%` }} />
                  </div>
                  <div className="upload-progress-label">
                    {formatBytes(uploaded)} / {formatBytes(total)} ({pct}%)
                  </div>
                </div>
              )}

              {error && <div className="upload-error">{error}</div>}
            </>
          )}
        </div>

        <div className="dialog-actions">
          {phase === 'uploading' ? (
            <button type="button" className="btn btn-secondary" onClick={handleStop}>■ Stop</button>
          ) : phase === 'done' ? (
            <button type="button" className="btn btn-primary" onClick={onClose}>Close</button>
          ) : phase === 'stopped' ? (
            <>
              <button type="button" className="btn btn-secondary" onClick={onClose}>Close</button>
              <button type="button" className="btn btn-primary" onClick={handleReset}>Upload again</button>
            </>
          ) : (
            <>
              <button type="button" className="btn btn-secondary" onClick={onClose}>Cancel</button>
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleUpload}
                disabled={!file || !fileName.trim()}
              >
                ↑ Upload
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  )
}
